import React from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { InAppLink } from '../../router/InAppLink';
import { navigateInAppPath } from '../../router/navigateInAppPath';
import {
  LinExpandableDateRangeField,
  useNavTitle,
  useAppToast,
} from '@linm-soft-org/linm-web-common-components';
import { Button, Pagination, Slideout, TableCard } from '../../ui';
import JobsListToolbar from './JobsListToolbar';
import {
  jobsService,
  type ImportRunDetail,
  type JobDirection,
  type PlatformEventDetail,
  type PlatformEventQueueSummary,
} from '../../services/jobs';
import { isEventActive } from './jobStatusDisplay';
import { PlatformJobStatus } from './platformJobStatus';
import { JobEventTypeFilter } from './components/JobEventTypeFilter';
import { JobEventQueuePanel } from './components/JobEventQueuePanel';
import { JobEventQueueActions, JobRequeueFailedButton } from './components/JobEventQueueActions';
import { JobEventsTable } from './components/JobEventsTable';
import { JobEventDetailPanel } from './components/JobEventDetailPanel';
import { JobImportRunDetailPanel } from './components/JobImportRunDetailPanel';
import { buildJobsEventsHref } from './jobsEventLinks';
import { AdminPermNavLinks } from '../../components/auth/AdminPermNavLinks';
import styles from './JobInternalPage.module.css';

const PAGE_SIZE = 20;
const SLIDEOUT_WIDTH = '640px';

const formatDate = (iso: string) => new Date(iso).toLocaleString('vi-VN');

const JobEventsPage: React.FC = () => {
  useNavTitle('Danh sách platform events');
  const toast = useAppToast();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();

  /** URL = SSOT for selection + filters (browser back / deep-link). */
  const direction = (searchParams.get('direction') as JobDirection | null) ?? undefined;
  const eventType = searchParams.get('eventType') ?? '';
  const status = searchParams.get('jobStatus') ?? searchParams.get('status') ?? '';
  const page = Math.max(1, Number(searchParams.get('page') || 1));
  const selectedEventId = searchParams.get('eventId');
  const runIdFilter = searchParams.get('runId') ?? '';
  const fromDate = searchParams.get('fromDate') ?? undefined;
  const toDate = searchParams.get('toDate') ?? undefined;
  const searchApplied = searchParams.get('search') ?? '';

  const [eventTypes, setEventTypes] = React.useState<Awaited<ReturnType<typeof jobsService.getEventTypes>>>([]);
  const [queueSummary, setQueueSummary] = React.useState<PlatformEventQueueSummary | null>(null);
  const [loadingQueue, setLoadingQueue] = React.useState(false);
  const [events, setEvents] = React.useState<Awaited<ReturnType<typeof jobsService.getEvents>>['items']>([]);
  const [total, setTotal] = React.useState(0);
  const [loading, setLoading] = React.useState(true);
  const [eventDetail, setEventDetail] = React.useState<PlatformEventDetail | null>(null);
  const [loadingDetail, setLoadingDetail] = React.useState(false);
  const [retention, setRetention] = React.useState<Awaited<ReturnType<typeof jobsService.getEventRetention>> | null>(null);
  const [cleanupPreview, setCleanupPreview] = React.useState<
    Awaited<ReturnType<typeof jobsService.getEventCleanupPreview>> | null
  >(null);
  const [cleanupRunning, setCleanupRunning] = React.useState(false);
  const [linkedRunId, setLinkedRunId] = React.useState<string | null>(null);
  const [linkedRunDetail, setLinkedRunDetail] = React.useState<ImportRunDetail | null>(null);
  const [loadingLinkedRun, setLoadingLinkedRun] = React.useState(false);
  const [searchQuery, setSearchQuery] = React.useState(searchApplied);
  const detailReqRef = React.useRef(0);

  const displayEvents = events;
  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));

  const buildHref = React.useCallback(
    (overrides: {
      eventId?: string | null;
      page?: number;
      eventType?: string;
      jobStatus?: string;
      search?: string;
      fromDate?: string | undefined;
      toDate?: string | undefined;
      runId?: string | null;
    } = {}) =>
      buildJobsEventsHref({
        direction,
        eventType: overrides.eventType !== undefined ? overrides.eventType : eventType,
        jobStatus: overrides.jobStatus !== undefined ? overrides.jobStatus : status,
        search: overrides.search !== undefined ? overrides.search : searchApplied || undefined,
        fromDate: overrides.fromDate !== undefined ? overrides.fromDate : fromDate,
        toDate: overrides.toDate !== undefined ? overrides.toDate : toDate,
        page: overrides.page !== undefined ? overrides.page : page,
        runId: overrides.runId !== undefined ? overrides.runId : runIdFilter || null,
        eventId: overrides.eventId !== undefined ? overrides.eventId : selectedEventId,
      }),
    [direction, eventType, status, searchApplied, fromDate, toDate, page, runIdFilter, selectedEventId],
  );

  /** Filter / pagination → replace (không đẩy history). Selection → push. */
  const replaceHref = React.useCallback(
    (href: string) => navigateInAppPath(href, navigate, { replace: true }),
    [navigate],
  );
  const pushHref = React.useCallback(
    (href: string) => navigateInAppPath(href, navigate),
    [navigate],
  );

  React.useEffect(() => {
    setSearchQuery(searchApplied);
  }, [searchApplied]);

  React.useEffect(() => {
    const timer = window.setTimeout(() => {
      const next = searchQuery.trim();
      if (next === searchApplied) return;
      replaceHref(buildHref({ search: next || undefined, page: 1, eventId: selectedEventId }));
    }, 400);
    return () => window.clearTimeout(timer);
  }, [searchQuery, searchApplied, buildHref, replaceHref, selectedEventId]);

  const loadQueueSummary = React.useCallback(() => {
    setLoadingQueue(true);
    jobsService
      .getEventQueueSummary({ direction, eventType: eventType || undefined })
      .then(setQueueSummary)
      .catch(() => setQueueSummary(null))
      .finally(() => setLoadingQueue(false));
  }, [direction, eventType]);

  const loadEvents = React.useCallback(() => {
    setLoading(true);
    jobsService
      .getEvents({
        page,
        pageSize: PAGE_SIZE,
        direction,
        eventType: eventType || undefined,
        jobStatus: status || undefined,
        runId: runIdFilter || undefined,
        fromUtc: fromDate ? new Date(fromDate).toISOString() : undefined,
        toUtc: toDate ? new Date(toDate + 'T23:59:59.999').toISOString() : undefined,
        search: searchApplied || undefined,
      })
      .then((r) => {
        setEvents(r.items);
        setTotal(r.total);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoading(false));
  }, [page, direction, eventType, status, runIdFilter, fromDate, toDate, searchApplied, toast]);

  const loadDetail = React.useCallback(
    (eventId: string) => {
      const req = ++detailReqRef.current;
      setLoadingDetail(true);
      return jobsService
        .getEvent(eventId)
        .then((detail) => {
          if (req !== detailReqRef.current) return;
          // Chỉ nhận detail đúng id đang chọn (tránh race click nhanh)
          if (detail.eventId !== eventId) return;
          setEventDetail(detail);
        })
        .catch((e: Error) => {
          if (req !== detailReqRef.current) return;
          toast.error(e.message);
          setEventDetail(null);
        })
        .finally(() => {
          if (req !== detailReqRef.current) return;
          setLoadingDetail(false);
        });
    },
    [toast],
  );

  const loadRetention = React.useCallback(() => {
    Promise.all([jobsService.getEventRetention(), jobsService.getEventCleanupPreview()])
      .then(([cfg, preview]) => {
        setRetention(cfg);
        setCleanupPreview(preview);
      })
      .catch(() => undefined);
  }, []);

  React.useEffect(() => {
    jobsService.getEventTypes(direction).then(setEventTypes).catch(() => undefined);
    loadRetention();
  }, [direction, loadRetention]);

  React.useEffect(() => {
    loadEvents();
    loadQueueSummary();
  }, [loadEvents, loadQueueSummary]);

  const selectedEvent = events.find((e) => e.eventId === selectedEventId);
  const selectedIsActive = events.some((e) => e.eventId === selectedEventId && isEventActive(e));
  const detailMatchesSelection =
    Boolean(selectedEventId) && eventDetail?.eventId === selectedEventId;
  const hasActiveListItems = events.some((e) => isEventActive(e));
  const hasQueuedListItems = events.some(
    (e) => (e.jobStatus ?? e.processingStatus) === PlatformJobStatus.Queued || e.processingStatus === 'Pending',
  );

  React.useEffect(() => {
    if (!hasActiveListItems && !hasQueuedListItems) return undefined;
    const t = setInterval(() => {
      loadEvents();
      loadQueueSummary();
    }, 4000);
    return () => clearInterval(t);
  }, [hasActiveListItems, hasQueuedListItems, loadEvents, loadQueueSummary]);

  React.useEffect(() => {
    if (!selectedEventId) {
      detailReqRef.current += 1;
      setEventDetail(null);
      setLoadingDetail(false);
      return undefined;
    }
    // Xóa detail cũ ngay khi đổi id — tránh flash CT/job sai
    setEventDetail((prev) => (prev?.eventId === selectedEventId ? prev : null));
    loadDetail(selectedEventId);
    if (!selectedIsActive) return undefined;
    const t = setInterval(() => {
      loadDetail(selectedEventId);
      loadEvents();
      loadQueueSummary();
    }, 4000);
    return () => clearInterval(t);
  }, [selectedEventId, selectedIsActive, loadDetail, loadEvents, loadQueueSummary]);

  const handleSelectEvent = (eventId: string) => {
    if (eventId === selectedEventId) return;
    pushHref(buildHref({ eventId }));
  };

  const closeEventDetail = () => {
    pushHref(buildHref({ eventId: null }));
  };

  const handleViewQueue = React.useCallback(
    (nextEventType?: string) => {
      replaceHref(
        buildHref({
          eventType: nextEventType ?? eventType,
          jobStatus: PlatformJobStatus.Queued,
          page: 1,
          search: undefined,
          eventId: null,
        }),
      );
      setSearchQuery('');
    },
    [buildHref, eventType, replaceHref],
  );

  const openImportRunSlideout = React.useCallback(
    (runId: string) => {
      setLinkedRunId(runId);
      setLoadingLinkedRun(true);
      jobsService
        .getImportRun(runId)
        .then(setLinkedRunDetail)
        .catch((e: Error) => {
          toast.error(e.message);
          setLinkedRunDetail(null);
        })
        .finally(() => setLoadingLinkedRun(false));
    },
    [toast],
  );

  const closeLinkedRunSlideout = React.useCallback(() => {
    setLinkedRunId(null);
    setLinkedRunDetail(null);
  }, []);

  const handleCleanup = () => {
    setCleanupRunning(true);
    jobsService
      .runEventCleanup()
      .then((r) => {
        toast.success(`Đã xóa ${r.deletedCount} event (trước ${formatDate(r.cutoffUtc)})`);
        loadRetention();
        loadEvents();
        if (selectedEventId) loadDetail(selectedEventId);
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setCleanupRunning(false));
  };

  return (
    <div data-testid="job-events-page">
      <AdminPermNavLinks
        data-testid="job-events-perm-nav"
        style={{ marginBottom: 12 }}
        items={[
          { to: '/admin/jobs', label: '← Job monitoring', permissionCode: 'admin:jobs:hub:read' },
          { to: '/admin/jobs/dashboard', label: 'Dashboard', permissionCode: 'admin:jobs:dashboard:read' },
          {
            to: '/admin/jobs/internal?tab=events',
            label: 'Job nội bộ',
            permissionCode: 'admin:jobs:internal:read',
          },
        ]}
      />

      {retention ? (
        <div
          style={{
            marginBottom: 16,
            padding: 12,
            background: '#f8fafc',
            borderRadius: 8,
            fontSize: 13,
            display: 'flex',
            flexWrap: 'wrap',
            gap: 12,
            alignItems: 'center',
          }}
        >
          <span>
            Cleanup tự động: <strong>{retention.enabled ? 'Bật' : 'Tắt'}</strong> — giữ{' '}
            <strong>{retention.retentionDays}</strong> ngày (mỗi {retention.cleanupIntervalHours}h)
          </span>
          {cleanupPreview ? (
            <span style={{ color: '#64748b' }}>
              Đủ điều kiện xóa: <strong>{cleanupPreview.eligibleCount}</strong> (trước{' '}
              {formatDate(cleanupPreview.cutoffUtc)})
            </span>
          ) : null}
          <Button
            type="button"
            variant="secondary"
            disabled={cleanupRunning || !retention.enabled}
            onClick={handleCleanup}
          >
            {cleanupRunning ? 'Đang dọn…' : 'Dọn ngay'}
          </Button>
        </div>
      ) : null}

      <JobEventQueuePanel
        summary={queueSummary}
        loading={loadingQueue}
        direction={direction}
        onViewQueue={handleViewQueue}
        onRefresh={loadQueueSummary}
      />

      <JobEventQueueActions
        eventType={eventType || undefined}
        direction={direction}
        fromUtc={fromDate ? new Date(fromDate).toISOString() : undefined}
        toUtc={toDate ? new Date(toDate + 'T23:59:59.999').toISOString() : undefined}
        queuedTotal={queueSummary?.queuedTotal ?? 0}
        failedHint={status === PlatformJobStatus.Failed ? total : 0}
        onDone={() => {
          loadQueueSummary();
          loadEvents();
          if (selectedEventId) loadDetail(selectedEventId);
        }}
      />

      <div className={styles.shell}>
        <TableCard
          listShell
          header={
            <div>
              <h4 className={styles.listHeaderTitle}>Platform events ({total})</h4>
              <p className={styles.listHint}>
                Mới nhất trước — mỗi dòng là một loại import (set) khi event là Seed/Import.
                Click dòng mở chi tiết (URL <code>?eventId=</code>). Back trình duyệt đóng/mở lại.
                {runIdFilter ? (
                  <>
                    {' '}
                    Đang lọc run{' '}
                    <code style={{ fontSize: 12 }}>{runIdFilter.slice(0, 8)}…</code>
                    {' · '}
                    <InAppLink to={buildHref({ runId: null, eventId: null })}>Bỏ lọc run</InAppLink>
                  </>
                ) : null}
              </p>
              <JobEventTypeFilter
                eventTypes={eventTypes}
                eventType={eventType}
                onEventTypeChange={(v) => {
                  replaceHref(
                    buildHref({ eventType: v, page: 1, search: undefined, eventId: null }),
                  );
                  setSearchQuery('');
                }}
                status={status}
                onStatusChange={(v) => {
                  replaceHref(
                    buildHref({ jobStatus: v, page: 1, search: undefined, eventId: null }),
                  );
                  setSearchQuery('');
                }}
              />
              <JobsListToolbar
                searchQuery={searchQuery}
                onSearchChange={setSearchQuery}
                searchPlaceholder="Tìm set import, eventId, sourceId, documentKey, connector, lỗi…"
                searchTestId="job-events-search"
                onRefresh={loadEvents}
                refreshDisabled={loading}
                extraActions={
                  <JobRequeueFailedButton
                    eventType={eventType || undefined}
                    direction={direction}
                    fromUtc={fromDate ? new Date(fromDate).toISOString() : undefined}
                    toUtc={toDate ? new Date(toDate + 'T23:59:59.999').toISOString() : undefined}
                    failedCount={status === PlatformJobStatus.Failed ? total : 0}
                    onDone={() => {
                      loadQueueSummary();
                      loadEvents();
                      if (selectedEventId) loadDetail(selectedEventId);
                    }}
                  />
                }
                totalCount={total}
                filteredCount={displayEvents.length}
                loading={loading}
                itemLabel="dòng"
              />
              <div style={{ marginTop: 8 }}>
                <LinExpandableDateRangeField
                  label="Thời gian tạo event"
                  fromDate={fromDate}
                  toDate={toDate}
                  onChange={(f, t) => {
                    replaceHref(
                      buildHref({
                        fromDate: f,
                        toDate: t,
                        page: 1,
                        eventId: selectedEventId,
                      }),
                    );
                  }}
                  testId="job-event-date-filter"
                />
              </div>
            </div>
          }
          footer={
            !loading && events.length > 0 ? (
              <Pagination
                currentPage={page}
                totalPages={totalPages}
                totalCount={total}
                pageSize={PAGE_SIZE}
                itemLabel="event"
                onPageChange={(p) => replaceHref(buildHref({ page: p, eventId: selectedEventId }))}
              />
            ) : undefined
          }
        >
          <div className={styles.eventsTableWrap}>
            {loading && events.length === 0 ? (
              <p className={styles.gridLoading}>Đang tải…</p>
            ) : displayEvents.length === 0 ? (
              <p className={styles.gridEmpty}>
                {searchQuery.trim() ? 'Không tìm thấy event phù hợp.' : 'Không có event'}
              </p>
            ) : (
              <JobEventsTable
                events={displayEvents}
                selectedEventId={selectedEventId}
                eventHref={(eventId) => buildHref({ eventId })}
                onSelectEvent={handleSelectEvent}
              />
            )}
          </div>
        </TableCard>
      </div>

      <Slideout
        isOpen={Boolean(selectedEventId)}
        onClose={closeEventDetail}
        title="Chi tiết event"
        width={SLIDEOUT_WIDTH}
        data-testid="job-event-detail-slideout"
        customFooter={
          <button type="button" className={styles.closeBtn} onClick={closeEventDetail}>
            Đóng
          </button>
        }
      >
        <div className={styles.slideoutBody}>
          {!selectedEventId ? (
            <p style={{ color: '#64748b' }}>Chọn một dòng để xem chi tiết.</p>
          ) : loadingDetail && !detailMatchesSelection ? (
            <p>Đang tải…</p>
          ) : detailMatchesSelection && eventDetail ? (
            <JobEventDetailPanel
              detail={eventDetail}
              onOpenImportRun={openImportRunSlideout}
              onRequeued={() => {
                loadEvents();
                loadQueueSummary();
                if (selectedEventId) loadDetail(selectedEventId);
              }}
            />
          ) : (
            <p style={{ color: '#64748b' }}>Không tải được chi tiết.</p>
          )}
        </div>
      </Slideout>

      <Slideout
        isOpen={Boolean(linkedRunId)}
        onClose={closeLinkedRunSlideout}
        title="Chi tiết / tiến độ import"
        width={SLIDEOUT_WIDTH}
        data-testid="job-event-linked-import-slideout"
        customFooter={
          <button type="button" className={styles.closeBtn} onClick={closeLinkedRunSlideout}>
            Đóng
          </button>
        }
      >
        <div className={styles.slideoutBody}>
          <JobImportRunDetailPanel
            runDetail={linkedRunDetail}
            loading={loadingLinkedRun}
            showEventsLink={false}
          />
        </div>
      </Slideout>
    </div>
  );
};

export default JobEventsPage;
