import React from 'react';
import { InAppLink } from '../../router/InAppLink';
import JobParallelismQueueWarningBanner from './JobParallelismQueueWarningBanner';
import styles from './DataSyncSetConfigPage.module.css';

export type JobSyncBatchConfigSummaryProps = {
  configKey: string;
  searchLaneCount: number;
  detailParallelJobs: number;
  concurrentDetailBatches?: number;
  detailImportConcurrency?: number;
  maxActivePlatformEvents?: number;
  lowWorkerPickCapacity?: number | null;
  loadingLowWorkers?: boolean;
};

/** Tab Job sync — map field UI ↔ optionsJson ↔ ExternalDetailBatchRequested. */
export const JobSyncBatchConfigSummary: React.FC<JobSyncBatchConfigSummaryProps> = ({
  configKey,
  searchLaneCount,
  detailParallelJobs,
  concurrentDetailBatches = 2,
  detailImportConcurrency = 16,
  maxActivePlatformEvents = 20,
  lowWorkerPickCapacity,
  loadingLowWorkers,
}) => {
  const lanes = Math.max(1, searchLaneCount);
  const perBatch = Math.max(1, detailParallelJobs);
  const concurrent = Math.max(1, concurrentDetailBatches);
  const importDeg = Math.max(1, detailImportConcurrency);
  const eventBudget = Math.min(20, Math.max(2, maxActivePlatformEvents));
  /** Docs đang claim Processing tối đa — KHÔNG = số platform job. */
  const docsCap = lanes * perBatch * concurrent;
  /** Peak planned ≈ lanes × (1 search + concurrent detail batches). */
  const plannedPeak = lanes * (1 + concurrent);
  /** Cap so sánh worker: min(plannedPeak, eventBudget) — BE hard-gate ≤ eventBudget. */
  const eventCap = Math.min(plannedPeak, eventBudget);

  return (
    <div className={styles.batchConfigPanel} data-testid="job-sync-batch-config-summary">
      <strong>Cấu hình detail batch (SSOT)</strong>
      <p className={styles.batchConfigMeta}>
        Lưu vào bảng <code>data_sync_set_configs</code> · cột <code>optionsJson</code> · row global{' '}
        <code>companyCode = null</code> · key <code>{configKey}</code>.
        {' '}
        Run mới đọc snapshot lúc Resync — sửa field → <strong>Lưu</strong> → Resync lại.
      </p>
      <table className={styles.batchConfigTable}>
        <tbody>
          <tr>
            <th align="left">Field UI</th>
            <th align="left">JSON key</th>
            <th align="right">Giá trị</th>
          </tr>
          <tr>
            <td>Số leader (search)</td>
            <td>
              <code>searchLaneCount</code>
            </td>
            <td align="right">{lanes}</td>
          </tr>
          <tr>
            <td>CT / 1 batch event (= 1 POS call)</td>
            <td>
              <code>detailBatchSize</code> (alias <code>detailParallelJobs</code>)
            </td>
            <td align="right">
              <strong>{perBatch}</strong>
            </td>
          </tr>
          <tr>
            <td>Batch event song song / lane</td>
            <td>
              <code>concurrentDetailBatches</code>
            </td>
            <td align="right">{concurrent}</td>
          </tr>
          <tr>
            <td>CPU import trong 1 batch</td>
            <td>
              <code>detailImportConcurrency</code>
            </td>
            <td align="right">{importDeg}</td>
          </tr>
          <tr>
            <td>Hard cap event / run</td>
            <td>
              <code>maxActivePlatformEvents</code>
            </td>
            <td align="right">
              <strong>{eventBudget}</strong>
            </td>
          </tr>
          <tr>
            <td>Planned peak event</td>
            <td>
              <code>lanes × (1 + concurrentBatches)</code>
            </td>
            <td align="right">
              {plannedPeak}
              {plannedPeak > eventBudget ? ' → clamp ≤ budget' : ''}
            </td>
          </tr>
          <tr>
            <td>Max docs claim (Processing)</td>
            <td>
              <code>maxInFlightDocsTotal</code>
            </td>
            <td align="right">
              {docsCap} ({lanes}×{perBatch}×{concurrent})
            </td>
          </tr>
        </tbody>
      </table>
      <p className={styles.batchConfigFlow}>
        Đúng: claim {perBatch} checkpoint → <strong>1</strong>{' '}
        <code>ExternalDetailBatchRequested</code> → <strong>1</strong> POST{' '}
        <code>ChiTiet*Batch</code> <code>{'{'} ids: [{perBatch}] {'}'}</code> → import trong batch
        (CPU degree {importDeg}).
        {' '}
        BE hard-gate: active search/detail/batch ≤ <strong>{eventBudget}</strong>.
        {' '}
        Gợi ý an toàn: lanes=2 · concurrent=1 · batch=100 → peak≈4.
        {' '}
        <strong>Sai:</strong> hiểu {perBatch} CT = {perBatch} job song song / so worker với {docsCap}{' '}
        docs.
      </p>
      <p className={styles.batchConfigMeta}>
        Worker Low pick:{' '}
        {loadingLowWorkers ? (
          'đang đọc…'
        ) : lowWorkerPickCapacity != null ? (
          <>
            <strong>{lowWorkerPickCapacity}</strong> — so với{' '}
            <strong>{eventCap} platform event</strong> (không so {docsCap} docs)
            {' '}(
            <code>LowWorkerInstanceCount × cluster</code> —{' '}
            <InAppLink to="/admin/jobs/server-config">Cấu hình worker</InAppLink>)
          </>
        ) : (
          <>
            chưa đọc được — xem{' '}
            <InAppLink to="/admin/jobs/server-config">Cấu hình worker</InAppLink>
          </>
        )}
        .
      </p>
      <JobParallelismQueueWarningBanner
        configuredCap={eventCap}
        detailBatchSize={perBatch}
        lowWorkerPickCapacity={lowWorkerPickCapacity}
        loadingWorkers={loadingLowWorkers}
        context="sync"
        testId="connector-sync-parallelism-warning"
      />
    </div>
  );
};

export default JobSyncBatchConfigSummary;
