import { apiClient } from '../../services/api';

export type PlatformLoginDevice = {
  userId: string;
  accountName: string;
  fullName: string;
  employeeId: string;
  deviceId: string;
  label: string;
  signedInAt: string;
  lastSeenAt: string;
  ipAddress: string;
};

export type UserLoginEvent = {
  id: string;
  userId: string;
  accountName: string;
  fullName: string;
  employeeId: string;
  deviceId: string;
  deviceLabel: string;
  ipAddress: string;
  loggedInAt: string;
};

function text(row: Record<string, unknown>, key: string): string {
  const value = row[key] ?? row[key.charAt(0).toUpperCase() + key.slice(1)];
  return typeof value === 'string' ? value : '';
}

function asRows(body: unknown): Record<string, unknown>[] {
  if (Array.isArray(body)) return body.filter((row) => row && typeof row === 'object') as Record<string, unknown>[];
  if (body && typeof body === 'object') {
    const data = (body as { data?: unknown }).data;
    if (Array.isArray(data)) return data.filter((row) => row && typeof row === 'object') as Record<string, unknown>[];
  }
  return [];
}

export async function listPlatformDevices(search: string): Promise<PlatformLoginDevice[]> {
  const query = search.trim() ? `?search=${encodeURIComponent(search.trim())}` : '';
  const body = await apiClient.get<unknown>(`/admin/login-devices${query}`);
  return asRows(body).map((row) => ({
    userId: text(row, 'userId'),
    accountName: text(row, 'accountName'),
    fullName: text(row, 'fullName'),
    employeeId: text(row, 'employeeId'),
    deviceId: text(row, 'deviceId'),
    label: text(row, 'label'),
    signedInAt: text(row, 'signedInAt'),
    lastSeenAt: text(row, 'lastSeenAt'),
    ipAddress: text(row, 'ipAddress'),
  }));
}

export async function listLoginHistory(search: string): Promise<UserLoginEvent[]> {
  const query = search.trim() ? `?search=${encodeURIComponent(search.trim())}` : '';
  const body = await apiClient.get<unknown>(`/admin/login-history${query}`);
  return asRows(body).map((row) => ({
    id: text(row, 'id'),
    userId: text(row, 'userId'),
    accountName: text(row, 'accountName'),
    fullName: text(row, 'fullName'),
    employeeId: text(row, 'employeeId'),
    deviceId: text(row, 'deviceId'),
    deviceLabel: text(row, 'deviceLabel'),
    ipAddress: text(row, 'ipAddress'),
    loggedInAt: text(row, 'loggedInAt'),
  }));
}
