import React, { useCallback, useEffect, useState } from 'react';
import { localInputToISOWithOffset, useAppToast, useNavTitle } from '@linm-soft-org/linm-web-common-components';
import { useFormOptions } from '../../hooks/useFormOptions';
import { useAdminPermissions } from '../../hooks/useAdminPermissions';
import { AdminPerm, hasAdminPagePermission } from '../../config/adminPermissions';
import { goLiveCleanupService } from '../../services/goLiveCleanup';
import type { GoLiveCleanupPeriod } from '../../services/goLiveCleanup/endpoint';
import type {
  GoLiveCleanupCardDto,
  GoLiveCleanupExecuteResultDto,
  GoLiveCleanupPreviewDto,
} from '../../services/goLiveCleanup/responseModel';
import styles from './GoLiveCleanupPage.module.css';

function periodQuery(from: string, to: string): GoLiveCleanupPeriod {
  const query: GoLiveCleanupPeriod = {};
  if (from) query.dateFrom = localInputToISOWithOffset(`${from}T00:00:00`);
  const end = to || from;
  if (end) query.dateTo = localInputToISOWithOffset(`${end}T23:59:59`);
  return query;
}

function csvCell(value: string): string {
  const text = value ?? '';
  if (/[",\n]/.test(text)) return `"${text.replace(/"/g, '""')}"`;
  return text;
}

function downloadCard(card: GoLiveCleanupCardDto) {
  const headers = card.downloadHeaders ?? [];
  const rows = card.downloadRows ?? [];
  if (headers.length === 0) return;
  const lines = [headers, ...rows].map((cols) => cols.map(csvCell).join(',')).join('\n');
  const blob = new Blob([`\uFEFF${lines}`], { type: 'text/csv;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const link = document.createElement('a');
  link.href = url;
  link.download = card.downloadFileName || 'keep-users.csv';
  link.click();
  URL.revokeObjectURL(url);
}

const GoLiveCleanupPage: React.FC = () => {
  useFormOptions('admin-go-live-cleanup');
  const toast = useAppToast();
  const { hasPermission } = useAdminPermissions();
  const canWrite = hasAdminPagePermission(hasPermission, AdminPerm.dataCleanupWrite);

  const [preview, setPreview] = useState<GoLiveCleanupPreviewDto | null>(null);
  const [checked, setChecked] = useState<Record<string, string[]>>({});
  const [loading, setLoading] = useState(true);
  const [busyKey, setBusyKey] = useState('');
  const [pendingCard, setPendingCard] = useState('');
  const [phrase, setPhrase] = useState('');
  const [result, setResult] = useState<GoLiveCleanupExecuteResultDto | null>(null);
  const [errorMsg, setErrorMsg] = useState('');
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [period, setPeriod] = useState<GoLiveCleanupPeriod>({});

  useNavTitle(preview?.title ?? '');

  const load = useCallback(async (next: GoLiveCleanupPeriod) => {
    setLoading(true);
    setErrorMsg('');
    try {
      const data = await goLiveCleanupService.preview(next);
      const next: Record<string, string[]> = {};
      for (const card of data.cards ?? []) {
        next[card.key] = (card.items ?? []).filter((item) => item.checked).map((item) => item.key);
      }
      setPreview(data);
      setChecked(next);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '';
      setErrorMsg(message);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    const timer = window.setTimeout(() => {
      void load({});
    }, 0);
    return () => window.clearTimeout(timer);
  }, [load]);

  const toggle = (cardKey: string, itemKey: string) => {
    setChecked((current) => {
      const list = current[cardKey] ?? [];
      const has = list.includes(itemKey);
      return {
        ...current,
        [cardKey]: has ? list.filter((key) => key !== itemKey) : [...list, itemKey],
      };
    });
  };

  const toggleAll = (cardKey: string, itemKeys: string[], on: boolean) => {
    setChecked((current) => ({ ...current, [cardKey]: on ? itemKeys : [] }));
  };

  const runCard = async () => {
    if (!preview || !pendingCard || !canWrite) return;
    if (phrase !== preview.confirmPhrase) {
      toast.error(preview.confirmMismatch);
      return;
    }
    const itemKeys = checked[pendingCard] ?? [];
    setBusyKey(pendingCard);
    setErrorMsg('');
    try {
      const data = await goLiveCleanupService.execute({
        confirmPhrase: phrase,
        cardKey: pendingCard,
        itemKeys,
        dateFrom: period.dateFrom,
        dateTo: period.dateTo,
      });
      setResult(data);
      toast.success(data.message);
      setPendingCard('');
      setPhrase('');
      await load(period);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '';
      setErrorMsg(message);
      toast.error(message);
    } finally {
      setBusyKey('');
    }
  };

  return (
    <div className={styles.page} data-testid="admin-go-live-cleanup-page">
      <header className={styles.header}>
        <h1 className={styles.title}>{preview?.title}</h1>
        {preview?.summary ? <p className={styles.summary}>{preview.summary}</p> : null}
      </header>

      {preview ? (
        <form
          className={styles.period}
          onSubmit={(event) => {
            event.preventDefault();
            const next = periodQuery(dateFrom, dateTo);
            setPeriod(next);
            void load(next);
          }}
        >
          <label>
            {preview.dateFromLabel}
            <input type="date" value={dateFrom} onChange={(event) => setDateFrom(event.target.value)} />
          </label>
          <label>
            {preview.dateToLabel}
            <input type="date" value={dateTo} onChange={(event) => setDateTo(event.target.value)} />
          </label>
          <button type="submit" className={`${styles.btn} ${styles.btnGhost}`}>
            {preview.applyLabel}
          </button>
          {preview.dateHint ? <p className={styles.hint}>{preview.dateHint}</p> : null}
        </form>
      ) : null}

      {errorMsg ? <p className={styles.empty}>{errorMsg}</p> : null}

      {loading ? null : (
        <div className={styles.cards}>
          {(preview?.cards ?? []).map((card) => {
            const selected = checked[card.key] ?? [];
            const itemKeys = (card.items ?? []).map((item) => item.key);
            const allOn = itemKeys.length > 0 && itemKeys.every((key) => selected.includes(key));
            return (
              <section
                key={card.key}
                className={`${styles.card} ${card.canCleanup ? styles.cardDrop : styles.cardKeep}`}
                data-testid={`cleanup-card-${card.key}`}
              >
                <h2 className={styles.cardTitle}>{card.title}</h2>
                {card.hint ? <p className={styles.hint}>{card.hint}</p> : null}
                {card.canCleanup && (card.items ?? []).length > 0 ? (
                  <div className={styles.toolbar}>
                    <label>
                      <input
                        type="checkbox"
                        checked={allOn}
                        onChange={(event) => toggleAll(card.key, itemKeys, event.target.checked)}
                      />
                      {' '}
                      {card.selectAllLabel}
                    </label>
                    <button
                      type="button"
                      className={`${styles.btn} ${styles.btnDanger}`}
                      disabled={!canWrite || selected.length === 0 || busyKey === card.key}
                      onClick={() => {
                        setPhrase('');
                        setPendingCard(card.key);
                      }}
                    >
                      {card.actionLabel}
                    </button>
                  </div>
                ) : null}
                {(card.downloadHeaders ?? []).length > 0 ? (
                  <div className={styles.toolbar}>
                    <span />
                    <button
                      type="button"
                      className={`${styles.btn} ${styles.btnGhost}`}
                      onClick={() => downloadCard(card)}
                    >
                      {card.downloadLabel}
                    </button>
                  </div>
                ) : null}
                {(card.items ?? []).length === 0 ? (
                  <p className={styles.empty}>{card.emptyLabel}</p>
                ) : (
                  <ul className={styles.list}>
                    {(card.items ?? []).map((item) => (
                      <li key={item.key} className={styles.row}>
                        {card.canCleanup ? (
                          <input
                            type="checkbox"
                            checked={selected.includes(item.key)}
                            onChange={() => toggle(card.key, item.key)}
                            aria-label={item.label}
                          />
                        ) : null}
                        <span className={styles.rowMain}>
                          <span>
                            <span className={styles.label}>{item.label}</span>
                            {item.detail ? <span className={styles.detail}>{item.detail}</span> : null}
                          </span>
                          {item.code ? (
                            <span className={styles.code}>
                              {item.code}
                              {item.copyLabel ? (
                                <button
                                  type="button"
                                  className={`${styles.btn} ${styles.btnGhost}`}
                                  onClick={() => {
                                    void navigator.clipboard.writeText(item.code).then(() => {
                                      if (preview?.copiedMessage) toast.success(preview.copiedMessage);
                                    });
                                  }}
                                >
                                  {item.copyLabel}
                                </button>
                              ) : null}
                            </span>
                          ) : null}
                        </span>
                      </li>
                    ))}
                  </ul>
                )}
              </section>
            );
          })}
        </div>
      )}

      {result ? (
        <div className={styles.result}>
          <strong>{result.message}</strong>
          <ul>
            {(result.items ?? []).map((item) => (
              <li key={item.key}>
                {item.label}: {item.count}
              </li>
            ))}
          </ul>
        </div>
      ) : null}

      {preview && pendingCard ? (
        <div className={styles.backdrop}>
          <div className={styles.modal} role="dialog">
            <h3>{preview.confirmTitle}</h3>
            <p>{preview.confirmHint}</p>
            <p>
              <strong>{preview.confirmPhrase}</strong>
            </p>
            <input
              value={phrase}
              onChange={(event) => setPhrase(event.target.value)}
              autoFocus
            />
            <div className={styles.modalActions}>
              <button
                type="button"
                className={`${styles.btn} ${styles.btnGhost}`}
                onClick={() => {
                  setPendingCard('');
                  setPhrase('');
                }}
              >
                {preview.cancelLabel}
              </button>
              <button
                type="button"
                className={`${styles.btn} ${styles.btnDanger}`}
                disabled={phrase !== preview.confirmPhrase || busyKey.length > 0}
                onClick={() => {
                  void runCard();
                }}
              >
                {preview.confirmActionLabel}
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
};

export default GoLiveCleanupPage;
