/**
 * Quản lý API key — inbound camera ingest.
 * Secret = Name (hash trên Auth). Bật/tắt — không xoay. Bảng = đúng field Auth DB.
 */
import React, { useCallback, useEffect, useRef, useState } from 'react';
import {
  LeaveConfirmModal,
  useAppToast,
  useDirtyTracking,
  useNavTitle,
} from '@linm-soft-org/linm-web-common-components';
import { Button, Input, Modal, SearchTextInput, Select, TableCard } from '../../ui';
import { useActiveStatusOptions } from '../../hooks/useAdminFormOptions';
import { useAdminPermissions } from '../../hooks/useAdminPermissions';
import { AdminPerm } from '../../config/adminPermissions';
import { apiKeysService, type ApiKeyListItem } from '../../services/apiKeys';
import { apiClient } from '../../services/api';
import { isAdminPermissionsBypass } from '../../dev/isAdminPermissionsBypass';
import {
  formatUTCToLocalDisplay,
  localInputToISOWithOffset,
  utcToLocalInputValue,
} from '../../utils/dateTime';
import catalog from '../orgCatalog/orgCatalog.module.css';
import styles from './ApiKeysManagementPage.module.css';

async function ensureApiKeysPermissionCache(): Promise<void> {
  if (isAdminPermissionsBypass()) return;
  try {
    await apiClient.get('/admin/users/me/permissions?currentPath=/admin/api-keys');
  } catch {
    /* best-effort */
  }
}

type FormMode = 'create' | 'edit' | 'view';

interface KeyForm {
  name: string;
  companyCode: string;
  scopes: string;
  allowedIpAddresses: string;
  expiresAt: string;
  isActive: boolean;
}

function defaultExpiresLocal(): string {
  const d = new Date();
  d.setDate(d.getDate() + 365);
  return utcToLocalInputValue(d.toISOString());
}

function emptyForm(): KeyForm {
  return {
    name: '',
    companyCode: 'RMMS',
    scopes: 'camera:ingest',
    allowedIpAddresses: '',
    expiresAt: defaultExpiresLocal(),
    isActive: true,
  };
}

function rowToForm(row: ApiKeyListItem): KeyForm {
  return {
    name: row.name ?? '',
    companyCode: row.companyCode ?? '',
    scopes: row.scopes ?? '',
    allowedIpAddresses: row.allowedIpAddresses ?? '',
    expiresAt: utcToLocalInputValue(row.expiresAt),
    isActive: row.isActive && !row.revokedAt,
  };
}

const ApiKeysManagementPage: React.FC = () => {
  useNavTitle('Quản lý API key');
  const toast = useAppToast();
  const { hasPermission } = useAdminPermissions();
  const canWrite = hasPermission(AdminPerm.apiKeysWrite);
  const { getActiveLabel, options: statusOptions } = useActiveStatusOptions();

  const [items, setItems] = useState<ApiKeyListItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [includeInactive, setIncludeInactive] = useState(true);

  const [formOpen, setFormOpen] = useState(false);
  const [formMode, setFormMode] = useState<FormMode>('create');
  const [editing, setEditing] = useState<ApiKeyListItem | null>(null);
  const [form, setForm] = useState<KeyForm>(emptyForm);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const [formDirty, setFormDirty] = useState(false);
  const [leaveOpen, setLeaveOpen] = useState(false);
  const { markDirty, markClean } = useDirtyTracking(setFormDirty);

  const [plainOpen, setPlainOpen] = useState(false);
  const [plainValue, setPlainValue] = useState('');
  const [revokeTarget, setRevokeTarget] = useState<ApiKeyListItem | null>(null);
  const [revoking, setRevoking] = useState(false);
  const [enablingId, setEnablingId] = useState<string | null>(null);
  const cancelRef = useRef(false);

  const locked = formMode === 'view';

  const load = useCallback(async () => {
    setLoading(true);
    try {
      await ensureApiKeysPermissionCache();
      const rows = await apiKeysService.list({
        search: appliedSearch,
        includeInactive,
      });
      if (!cancelRef.current) setItems(rows);
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể tải danh sách API key');
    } finally {
      if (!cancelRef.current) setLoading(false);
    }
  }, [appliedSearch, includeInactive, toast]);

  useEffect(() => {
    cancelRef.current = false;
    const t = setTimeout(() => {
      load();
    }, 0);
    return () => {
      clearTimeout(t);
      cancelRef.current = true;
    };
  }, [load]);

  const applySearch = () => {
    setAppliedSearch(search.trim());
  };

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm());
    setFieldErrors({});
    setFormMode('create');
    markClean();
    setFormOpen(true);
  };

  const openForm = (row: ApiKeyListItem, mode: FormMode) => {
    setEditing(row);
    setForm(rowToForm(row));
    setFieldErrors({});
    setFormMode(mode);
    markClean();
    setFormOpen(true);
    void apiKeysService
      .getById(row.id)
      .then((fresh) => {
        setEditing(fresh);
        setForm(rowToForm(fresh));
        markClean();
      })
      .catch(() => {
        /* list row already shown */
      });
  };

  const actuallyCloseForm = () => {
    setFormOpen(false);
    setLeaveOpen(false);
    markClean();
  };

  const closeForm = () => {
    if (saving) return;
    if (!locked && formDirty) {
      setLeaveOpen(true);
      return;
    }
    actuallyCloseForm();
  };

  const patchForm = (patch: Partial<KeyForm>) => {
    markDirty();
    setForm((f) => ({ ...f, ...patch }));
  };

  const validate = (): boolean => {
    const next: Record<string, string> = {};
    if (!form.name.trim()) next.name = 'Tên key là bắt buộc';
    if (!form.companyCode.trim()) next.companyCode = 'Mã đơn vị là bắt buộc';
    if (!form.scopes.trim()) next.scopes = 'Scope là bắt buộc';
    setFieldErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSave = async () => {
    if (locked || !canWrite) return;
    if (!validate()) return;
    setSaving(true);
    try {
      const expiresAt = form.expiresAt ? localInputToISOWithOffset(form.expiresAt) : undefined;
      const payload = {
        name: form.name.trim(),
        companyCode: form.companyCode.trim().toUpperCase() || 'RMMS',
        scopes: form.scopes.trim() || 'camera:ingest',
        allowedIpAddresses: form.allowedIpAddresses.trim() || undefined,
        expiresAt,
      };
      if (editing) {
        await apiKeysService.update(editing.id, { ...payload, isActive: form.isActive });
        toast.success('Đã cập nhật API key');
        actuallyCloseForm();
      } else {
        const created = await apiKeysService.create(payload);
        actuallyCloseForm();
        setPlainValue(created.name || created.apiKey);
        setPlainOpen(true);
      }
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể lưu API key');
    } finally {
      setSaving(false);
    }
  };

  const handleEnable = async (row: ApiKeyListItem) => {
    if (!canWrite) return;
    setEnablingId(row.id);
    try {
      await apiKeysService.update(row.id, {
        name: row.name,
        companyCode: row.companyCode,
        scopes: row.scopes,
        allowedIpAddresses: row.allowedIpAddresses ?? undefined,
        expiresAt: row.expiresAt ?? undefined,
        isActive: true,
      });
      toast.success('Đã bật API key');
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể bật API key');
    } finally {
      setEnablingId(null);
    }
  };

  const handleRevoke = async () => {
    if (!canWrite || !revokeTarget) return;
    setRevoking(true);
    try {
      await apiKeysService.revoke(revokeTarget.id);
      toast.success('Đã tắt API key');
      setRevokeTarget(null);
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể thu hồi API key');
    } finally {
      setRevoking(false);
    }
  };

  const copyPlain = async () => {
    try {
      await navigator.clipboard.writeText(plainValue);
      toast.success('Đã sao chép API key');
    } catch {
      toast.error('Không sao chép được — hãy chọn và copy thủ công');
    }
  };

  const statusLabel = (row: ApiKeyListItem) => {
    if (row.revokedAt || !row.isActive) return getActiveLabel(false);
    return getActiveLabel(true);
  };

  const rowActive = (row: ApiKeyListItem) => row.isActive && !row.revokedAt;

  const modalTitle =
    formMode === 'create' ? 'Tạo API key' : formMode === 'edit' ? 'Chỉnh sửa API key' : 'Xem API key';

  const statusSelectOptions =
    statusOptions.length >= 2
      ? statusOptions
      : [
          { value: 'active', label: 'Hoạt động' },
          { value: 'inactive', label: 'Ngừng hoạt động' },
        ];

  return (
    <div className={catalog.page} data-testid="admin-apikeys-page">
      <div className={catalog.header}>
        <div>
          <h1 className={catalog.title}>
            <i className="fas fa-key" /> Quản lý API key
          </h1>
          <p className={catalog.hint}>
            Tên key = <code>apiKey</code> trên camera. Hash trên Auth. Bật/tắt trạng thái — không xoay
            secret. Bảng hiển thị đúng field từ Auth DB.
          </p>
        </div>
        <div className={catalog.headerActions}>
          <SearchTextInput
            value={search}
            onChange={setSearch}
            onSearch={applySearch}
            placeholder="Tìm tên, đơn vị, scope, IP"
            testId="admin-apikeys-search"
          />
          <Button
            variant={includeInactive ? 'secondary' : 'primary'}
            onClick={() => setIncludeInactive((v) => !v)}
          >
            {includeInactive ? 'Tất cả' : 'Đang hoạt động'}
          </Button>
          <Button
            variant="secondary"
            onClick={() => {
              const next = search.trim();
              if (next === appliedSearch) load();
              else setAppliedSearch(next);
            }}
            disabled={loading}
          >
            <i className="fas fa-rotate" /> Làm mới
          </Button>
          {canWrite && (
            <Button variant="primary" onClick={openCreate} data-testid="admin-apikeys-create">
              <i className="fas fa-plus" /> Tạo API key
            </Button>
          )}
        </div>
      </div>

      {loading ? (
        <TableCard>
          <div className={catalog.emptyState}>
            <i className="fas fa-spinner fa-spin" />
            Đang tải…
          </div>
        </TableCard>
      ) : items.length === 0 ? (
        <TableCard>
          <div className={catalog.emptyState}>
            <i className="fas fa-key" />
            Chưa có API key
          </div>
        </TableCard>
      ) : (
        <TableCard>
          <div className={catalog.tableWrapper}>
            <table className={catalog.table}>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Tên</th>
                  <th>Đơn vị</th>
                  <th>Scope</th>
                  <th>IP cho phép</th>
                  <th>Trạng thái</th>
                  <th>Hết hạn</th>
                  <th>Dùng lần cuối</th>
                  <th className={catalog.actionsCell}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {items.map((row, idx) => (
                  <tr
                    key={row.id}
                    className={catalog.clickableRow}
                    onClick={() => openForm(row, 'view')}
                  >
                    <td>{idx + 1}</td>
                    <td>
                      <span className={catalog.codeBadge}>{row.name}</span>
                    </td>
                    <td>{row.companyCode}</td>
                    <td>{row.scopes}</td>
                    <td>{row.allowedIpAddresses || <span className={catalog.na}>—</span>}</td>
                    <td>
                      <span
                        className={`${catalog.statusBadge} ${
                          rowActive(row) ? catalog.active : catalog.inactive
                        }`}
                      >
                        {statusLabel(row)}
                      </span>
                    </td>
                    <td>{formatUTCToLocalDisplay(row.expiresAt)}</td>
                    <td>{formatUTCToLocalDisplay(row.lastUsedAt)}</td>
                    <td className={styles.actionsCell} onClick={(e) => e.stopPropagation()}>
                      <button
                        type="button"
                        className={catalog.viewBtn}
                        title="Xem"
                        onClick={() => openForm(row, 'view')}
                      >
                        <i className="fas fa-eye" />
                      </button>
                      {canWrite && (
                        <button
                          type="button"
                          className={catalog.editBtn}
                          title="Sửa"
                          onClick={() => openForm(row, 'edit')}
                        >
                          <i className="fas fa-pen" />
                        </button>
                      )}
                      {canWrite && rowActive(row) && (
                        <button
                          type="button"
                          className={catalog.deleteBtn}
                          title="Tắt"
                          onClick={() => setRevokeTarget(row)}
                        >
                          <i className="fas fa-ban" />
                        </button>
                      )}
                      {canWrite && !rowActive(row) && (
                        <button
                          type="button"
                          className={catalog.editBtn}
                          title="Bật"
                          disabled={enablingId === row.id}
                          onClick={() => handleEnable(row)}
                        >
                          <i className="fas fa-check" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </TableCard>
      )}

      <Modal
        isOpen={formOpen}
        onClose={closeForm}
        title={modalTitle}
        size="lg"
        closeOnOverlayClick={!saving}
      >
        <div className={catalog.formWrapper}>
          <div className={catalog.formRow}>
            <Input
              label="Tên (= apiKey trên camera)"
              value={form.name}
              onChange={(e) => patchForm({ name: e.target.value })}
              error={fieldErrors.name}
              required
              readOnly={locked || formMode === 'edit'}
              helperText={formMode === 'create' ? 'Ghi đúng tên này vào URL camera. Không đổi sau khi tạo.' : undefined}
              fullWidth
              data-testid="admin-apikeys-name"
            />
            <Input
              label="Mã đơn vị"
              value={form.companyCode}
              onChange={(e) => patchForm({ companyCode: e.target.value.toUpperCase() })}
              error={fieldErrors.companyCode}
              required
              readOnly={locked}
              fullWidth
              data-testid="admin-apikeys-company"
            />
          </div>
          <div className={catalog.formRow}>
            <Input
              label="Scope"
              value={form.scopes}
              onChange={(e) => patchForm({ scopes: e.target.value })}
              error={fieldErrors.scopes}
              required
              readOnly={locked}
              fullWidth
              data-testid="admin-apikeys-scopes"
            />
            <Input
              label="IP cho phép"
              value={form.allowedIpAddresses}
              onChange={(e) => patchForm({ allowedIpAddresses: e.target.value })}
              helperText="Phân cách bằng dấu phẩy"
              readOnly={locked}
              fullWidth
              data-testid="admin-apikeys-ips"
            />
          </div>
          <div className={catalog.formRow}>
            {locked ? (
              <Input
                label="Hết hạn"
                value={editing?.expiresAt ? formatUTCToLocalDisplay(editing.expiresAt) : '—'}
                readOnly
                fullWidth
                data-testid="admin-apikeys-expires"
              />
            ) : (
              <Input
                label="Hết hạn"
                type="datetime-local"
                value={form.expiresAt}
                onChange={(e) => patchForm({ expiresAt: e.target.value })}
                fullWidth
                data-testid="admin-apikeys-expires"
              />
            )}
            <Select
              label="Trạng thái"
              value={form.isActive ? 'active' : 'inactive'}
              onChange={(e) => patchForm({ isActive: e.target.value === 'active' })}
              options={statusSelectOptions}
              disabled={locked || formMode === 'create'}
              fullWidth
            />
          </div>
          {formMode !== 'create' ? (
            <p className={catalog.hint}>
              Dùng lần cuối: {editing?.lastUsedAt ? formatUTCToLocalDisplay(editing.lastUsedAt) : '—'}
            </p>
          ) : null}
        </div>
        <div className={catalog.modalFooter}>
          <button type="button" className={catalog.cancelBtn} onClick={closeForm} disabled={saving}>
            {locked ? 'Đóng' : 'Hủy'}
          </button>
          {!locked && canWrite && (
            <button type="button" className={catalog.saveBtn} onClick={handleSave} disabled={saving}>
              {saving ? 'Đang lưu...' : 'Lưu'}
            </button>
          )}
        </div>
      </Modal>

      <LeaveConfirmModal
        isOpen={leaveOpen}
        onClose={() => setLeaveOpen(false)}
        onConfirmLeave={actuallyCloseForm}
      />

      <Modal
        isOpen={plainOpen}
        onClose={() => {
          setPlainOpen(false);
          setPlainValue('');
        }}
        title="API key = tên"
        size="md"
      >
        <p className={styles.secretWarn}>
          Ghi đúng tên này vào URL camera (<code>apiKey=</code>). Secret không xoay — tắt bằng trạng thái
          Ngừng hoạt động.
        </p>
        <div className={styles.secretBox}>
          <code className={styles.secretValue} data-testid="admin-apikeys-plaintext">
            {plainValue}
          </code>
          <Button variant="primary" onClick={copyPlain}>
            Sao chép
          </Button>
        </div>
        <div className={catalog.modalFooter}>
          <Button
            variant="secondary"
            onClick={() => {
              setPlainOpen(false);
              setPlainValue('');
            }}
          >
            Đóng
          </Button>
        </div>
      </Modal>

      <Modal
        isOpen={!!revokeTarget}
        onClose={() => !revoking && setRevokeTarget(null)}
        title="Tắt API key"
        size="sm"
      >
        <p className={styles.secretWarn}>
          Tắt <strong>{revokeTarget?.name}</strong>? Camera dùng tên này sẽ nhận 401. Bật lại từ danh sách
          hoặc form.
        </p>
        <div className={catalog.modalFooter}>
          <Button variant="secondary" onClick={() => setRevokeTarget(null)} disabled={revoking}>
            Hủy
          </Button>
          <Button variant="primary" onClick={handleRevoke} disabled={revoking}>
            {revoking ? 'Đang tắt…' : 'Tắt'}
          </Button>
        </div>
      </Modal>
    </div>
  );
};

export default ApiKeysManagementPage;
