import { apiClient } from '../api';
import { BffResponse, unwrap } from '@linm-soft-org/linm-web-common-components';
import type { PatrolDemoSeedResultDto, ReportSeedChannel } from './responseModel';

export const reportSeedEndpoint = {
  seedDemo: async (params?: {
    from?: string;
    to?: string;
    channel?: ReportSeedChannel;
  }): Promise<PatrolDemoSeedResultDto> => {
    const res = await apiClient.post<BffResponse<PatrolDemoSeedResultDto>>(
      '/patrol/demo-seed',
      { from: params?.from, to: params?.to, channel: params?.channel ?? 'both' },
    );
    return unwrap(res);
  },
};
