import type { JobDirection } from '../../services/jobs';

export type JobsEventsHrefOptions = {
  direction?: JobDirection | '';
  jobStatus?: string;
  runId?: string | null;
  eventId?: string | null;
  eventType?: string;
  search?: string;
  fromDate?: string;
  toDate?: string;
  page?: number;
};

/** Build `/admin/jobs/events` query — omit null/empty; page only when > 1. */
export function buildJobsEventsHref(options?: JobsEventsHrefOptions): string {
  const sp = new URLSearchParams();
  if (options?.direction) sp.set('direction', options.direction);
  if (options?.jobStatus) sp.set('jobStatus', options.jobStatus);
  if (options?.eventType) sp.set('eventType', options.eventType);
  if (options?.search) sp.set('search', options.search);
  if (options?.fromDate) sp.set('fromDate', options.fromDate);
  if (options?.toDate) sp.set('toDate', options.toDate);
  if (options?.runId) sp.set('runId', options.runId);
  if (options?.eventId) sp.set('eventId', options.eventId);
  if (options?.page != null && options.page > 1) sp.set('page', String(options.page));
  const q = sp.toString();
  return q ? `/admin/jobs/events?${q}` : '/admin/jobs/events';
}

/** Hub / dashboard direction cards → drill-down target. */
export function buildJobsDirectionCardHref(direction: string): string {
  if (direction === 'Internal') return '/admin/jobs/internal?tab=events';
  if (direction === 'Inbound') return buildJobsEventsHref({ direction: 'Inbound' });
  if (direction === 'Outbound') return buildJobsEventsHref({ direction: 'Outbound' });
  return '/admin/jobs/dashboard';
}

export type JobInternalHrefOptions = {
  tab?: 'sets' | 'events' | 'import';
  eventId?: string | null;
  runId?: string | null;
  jobStatus?: string;
  eventType?: string;
};

export function buildJobInternalHref(options?: JobInternalHrefOptions): string {
  const sp = new URLSearchParams();
  const tab = options?.tab ?? 'events';
  sp.set('tab', tab);
  if (options?.jobStatus) sp.set('jobStatus', options.jobStatus);
  if (options?.eventType) sp.set('eventType', options.eventType);
  if (options?.eventId) sp.set('eventId', options.eventId);
  if (options?.runId) sp.set('runId', options.runId);
  return `/admin/jobs/internal?${sp.toString()}`;
}

export function buildPosInboundRunsHref(runId?: string | null): string {
  if (!runId) return '/admin/jobs/pos-inbound-runs';
  return `/admin/jobs/pos-inbound-runs?runId=${encodeURIComponent(runId)}`;
}
