import React from 'react';
import { Button } from '../../ui';
import {
  jobsService,
  type MissingLedgerRepostReviewPreview,
} from '../../services/jobs';
import { SearchInput, useAppToast } from '@linm-soft-org/linm-web-common-components';
import {
  useMissingLedgerRepostVoucherSearchConfig,
} from './useMissingLedgerRepostVoucherSearchConfig';
import type { VoucherCodePrefixRow } from './useMissingLedgerRepostVoucherSearchConfig';

type Props = {
  legacyRepostPaused?: boolean;
  onRunStarted?: (runId: string) => void;
  onCompleted?: () => void;
};

function formatFilterSummary(
  fromDate: string,
  toDate: string,
  idCodePrefix: string,
  detailVoucherCode: string,
): string {
  const parts: string[] = [];
  if (fromDate || toDate) {
    parts.push(`${fromDate || '…'} → ${toDate || '…'}`);
  }
  const prefix = idCodePrefix.trim();
  const detail = detailVoucherCode.trim();
  if (detail && prefix) parts.push(`${prefix} · ${detail}`);
  else if (detail) parts.push(detail);
  else if (prefix) parts.push(`prefix ${prefix}`);
  return parts.length > 0 ? parts.join(' · ') : 'toàn bộ (không lọc prefix/mã)';
}

const MissingLedgerRepostReviewPanel: React.FC<Props> = ({ legacyRepostPaused, onRunStarted, onCompleted }) => {
  const toast = useAppToast();
  const [fromDate, setFromDate] = React.useState('');
  const [toDate, setToDate] = React.useState('');
  const [prefixCode, setPrefixCode] = React.useState('');
  const [prefixLabel, setPrefixLabel] = React.useState('');
  const [detailVoucherCode, setDetailVoucherCode] = React.useState('');
  const [forceRepost, setForceRepost] = React.useState(false);
  const [companyCodeMismatchRepost, setCompanyCodeMismatchRepost] = React.useState(false);
  const [preview, setPreview] = React.useState<MissingLedgerRepostReviewPreview | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [running, setRunning] = React.useState(false);

  const { config: prefixSearchConfig, loading: prefixConfigLoading } =
    useMissingLedgerRepostVoucherSearchConfig();

  const filterSummary = React.useMemo(
    () => formatFilterSummary(fromDate, toDate, prefixCode, detailVoucherCode),
    [fromDate, toDate, prefixCode, detailVoucherCode],
  );

  const searchParams = React.useMemo(
    () => ({
      fromDate: fromDate || null,
      toDate: toDate || null,
      idCodePrefix: prefixCode.trim() || null,
      voucherCode: detailVoucherCode.trim() || null,
      forceRepost,
      companyCodeMismatchRepost,
    }),
    [fromDate, toDate, prefixCode, detailVoucherCode, forceRepost, companyCodeMismatchRepost],
  );

  const loadPreview = React.useCallback(() => {
    setLoadingPreview(true);
    jobsService
      .getMissingLedgerRepostReviewPreview(
        searchParams.fromDate,
        searchParams.toDate,
        searchParams.idCodePrefix,
        searchParams.voucherCode,
        searchParams.forceRepost,
        searchParams.companyCodeMismatchRepost,
      )
      .then(setPreview)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [searchParams, toast]);

  const handleRun = React.useCallback(() => {
    const modeLine = companyCodeMismatchRepost
      ? 'Re-post sau đổi companyCode (xóa GL mã cũ + ghi lại mã mới)'
      : forceRepost
        ? 'Force Post (xóa GL + ghi sổ lại)'
        : 'Ghi sổ bổ sung (lệch — thiếu GL)';
    if (
      !window.confirm(
        `${modeLine}\n\nBộ lọc: ${filterSummary}\n\nJob sẽ load phiếu theo điều kiện trên và xử lý nền.`,
      )
    ) {
      return;
    }

    setRunning(true);
    jobsService
      .triggerMissingLedgerRepostReview(searchParams)
      .then((result) => {
        if (result.runId) {
          toast.info(
            `Đã tạo job theo bộ lọc — run ${result.runId.slice(0, 8)}… · theo dõi checkpoint / Job events.`,
          );
          onRunStarted?.(result.runId);
          onCompleted?.();
          return;
        }
        toast.success('Đã lên lịch job theo bộ lọc.');
        onCompleted?.();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRunning(false));
  }, [searchParams, filterSummary, forceRepost, companyCodeMismatchRepost, toast, onCompleted, onRunStarted]);

  const handleDateChange = React.useCallback((field: 'from' | 'to', value: string) => {
    if (field === 'from') setFromDate(value);
    else setToDate(value);
    setPreview(null);
  }, []);

  const handlePrefixChange = React.useCallback((item: VoucherCodePrefixRow) => {
    setPrefixCode(item.idCodePrefix);
    setPrefixLabel(`${item.idCodePrefix} — ${item.name}`);
    setPreview(null);
  }, []);

  const handlePrefixClear = React.useCallback(() => {
    setPrefixCode('');
    setPrefixLabel('');
    setPreview(null);
  }, []);

  const handleDetailChange = React.useCallback((value: string) => {
    setDetailVoucherCode(value);
    setPreview(null);
  }, []);

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '12px 16px',
        border: '1px solid #cbd5e1',
        borderRadius: 8,
        background: legacyRepostPaused ? '#f1f5f9' : '#eff6ff',
        opacity: legacyRepostPaused ? 0.85 : 1,
      }}
      data-testid="missing-ledger-repost-review-panel"
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div style={{ flex: '1 1 320px' }}>
          <strong>Re-Post</strong>
          <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
            Chạy job chỉ cần <strong>bộ lọc</strong> (ngày · prefix · mã CT). BE load phiếu và xử lý nền.{' '}
            <strong>Kiểm tra</strong> (tùy chọn) xem trước số lệch / đã GL / lệch companyCode.
          </p>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8, alignItems: 'flex-end' }}>
            <label style={{ fontSize: 13 }}>
              Từ ngày{' '}
              <input
                type="date"
                value={fromDate}
                onChange={(e) => handleDateChange('from', e.target.value)}
                data-testid="missing-ledger-review-from-date"
              />
            </label>
            <label style={{ fontSize: 13 }}>
              Đến ngày{' '}
              <input
                type="date"
                value={toDate}
                onChange={(e) => handleDateChange('to', e.target.value)}
                data-testid="missing-ledger-review-to-date"
              />
            </label>
            <div style={{ flex: '1 1 200px', minWidth: 180 }} data-testid="missing-ledger-review-prefix-search">
              {prefixSearchConfig ? (
                <SearchInput
                  config={prefixSearchConfig}
                  value={prefixCode}
                  primaryDisplay={prefixLabel || prefixCode}
                  label="Mã CT (prefix)"
                  placeholder="INV · PT · PC…"
                  showSecondaryInput={false}
                  disabled={prefixConfigLoading}
                  onChange={handlePrefixChange}
                  onClear={handlePrefixClear}
                />
              ) : (
                <label style={{ fontSize: 13, display: 'block' }}>
                  Prefix
                  <input
                    type="text"
                    disabled
                    placeholder={prefixConfigLoading ? 'Đang tải Định dạng mã…' : 'Chưa có IdCode config'}
                    style={{ display: 'block', marginTop: 4, width: '100%' }}
                  />
                </label>
              )}
            </div>
            <label style={{ fontSize: 13, flex: '1 1 200px', minWidth: 180 }}>
              Mã chứng từ (đầy đủ)
              <input
                type="text"
                value={detailVoucherCode}
                onChange={(e) => handleDetailChange(e.target.value)}
                placeholder="FM-HD-… / INV-20260614-0001"
                style={{ display: 'block', marginTop: 4, width: '100%' }}
                data-testid="missing-ledger-review-detail-code"
              />
            </label>
            <label
              style={{
                fontSize: 13,
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                alignSelf: 'center',
                cursor: 'pointer',
              }}
              data-testid="missing-ledger-review-force-repost"
            >
              <input
                type="checkbox"
                checked={forceRepost}
                disabled={companyCodeMismatchRepost}
                onChange={(e) => {
                  setForceRepost(e.target.checked);
                  if (e.target.checked) setCompanyCodeMismatchRepost(false);
                  setPreview(null);
                }}
              />
              Force Post (xóa GL + ghi lại)
            </label>
            <label
              style={{
                fontSize: 13,
                display: 'flex',
                alignItems: 'center',
                gap: 6,
                alignSelf: 'center',
                cursor: 'pointer',
              }}
              data-testid="missing-ledger-review-company-code-mismatch"
            >
              <input
                type="checkbox"
                checked={companyCodeMismatchRepost}
                disabled={forceRepost}
                onChange={(e) => {
                  setCompanyCodeMismatchRepost(e.target.checked);
                  if (e.target.checked) setForceRepost(false);
                  setPreview(null);
                }}
              />
              Re-post sau đổi companyCode
            </label>
          </div>
          {loadingPreview ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>Đang kiểm tra…</p>
          ) : preview ? (
            <div style={{ margin: '6px 0 0', fontSize: 13 }}>
              <p style={{ margin: '0 0 4px' }}>
                Lọc <strong>{filterSummary}</strong>
              </p>
              <p style={{ margin: '0 0 4px' }}>
                Trong phạm vi: <strong>{preview.totalInScope.toLocaleString('vi-VN')}</strong> CT
                {' '}(HĐ <strong>{preview.salesInvoiceTotalInScope.toLocaleString('vi-VN')}</strong>
                {' · '}PT/PC <strong>{preview.cashVoucherTotalInScope.toLocaleString('vi-VN')}</strong>)
              </p>
              <p style={{ margin: '0 0 4px', color: '#b45309' }}>
                Lệch (thiếu GL): HĐ <strong>{preview.salesInvoiceMissingLedgerCount.toLocaleString('vi-VN')}</strong>
                {' · '}PT/PC <strong>{preview.cashVoucherMissingLedgerCount.toLocaleString('vi-VN')}</strong>
              </p>
              <p style={{ margin: '0 0 4px', color: '#1d4ed8' }}>
                Đã có GL (Force Post): HĐ <strong>{preview.salesInvoiceHasLedgerCount.toLocaleString('vi-VN')}</strong>
                {' · '}PT/PC <strong>{preview.cashVoucherHasLedgerCount.toLocaleString('vi-VN')}</strong>
              </p>
              <p style={{ margin: '0 0 4px', color: '#7c3aed' }}>
                Lệch companyCode (GL cũ): HĐ{' '}
                <strong>{preview.salesInvoiceCompanyCodeMismatchCount.toLocaleString('vi-VN')}</strong>
                {' · '}PT/PC{' '}
                <strong>{preview.cashVoucherCompanyCodeMismatchCount.toLocaleString('vi-VN')}</strong>
              </p>
              <p style={{ margin: 0 }}>
                {companyCodeMismatchRepost ? (
                  <>
                    Chế độ: <strong>Re-post sau đổi companyCode</strong>
                    {' · '}Ước tính: <strong>{preview.totalEligible.toLocaleString('vi-VN')}</strong> phiếu
                    {' '}(toàn bộ trong phạm vi lọc)
                  </>
                ) : forceRepost ? (
                  <>
                    Chế độ: <strong>Force Post</strong>
                    {' · '}Ước tính: <strong>{preview.totalEligible.toLocaleString('vi-VN')}</strong> phiếu
                    {' '}(toàn bộ trong phạm vi lọc — unpost nếu có GL rồi ghi lại)
                  </>
                ) : (
                  <>
                    Chế độ: <strong>Normal</strong>
                    {' · '}Ước tính: <strong>{preview.totalEligible.toLocaleString('vi-VN')}</strong> phiếu
                  </>
                )}
              </p>
            </div>
          ) : (
            <p style={{ margin: '6px 0 0', fontSize: 13, color: '#64748b' }}>
              Bấm <strong>Ghi sổ bổ sung</strong> / <strong>Force Post</strong> / <strong>Re-post sau đổi companyCode</strong>{' '}
              để chạy theo bộ lọc — hoặc <strong>Kiểm tra</strong> xem trước số liệu.
            </p>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
          <Button
            type="button"
            variant="secondary"
            onClick={loadPreview}
            disabled={loadingPreview || running}
            data-testid="missing-ledger-review-search"
          >
            Kiểm tra
          </Button>
          <Button
            type="button"
            onClick={handleRun}
            disabled={running || loadingPreview || legacyRepostPaused}
            data-testid="missing-ledger-review-trigger"
          >
            {running
              ? 'Đang tạo job…'
              : companyCodeMismatchRepost
                ? 'Re-post companyCode'
                : forceRepost
                  ? 'Force Post'
                  : 'Ghi sổ bổ sung'}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default MissingLedgerRepostReviewPanel;
