/** Cap platform-event in-flight vs Low worker pick — tránh nghẽn queue.
 * Sync: so sánh số ExternalDetailBatchRequested (lanes × concurrentBatches),
 * KHÔNG so sánh cap docs (lanes × detailBatchSize) — 100 CT/batch ≠ 100 job.
 */

export type JobParallelismWarningLevel = 'ok' | 'warn' | 'danger';

export type LowWorkerPickCapacity = {
  lowWorkerInstanceCount: number;
  lowWorkerAutoScaleEnabled?: boolean;
  lowWorkerInstanceCountMax?: number;
  lowClusterInstanceCount: number;
};

export function effectiveLowWorkerPickCapacity(cap: LowWorkerPickCapacity): number {
  const instanceCount = cap.lowWorkerAutoScaleEnabled
    ? Math.max(1, cap.lowWorkerInstanceCountMax ?? cap.lowWorkerInstanceCount)
    : Math.max(1, cap.lowWorkerInstanceCount);
  return instanceCount * Math.max(1, cap.lowClusterInstanceCount);
}

export type ParallelismQueueWarningInput = {
  /**
   * Sync: max platform batch events in-flight (searchLaneCount × concurrentDetailBatches).
   * Repost: max PostImport / prepare jobs in-flight.
   * Cấm truyền cap docs (lanes × detailBatchSize).
   */
  configuredCap: number;
  lowWorkerPickCapacity: number;
  /** Số run Low đồng thời ước lượng (vd. 3 connector resync cùng lúc). */
  concurrentRuns?: number;
  context: 'sync' | 'repost';
  /** Optional — docs/event (chỉ để giải thích, không so worker). */
  detailBatchSize?: number;
};

export type ParallelismQueueWarning = {
  level: JobParallelismWarningLevel;
  configuredCap: number;
  lowWorkerPickCapacity: number;
  ratio: number;
  title: string;
  detail: string;
};

const capLabel = (context: ParallelismQueueWarningInput['context']): string =>
  context === 'sync'
    ? 'cap platform event (≤ maxActivePlatformEvents)'
    : 'cap post song song';

export function evaluateParallelismQueueWarning(
  input: ParallelismQueueWarningInput,
): ParallelismQueueWarning | null {
  const cap = Math.max(1, input.configuredCap);
  const workers = Math.max(1, input.lowWorkerPickCapacity);
  const runs = Math.max(1, input.concurrentRuns ?? 1);
  const effectiveLoad = cap * runs;
  const ratio = effectiveLoad / workers;
  const label = capLabel(input.context);
  const batchHint =
    input.context === 'sync' && input.detailBatchSize != null && input.detailBatchSize > 0
      ? ` Mỗi batch event chứa ${input.detailBatchSize} CT (1 POST ChiTiet*Batch) — không tính ${input.detailBatchSize} job.`
      : '';

  // Sync: event budget ≤20 is the hard product cap; worker warn when planned peak ≫ workers
  if (ratio <= 1 && (input.context === 'repost' ? cap <= 32 : cap <= 20) && input.concurrentRuns == null) {
    return null;
  }

  if (ratio <= 1 && (input.context === 'repost' ? cap <= 32 : cap <= 20)) {
    return {
      level: 'ok',
      configuredCap: cap,
      lowWorkerPickCapacity: workers,
      ratio,
      title: 'Cap trong ngưỡng worker Low',
      detail: `${label} ${cap} ≤ ${workers} worker pick/host×cluster. Nếu chạy ${runs} run đồng thời, tải ≈ ${effectiveLoad} event — vẫn ổn.${batchHint}`,
    };
  }

  if (ratio > 2 || (input.context === 'repost' && cap > 48) || effectiveLoad > workers * 3) {
    return {
      level: 'danger',
      configuredCap: cap,
      lowWorkerPickCapacity: workers,
      ratio,
      title: 'Nguy cơ nghẽn queue cao',
      detail:
        `${label} ${cap}${runs > 1 ? ` × ${runs} run ≈ ${effectiveLoad} event in-flight` : ''} ` +
        `trong khi worker Low pick ≈ ${workers}. ` +
        'Hàng đợi Queued tăng, batch event chậm. ' +
        'Giảm searchLaneCount / concurrentDetailBatches hoặc maxActivePlatformEvents (không giảm detailBatchSize trừ khi muốn ít CT/lần gọi POS); ' +
        'tăng LowWorkerInstanceCount trên /admin/jobs/server-config; tránh nhiều connector Resync cùng lúc.' +
        batchHint,
    };
  }

  return {
    level: 'warn',
    configuredCap: cap,
    lowWorkerPickCapacity: workers,
    ratio,
    title: 'Cap event có thể vượt throughput worker',
    detail:
      `${label} ${cap}${runs > 1 ? ` × ${runs} run` : ''} > ${workers} worker Low. ` +
      'Leader vẫn enqueue batch nhưng worker pick chậm hơn → pool chờ dài. ' +
      'Khuyến nghị: số batch event ≤ worker pick; hoặc tăng LowWorkerInstanceCount.' +
      batchHint,
  };
}
