const CONNECTORS = [
  { key: 'reva-fm-hoa-don', label: 'Hóa đơn' },
  { key: 'reva-fm-phieu-thu', label: 'Phiếu thu' },
  { key: 'reva-fm-phieu-chi', label: 'Phiếu chi' },
] as const;

const CONNECTOR_FILTER_OPTIONS = [
  { value: '', label: 'Tất cả loại' },
  ...CONNECTORS.map((c) => ({ value: c.key, label: c.label })),
];

const FILTER_YEAR_OPTIONS = yearOptionsFromStartYear(2025);

const PERIOD_FILTER_LABELS = {
  viewMode: 'Xem theo',
  fieldMonth: 'Tháng',
  fieldYear: 'Năm',
  fieldQuarter: 'Quý',
};

function ymdOverlaps(fromA: string, toA: string, fromB: string, toB: string): boolean {
  if (!fromA || !toA || !fromB || !toB) return true;
  return fromA <= toB && toA >= fromB;
}

const PAGE_PATH = '/admin/jobs/pos-voucher-count';

const MASTER_GRID_PREFIX = 'pos-detail-reconcile-masters';
const DETAIL_GRID_PREFIX = 'pos-detail-reconcile-keys';
const MASTER_PAGE_SIZE_DEFAULT = 50;
const DETAIL_PAGE_SIZE_DEFAULT = 50;

type ReconcileMasterCounts = PosVoucherDetailReconcileMaster & {
  changedCount?: number;
  posDeletedCount?: number;
};

function posDeletedOf(m: PosVoucherDetailReconcileMaster): number {
  return (m as ReconcileMasterCounts).posDeletedCount ?? 0;
}

function isMasterMismatch(m: PosVoucherDetailReconcileMaster): boolean {
  return (
    m.missingCount > 0 ||
    m.extraCount > 0 ||
    (m.changedCount ?? 0) > 0 ||
    posDeletedOf(m) > 0
  );
}

function isMasterSelectable(m: PosVoucherDetailReconcileMaster): boolean {
  return m.status === 'Done' && isMasterMismatch(m);
}

function masterSelectDisabledReason(m: PosVoucherDetailReconcileMaster): string | undefined {
  if (m.status !== 'Done') return 'Chỉ chọn kỳ đã xong (Done).';
  if (
    m.missingCount === 0 &&
    m.extraCount === 0 &&
    (m.changedCount ?? 0) === 0 &&
    posDeletedOf(m) === 0
  )
    return 'Không có CT thiếu/thừa/đổi/POS xóa.';
  return undefined;
}

function todayIso(): string {
  const d = new Date();
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

function formatRunCreated(iso: string): string {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  return d.toLocaleString('vi-VN', {
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
}

function runOptionLabel(r: PosVoucherDetailReconcileRunListItem): string {
  const scope = r.allCompanies || r.companyScope === '*' ? 'Tất cả ĐVCS' : r.companyScope;
  const split = r.splitByDay ? ' · theo ngày' : '';
  const miss =
    r.missingTotal > 0 || r.extraTotal > 0 || (r.changedTotal ?? 0) > 0
      ? ` · thiếu ${r.missingTotal.toLocaleString('vi-VN')} / đổi ${r.changedTotal ?? 0} / thừa ${r.extraTotal.toLocaleString('vi-VN')} / POS xóa ${r.posDeletedTotal ?? 0}`
      : '';
  const progress =
    (r.status === 'Running' || r.status === 'Queued') && r.progressMessage
      ? ` · ${r.progressMessage}`
      : '';
  return `${formatRunCreated(r.createdAtUtc)} · ${r.fromDate}→${r.toDate} · ${scope}${split} · ${r.status}${progress}${miss}`;
}

function statusLabel(status: string): string {
  switch (status) {
    case 'match':
      return 'Khớp';
    case 'erp_less':
      return 'ERP thiếu';
    case 'erp_more':
      return 'ERP thừa';
    case 'pos_fail':
      return 'POS lỗi';
    case 'config_missing':
      return 'Thiếu config';
    case 'Completed':
      return 'Xong';
    case 'Running':
      return 'Đang chạy';
    case 'Queued':
      return 'Chờ';
    case 'Cancelled':
      return 'Đã dừng';
    case 'Failed':
      return 'Lỗi';
    case 'Done':
      return 'Xong';
    default:
      return status;
  }
}

function statusClass(status: string): string {
  switch (status) {
    case 'match':
    case 'Completed':
    case 'Done':
      return styles.ok;
    case 'erp_less':
    case 'erp_more':
    case 'Running':
    case 'Queued':
    case 'Cancelled':
      return styles.warn;
    case 'pos_fail':
    case 'config_missing':
    case 'Failed':
      return styles.err;
    default:
      return '';
  }
}

function periodLabel(p: PosVoucherCountPeriod): string {
  if (p.periodKey === 'all') return 'Toàn kỳ';
  return p.periodKey;
}

function PeriodCells({ period }: { period: PosVoucherCountPeriod }) {
  return (
    <>
      <td>
        {period.posSuccess ? period.posTotalItems.toLocaleString('vi-VN') : '—'}
        {period.posElapsedMs > 0 && (
          <div className={styles.muted}>{period.posElapsedMs} ms</div>
        )}
      </td>
      <td>{period.erpCount.toLocaleString('vi-VN')}</td>
      <td className={period.delta === 0 && period.posSuccess ? styles.ok : styles.warn}>
        {period.posSuccess ? period.delta.toLocaleString('vi-VN') : '—'}
      </td>
      <td title="POS Tim* không trả tổng dòng — chỉ ERP">
        {period.erpLineCount.toLocaleString('vi-VN')}
      </td>
      <td className={statusClass(period.status)}>{statusLabel(period.status)}</td>
      <td className={styles.note}>
        {!period.posSuccess && period.posMessage
          ? period.posMessage
          : `${period.fromDate} → ${period.toDate}`}
      </td>
    </>
  );
}

function posCountHref(runId: string | null): string {
  if (!runId) return PAGE_PATH;
  return `${PAGE_PATH}?runId=${encodeURIComponent(runId)}`;
}

const PosVoucherCountCheckPage: React.FC = () => {
  useNavTitle('Đối soát số CT POS');
  const toast = useAppToast();
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const urlRunId = searchParams.get('runId');

  const [companies, setCompanies] = React.useState<ActiveCompanyItem[]>([]);
  const [companyCode, setCompanyCode] = React.useState('');
  const [fromDate, setFromDate] = React.useState(todayIso);
  const [toDate, setToDate] = React.useState(todayIso);
  const [selectedKeys, setSelectedKeys] = React.useState<string[]>(CONNECTORS.map((c) => c.key));
  const [mode, setMode] = React.useState<'count' | 'detail'>('count');
  const [loading, setLoading] = React.useState(false);
  const [result, setResult] = React.useState<PosVoucherCountCheckResult | null>(null);

  const [detailRunId, setDetailRunId] = React.useState<string | null>(null);
  const [detailRun, setDetailRun] = React.useState<PosVoucherDetailReconcileRun | null>(null);
  const [pastRuns, setPastRuns] = React.useState<PosVoucherDetailReconcileRunListItem[]>([]);
  const [loadingPastRuns, setLoadingPastRuns] = React.useState(false);
  const [detailPanel, setDetailPanel] = React.useState<{
    master: PosVoucherDetailReconcileMaster;
    kind: 'missing' | 'extra' | 'changed' | 'posDeleted';
    items: PosVoucherDetailReconcileDetail[];
    total: number;
  } | null>(null);
  const [resyncing, setResyncing] = React.useState(false);
  const [softDeleting, setSoftDeleting] = React.useState(false);
  const [hardDeleting, setHardDeleting] = React.useState(false);
  const [rechecking, setRechecking] = React.useState(false);
  const [stopping, setStopping] = React.useState(false);
  const [lastResyncJobId, setLastResyncJobId] = React.useState<string | null>(null);
  const [splitByDay, setSplitByDay] = React.useState(false);
  const [onlyMismatch, setOnlyMismatch] = React.useState(true);
  const [filterViewMode, setFilterViewMode] = React.useState<ViewMode>('day');
  const [filterMonth, setFilterMonth] = React.useState(() => nowMonth());
  const [filterYear, setFilterYear] = React.useState(() => nowYear());
  const [filterQuarter, setFilterQuarter] = React.useState(() => nowQuarter());
  const [filterManualFrom, setFilterManualFrom] = React.useState('');
  const [filterManualTo, setFilterManualTo] = React.useState('');
  const [filterConnectorKey, setFilterConnectorKey] = React.useState('');
  const [masterPage, setMasterPage] = React.useState(1);
  const [masterPageSize, setMasterPageSize] = React.useState(MASTER_PAGE_SIZE_DEFAULT);
  const [detailPage, setDetailPage] = React.useState(1);
  const [detailPageSize] = React.useState(DETAIL_PAGE_SIZE_DEFAULT);

  const filterComputedDates = React.useMemo(() => {
    if (filterViewMode === 'year') {
      const y = Number(filterYear);
      return { fromDate: `${y}-01-01`, toDate: `${y}-12-31` };
    }
    return computeReportPeriodDates(filterViewMode, filterMonth, filterYear, filterQuarter);
  }, [filterViewMode, filterMonth, filterYear, filterQuarter]);
  const masterFilterFrom =
    filterViewMode === 'day' ? filterManualFrom : filterComputedDates.fromDate;
  const masterFilterTo = filterViewMode === 'day' ? filterManualTo : filterComputedDates.toDate;

  const allMasters = detailRun?.masters ?? [];
  const scopedMasters = React.useMemo(
    () =>
      allMasters.filter((m) => {
        if (filterConnectorKey && m.connectorKey !== filterConnectorKey) return false;
        if (masterFilterFrom && masterFilterTo) {
          return ymdOverlaps(m.fromDate, m.toDate, masterFilterFrom, masterFilterTo);
        }
        return true;
      }),
    [allMasters, filterConnectorKey, masterFilterFrom, masterFilterTo],
  );
  const filteredMasters = React.useMemo(() => {
    if (!onlyMismatch) return scopedMasters;
    return scopedMasters.filter((m) => isMasterMismatch(m) || m.status === 'Failed');
  }, [scopedMasters, onlyMismatch]);
  const scopedMismatchCount = scopedMasters.filter(isMasterMismatch).length;
  const masterTotal = filteredMasters.length;
  const masterTotalPages = Math.max(1, Math.ceil(masterTotal / masterPageSize) || 1);
  const pagedMasters = React.useMemo(() => {
    const start = (masterPage - 1) * masterPageSize;
    return filteredMasters.slice(start, start + masterPageSize);
  }, [filteredMasters, masterPage, masterPageSize]);
  const selectableFiltered = React.useMemo(
    () => filteredMasters.filter(isMasterSelectable),
    [filteredMasters],
  );

  React.useEffect(() => {
    setMasterPage(1);
  }, [
    detailRunId,
    onlyMismatch,
    masterPageSize,
    filterConnectorKey,
    masterFilterFrom,
    masterFilterTo,
  ]);

  const filterSeedRunIdRef = React.useRef<string | null>(null);
  React.useEffect(() => {
    if (!detailRun) {
      filterSeedRunIdRef.current = null;
      return;
    }
    if (filterSeedRunIdRef.current === detailRun.id) return;
    filterSeedRunIdRef.current = detailRun.id;
    setFilterViewMode('day');
    setFilterManualFrom(detailRun.fromDate);
    setFilterManualTo(detailRun.toDate);
    setFilterConnectorKey('');
  }, [detailRun]);

  React.useEffect(() => {
    if (masterPage > masterTotalPages) setMasterPage(masterTotalPages);
  }, [masterPage, masterTotalPages]);

  const getMasterId = React.useCallback((m: PosVoucherDetailReconcileMaster) => m.id, []);
  const masterSelection = useErpListSelection({
    rows: pagedMasters,
    totalCount: selectableFiltered.length,
    page: masterPage,
    pageSize: masterPageSize,
    getRowId: getMasterId,
    isRowSelectable: isMasterSelectable,
  });

  const detailItems = detailPanel?.items ?? [];
  const detailTotal = detailPanel?.total ?? 0;
  const detailTotalPages = Math.max(1, Math.ceil(detailTotal / detailPageSize) || 1);
  const getDetailId = React.useCallback((d: PosVoucherDetailReconcileDetail) => d.id, []);
  const detailSelection = useErpListSelection({
    rows: detailItems,
    totalCount: detailTotal,
    page: detailPage,
    pageSize: detailPageSize,
    getRowId: getDetailId,
    isRowSelectable: () => false,
  });

  const resolveSelectedMasterIds = React.useCallback(
    (predicate: (m: PosVoucherDetailReconcileMaster) => boolean) => {
      const scope = masterSelection.getBatchScope();
      if (scope.mode === 'all') {
        return selectableFiltered.filter(predicate).map((m) => m.id);
      }
      if (scope.ids.length > 0) {
        return allMasters.filter((m) => scope.ids.includes(m.id) && predicate(m)).map((m) => m.id);
      }
      return [];
    },
    [masterSelection, selectableFiltered, allMasters],
  );

  const syncUrlRunId = React.useCallback(
    (runId: string | null, replace = false) => {
      navigateInAppPath(posCountHref(runId), navigate, { replace });
    },
    [navigate],
  );

  const loadPastRuns = React.useCallback(() => {
    setLoadingPastRuns(true);
    jobsService
      .listPosVoucherDetailReconcileRuns({ page: 1, pageSize: 40 })
      .then((page) => setPastRuns(page.items ?? []))
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPastRuns(false));
  }, [toast]);

  React.useEffect(() => {
    companyService
      .getActiveList()
      .then((list) => {
        setCompanies(list);
        const active = getActiveCompanyCode();
        if (!active && list[0]?.id) setActiveCompanyCode(list[0].id);
      })
      .catch((e: Error) => toast.error(e.message));
  }, [toast]);

  React.useEffect(() => {
    loadPastRuns();
  }, [loadPastRuns]);

  const selectPastRun = React.useCallback(
    (runId: string, opts?: { syncUrl?: boolean }) => {
      if (!runId) {
        setDetailRunId(null);
        setDetailRun(null);
        masterSelection.clearSelection();
        setDetailPanel(null);
        setLastResyncJobId(null);
        if (opts?.syncUrl !== false) syncUrlRunId(null, true);
        return;
      }
      setMode('detail');
      setResult(null);
      masterSelection.clearSelection();
      setDetailPanel(null);
      setLastResyncJobId(null);
      setDetailRun(null);
      setDetailRunId(runId);
      if (opts?.syncUrl !== false) syncUrlRunId(runId);
      const listed = pastRuns.find((r) => r.id === runId);
      if (listed) {
        setFromDate(listed.fromDate);
        setToDate(listed.toDate);
        setCompanyCode(listed.allCompanies || listed.companyScope === '*' ? '' : listed.companyScope);
        if (listed.connectorKeys?.length) setSelectedKeys(listed.connectorKeys);
        setSplitByDay(!!listed.splitByDay);
      }
    },
    [pastRuns, syncUrlRunId, masterSelection],
  );

  // Deep-link ?runId= → mở Detail + poll.
  React.useEffect(() => {
    if (!urlRunId) return;
    if (urlRunId === detailRunId) return;
    selectPastRun(urlRunId, { syncUrl: false });
  }, [urlRunId, detailRunId, selectPastRun]);

  React.useEffect(() => {
    if (!detailRunId) return;
    let cancelled = false;
    const poll = () => {
      jobsService
        .getPosVoucherDetailReconcileRun(detailRunId)
        .then((data) => {
          if (cancelled) return;
          setDetailRun(data);
          if (data.status === 'Queued' || data.status === 'Running') {
            window.setTimeout(poll, 2500);
          } else {
            loadPastRuns();
          }
        })
        .catch((e: Error) => {
          if (!cancelled) toast.error(e.message);
        });
    };
    poll();
    return () => {
      cancelled = true;
    };
  }, [detailRunId, toast, loadPastRuns]);

  const toggleKey = (key: string) => {
    setSelectedKeys((prev) =>
      prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key],
    );
  };

  const validateDates = () => {
    if (!fromDate || !toDate) {
      toast.warning('Chọn Từ ngày / Đến ngày.');
      return false;
    }
    if (fromDate > toDate) {
      toast.warning('Từ ngày không được lớn hơn Đến ngày.');
      return false;
    }
    if (selectedKeys.length === 0) {
      toast.warning('Chọn ít nhất một loại chứng từ.');
      return false;
    }
    return true;
  };

  const runCountCheck = () => {
    if (!validateDates()) return;
    const allCompanies = !companyCode.trim();
    if (!allCompanies) setActiveCompanyCode(companyCode.trim());

    setLoading(true);
    setResult(null);
    jobsService
      .checkPosVoucherCounts({
        fromDate,
        toDate,
        connectorKeys: selectedKeys,
        allCompanies,
        scopeCompanyCode: allCompanies ? null : companyCode.trim(),
      })
      .then((data) => {
        setResult(data);
        if (data.allMatch) toast.success('Khớp header — POS = ERP (toàn kỳ).');
        else toast.warning('Có chênh lệch — xem bảng hoặc chạy mode Detail.');
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoading(false));
  };

  const startDetailJob = () => {
    if (!validateDates()) return;
    const allCompanies = !companyCode.trim();
    if (!allCompanies) setActiveCompanyCode(companyCode.trim());

    setLoading(true);
    setDetailRun(null);
    setDetailRunId(null);
    masterSelection.clearSelection();
    setDetailPanel(null);
    setLastResyncJobId(null);
    jobsService
      .startPosVoucherDetailReconcile({
        fromDate,
        toDate,
        connectorKeys: selectedKeys,
        allCompanies,
        scopeCompanyCode: allCompanies ? null : companyCode.trim(),
        splitByDay,
      })
      .then((data) => {
        setMode('detail');
        setDetailRunId(data.runId);
        syncUrlRunId(data.runId);
        const ds = data.dataSyncRunId ? ` · DataSync ${data.dataSyncRunId.slice(0, 8)}…` : '';
        toast.success(
          `Đã tạo job Detail (${data.periodJobsEnqueued ?? '?'} kỳ song song)${ds}`,
        );
        loadPastRuns();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoading(false));
  };

  const openDetails = (
    master: PosVoucherDetailReconcileMaster,
    kind: 'missing' | 'extra' | 'changed' | 'posDeleted',
    page = 1,
  ) => {
    setDetailPage(page);
    jobsService
      .getPosVoucherDetailReconcileDetails(master.id, {
        kind,
        page,
        pageSize: detailPageSize,
      })
      .then((pageResult) => {
        setDetailPanel({
          master,
          kind,
          items: pageResult.items,
          total: pageResult.total,
        });
      })
      .catch((e: Error) => toast.error(e.message));
  };

  const confirmResync = (
    connectorKey?: string,
    masterId?: string,
    kind: 'missing' | 'changed' = 'missing',
  ) => {
    if (!detailRunId || !detailRun) return;
    const predicate = (m: PosVoucherDetailReconcileMaster) =>
      m.status === 'Done' &&
      (kind === 'changed' ? (m.changedCount ?? 0) > 0 : m.missingCount > 0) &&
      (!connectorKey || m.connectorKey === connectorKey) &&
      (!masterId || m.id === masterId);

    let masterIds = masterId ? [masterId] : resolveSelectedMasterIds(predicate);
    if (masterIds.length === 0 && !masterId) {
      masterIds = detailRun.masters.filter(predicate).map((m) => m.id);
    }

    if (masterIds.length === 0) {
      toast.warning(
        kind === 'changed'
          ? 'Chọn master có CT đổi (updatedDate), hoặc lọc theo loại.'
          : 'Chọn master có CT thiếu, hoặc lọc theo loại.',
      );
      return;
    }

    setResyncing(true);
    jobsService
      .confirmPosVoucherDetailResync(detailRunId, {
        masterIds,
        connectorKey: connectorKey ?? null,
        kind,
      })
      .then((r) => {
        setLastResyncJobId(r.dataSyncRunId);
        toast.success(
          `Đã enqueue resync ${r.detailsQueued.toLocaleString('vi-VN')} CT — DataSync ${r.dataSyncRunId.slice(0, 8)}…`,
        );
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run) => setDetailRun(run))
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setResyncing(false));
  };

  const updateAllChangedToLatest = () => {
    if (!detailRunId || !detailRun) return;
    const masters = detailRun.masters.filter(
      (m) => m.status === 'Done' && (m.changedCount ?? 0) > 0,
    );
    if (masters.length === 0) {
      toast.warning('Không có CT đổi (POS updatedDate mới hơn ERP) để cập nhật.');
      return;
    }

    const docSum = masters.reduce((s, m) => s + (m.changedCount ?? 0), 0);
    const ok = window.confirm(
      `Update all to latest — ghi đè ERP theo bản POS mới nhất?\n\n` +
        `${masters.length.toLocaleString('vi-VN')} kỳ · ${docSum.toLocaleString('vi-VN')} phiếu Đổi ` +
        `(POS updatedDate mới hơn ERP PosUpdatedAt).\n\n` +
        `Enqueue job resync (reimport). Phiếu đã queue trước đó sẽ bỏ qua. Tiếp tục?`,
    );
    if (!ok) return;

    setResyncing(true);
    jobsService
      .confirmPosVoucherDetailResync(detailRunId, {
        masterIds: masters.map((m) => m.id),
        connectorKey: null,
        kind: 'changed',
      })
      .then((r) => {
        setLastResyncJobId(r.dataSyncRunId);
        toast.success(
          `Đã enqueue Update all to latest · ${r.detailsQueued.toLocaleString('vi-VN')} CT — DataSync ${r.dataSyncRunId.slice(0, 8)}…`,
        );
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run) => setDetailRun(run))
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setResyncing(false));
  };

  const confirmSoftDeleteExtra = (connectorKey?: string, masterId?: string) => {
    if (!detailRunId || !detailRun) return;
    const predicate = (m: PosVoucherDetailReconcileMaster) =>
      m.status === 'Done' &&
      m.extraCount > 0 &&
      (!connectorKey || m.connectorKey === connectorKey) &&
      (!masterId || m.id === masterId);

    let mastersForDelete = masterId
      ? detailRun.masters.filter((m) => m.id === masterId && predicate(m))
      : (() => {
          const ids = resolveSelectedMasterIds(predicate);
          if (ids.length > 0) return detailRun.masters.filter((m) => ids.includes(m.id));
          return detailRun.masters.filter(predicate);
        })();

    if (mastersForDelete.length === 0) {
      toast.warning('Chọn master có CT thừa, hoặc lọc theo loại.');
      return;
    }

    const extraSum = mastersForDelete.reduce((s, m) => s + m.extraCount, 0);
    const ok = window.confirm(
      `Soft-delete ${extraSum.toLocaleString('vi-VN')} CT ERP thừa (unpost nếu Posted + IsDeleted), giống event POS delete.\n\nKhông hoàn tác từ UI này. Tiếp tục?`,
    );
    if (!ok) return;

    setSoftDeleting(true);
    jobsService
      .confirmPosVoucherDetailSoftDeleteExtra(detailRunId, {
        masterIds: mastersForDelete.map((m) => m.id),
        connectorKey: connectorKey ?? null,
      })
      .then((r) => {
        const parts = [
          `soft-delete ${r.detailsSoftDeleted.toLocaleString('vi-VN')}`,
          r.detailsNotFound > 0 ? `đã xóa sẵn ${r.detailsNotFound}` : null,
          r.detailsFailed > 0 ? `lỗi ${r.detailsFailed}` : null,
          `HĐ ${r.invoicesSoftDeleted} / tiền mặt ${r.cashVouchersSoftDeleted}`,
        ].filter(Boolean);
        toast.success(parts.join(' · '));
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run) => {
        setDetailRun(run);
        if (detailPanel?.kind === 'extra') {
          const master = run.masters.find((m) => m.id === detailPanel.master.id);
          if (master) openDetails(master, 'extra', detailPage);
        }
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setSoftDeleting(false));
  };

  const confirmHardDeletePosDeleted = (connectorKey?: string, masterId?: string) => {
    if (!detailRunId || !detailRun) return;
    const predicate = (m: PosVoucherDetailReconcileMaster) =>
      m.status === 'Done' &&
      posDeletedOf(m) > 0 &&
      (!connectorKey || m.connectorKey === connectorKey) &&
      (!masterId || m.id === masterId);

    let mastersForDelete = masterId
      ? detailRun.masters.filter((m) => m.id === masterId && predicate(m))
      : (() => {
          const ids = resolveSelectedMasterIds(predicate);
          if (ids.length > 0) return detailRun.masters.filter((m) => ids.includes(m.id));
          return detailRun.masters.filter(predicate);
        })();

    if (mastersForDelete.length === 0) {
      toast.warning('Chọn master có CT POS xóa, hoặc lọc theo loại.');
      return;
    }

    const delSum = mastersForDelete.reduce((s, m) => s + posDeletedOf(m), 0);
    const ok = window.confirm(
      `Hard-delete ${delSum.toLocaleString('vi-VN')} CT ERP (POS đã soft-delete): unpost nếu Posted + xóa hàng DB.\n\nKhông hoàn tác. Tiếp tục?`,
    );
    if (!ok) return;

    setHardDeleting(true);
    confirmPosVoucherDetailHardDeletePosDeleted(detailRunId, {
      masterIds: mastersForDelete.map((m) => m.id),
      connectorKey: connectorKey ?? null,
    })
      .then((r: ConfirmHardDeletePosDeletedResult) => {
        const parts = [
          `hard-delete ${r.detailsHardDeleted.toLocaleString('vi-VN')}`,
          r.detailsNotFound > 0 ? `đã xóa sẵn ${r.detailsNotFound}` : null,
          r.detailsFailed > 0 ? `lỗi ${r.detailsFailed}` : null,
          `HĐ ${r.invoicesRemoved} / tiền mặt ${r.cashVouchersRemoved}`,
        ].filter(Boolean);
        toast.success(parts.join(' · '));
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run: PosVoucherDetailReconcileRun) => {
        setDetailRun(run);
        if (detailPanel?.kind === 'posDeleted') {
          const master = run.masters.find((m: PosVoucherDetailReconcileMaster) => m.id === detailPanel.master.id);
          if (master) openDetails(master, 'posDeleted', detailPage);
        }
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setHardDeleting(false));
  };

  const confirmRecheck = (masterId?: string) => {
    if (!detailRunId || !detailRun) return;
    const predicate = (m: PosVoucherDetailReconcileMaster) =>
      (m.status === 'Done' || m.status === 'Failed') &&
      (isMasterMismatch(m) || m.status === 'Failed') &&
      (!masterId || m.id === masterId);

    let masterIds = masterId
      ? detailRun.masters.filter((m) => m.id === masterId).map((m) => m.id)
      : resolveSelectedMasterIds((m) => m.status === 'Done' || m.status === 'Failed');
    if (masterIds.length === 0 && !masterId) {
      masterIds = detailRun.masters.filter(predicate).map((m) => m.id);
    }

    if (masterIds.length === 0) {
      toast.warning('Chọn kỳ Done/Failed để re-check (sau soft-delete/resync).');
      return;
    }

    const ok = window.confirm(
      `Re-check ${masterIds.length.toLocaleString('vi-VN')} kỳ (Tim* vs ERP lại)? Kết quả thiếu/thừa cũ sẽ bị ghi đè.`,
    );
    if (!ok) return;

    setRechecking(true);
    jobsService
      .recheckPosVoucherDetailMasters(detailRunId, { masterIds })
      .then((r) => {
        toast.success(`Đã enqueue re-check ${r.mastersRequeued.toLocaleString('vi-VN')} kỳ`);
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run) => {
        setDetailRun(run);
        setDetailPanel(null);
        masterSelection.clearSelection();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRechecking(false));
  };

  const stopDetailRun = () => {
    if (!detailRunId) return;
    const ok = window.confirm(
      'Dừng run đối soát Detail này? Các kỳ đang chạy sẽ bị hủy; kỳ đã xong vẫn giữ kết quả.',
    );
    if (!ok) return;

    setStopping(true);
    jobsService
      .stopPosVoucherDetailReconcile(detailRunId)
      .then((r) => {
        toast.success(
          `Đã dừng run · hủy ${r.mastersCancelled.toLocaleString('vi-VN')} kỳ · ${r.eventsCancelled.toLocaleString('vi-VN')} event`,
        );
        return jobsService.getPosVoucherDetailReconcileRun(detailRunId);
      })
      .then((run) => {
        setDetailRun(run);
        loadPastRuns();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setStopping(false));
  };

  const handleMasterFilterDateChange = React.useCallback(
    (from?: string, to?: string) => {
      if (!from && !to) return;
      if (filterViewMode !== 'day') setFilterViewMode('day');
      if (from) setFilterManualFrom(from);
      if (to) setFilterManualTo(to);
    },
    [filterViewMode],
  );

  const handleMasterFilterViewModeChange = React.useCallback(
    (mode: ViewMode) => {
      if (mode === filterViewMode) return;
      if (mode === 'day') {
        const current =
          filterViewMode === 'year'
            ? { fromDate: `${Number(filterYear)}-01-01`, toDate: `${Number(filterYear)}-12-31` }
            : computeReportPeriodDates(filterViewMode, filterMonth, filterYear, filterQuarter);
        setFilterManualFrom(current.fromDate || detailRun?.fromDate || '');
        setFilterManualTo(current.toDate || detailRun?.toDate || '');
      } else {
        setFilterManualFrom('');
        setFilterManualTo('');
      }
      if (mode === 'month') {
        setFilterMonth(nowMonth());
        setFilterYear(nowYear());
      } else if (mode === 'quarter') {
        setFilterQuarter(nowQuarter());
        setFilterYear(nowYear());
      } else if (mode === 'year') {
        setFilterYear(nowYear());
      }
      setFilterViewMode(mode);
    },
    [filterViewMode, filterMonth, filterYear, filterQuarter, detailRun?.fromDate, detailRun?.toDate],
  );

  const applyMasterFilter = React.useCallback(() => {
    setMasterPage(1);
    masterSelection.clearSelection();
  }, [masterSelection]);

  const activeListed = detailRunId ? pastRuns.find((r) => r.id === detailRunId) : undefined;
  const discoverJobId = detailRun?.dataSyncRunId ?? activeListed?.dataSyncRunId ?? null;
  const reconcileStillRunning =
    !!detailRun && (detailRun.status === 'Queued' || detailRun.status === 'Running');
  const resyncJobIds = React.useMemo(() => {
    const ids = new Set<string>();
    if (lastResyncJobId) ids.add(lastResyncJobId);
    detailRun?.masters.forEach((m) => {
      if (m.resyncDataSyncRunId) ids.add(m.resyncDataSyncRunId);
    });
    return [...ids];
  }, [detailRun, lastResyncJobId]);
  const canActOnMasters =
    !!detailRun &&
    detailRun.masters.some(
      (m) =>
        m.status === 'Done' &&
        (m.missingCount > 0 ||
          m.extraCount > 0 ||
          (m.changedCount ?? 0) > 0 ||
          posDeletedOf(m) > 0),
    );
  const canHardDeletePosDeleted =
    !!detailRun &&
    detailRun.masters.some((m) => m.status === 'Done' && posDeletedOf(m) > 0);
  const changedMasters = detailRun?.masters.filter(
    (m) => m.status === 'Done' && (m.changedCount ?? 0) > 0,
  ) ?? [];
  const canUpdateAllChanged = changedMasters.length > 0;
  const changedDocTotal = changedMasters.reduce((s, m) => s + (m.changedCount ?? 0), 0);
  const canRecheckMasters =
    !!detailRun &&
    detailRun.masters.some(
      (m) =>
        (m.status === 'Done' || m.status === 'Failed') &&
        (isMasterMismatch(m) || m.status === 'Failed'),
    );
  const canStopDetail =
    !!detailRun && (detailRun.status === 'Queued' || detailRun.status === 'Running');
  const canBulkByConnector = canActOnMasters;
  const doneMasters = detailRun?.masters.filter((m) => m.status === 'Done').length ?? 0;
  const totalMasters = detailRun?.masters.length ?? 0;
  const mismatchMasters = detailRun?.masters.filter(isMasterMismatch).length ?? 0;
  const busyActions = resyncing || softDeleting || hardDeleting || stopping || rechecking;

  return (
    <div className={styles.page} data-testid="pos-voucher-count-check-page">
      <AdminPermNavLinks
        data-testid="pos-count-perm-nav"
        className={styles.breadcrumb}
        items={[
          { to: '/admin/jobs', label: 'Job hub', permissionCode: 'admin:jobs:hub:read' },
          {
            to: '/admin/jobs/external-sync',
            label: 'Cấu hình sync REVA',
            permissionCode: 'admin:jobs:external-sync:read',
          },
        ]}
      />
      <h1 className={styles.title}>Đối soát số chứng từ POS</h1>
      <p className={styles.sub}>
        <strong>Count</strong> — probe Tim* totalItems vs ERP (toàn kỳ + tháng).{' '}
        <strong>Detail</strong> — enqueue Low events (parity resync POS): mỗi kỳ × loại chạy song song
        trên leader pool; tháng/ngày nào xong fill master trước. Bật <em>Tách theo ngày</em> khi khoảng
        dài (không giới hạn số ngày — leader tự queue). <em>Tất cả ĐVCS</em> = không lọc branch / không
        theo X-Company-Id shell. Click Job ID → External runs.
      </p>

      <div className={styles.panel}>
        <div className={styles.checkRow}>
          <label className={styles.checkboxLabel}>
            <input
              type="radio"
              name="pos-check-mode"
              checked={mode === 'count'}
              onChange={() => setMode('count')}
            />
            Count (nhanh)
          </label>
          <label className={styles.checkboxLabel}>
            <input
              type="radio"
              name="pos-check-mode"
              checked={mode === 'detail'}
              onChange={() => setMode('detail')}
            />
            Detail (job + bảng đối soát)
          </label>
        </div>

        <div className={styles.toolbarRow}>
          <label className={styles.pastRunLabel}>
            Lượt Detail trước
            <select
              value={detailRunId ?? ''}
              onChange={(e) => selectPastRun(e.target.value)}
              disabled={loadingPastRuns}
              data-testid="pos-count-past-run"
            >
              <option value="">
                {loadingPastRuns
                  ? 'Đang tải…'
                  : pastRuns.length === 0
                    ? '— Chưa có lượt Detail —'
                    : '— Chọn để xem lại —'}
              </option>
              {pastRuns.map((r) => (
                <option key={r.id} value={r.id}>
                  {runOptionLabel(r)}
                </option>
              ))}
            </select>
          </label>
          <Button
            type="button"
            onClick={loadPastRuns}
            disabled={loadingPastRuns}
            data-testid="pos-count-refresh-runs"
          >
            Làm mới danh sách
          </Button>
          <Button
            type="button"
            onClick={() => {
              if (!detailRunId) {
                toast.warning('Chọn một lượt Detail trong danh sách.');
                return;
              }
              selectPastRun(detailRunId);
              toast.success('Đã mở chi tiết lượt đối soát.');
            }}
            disabled={!detailRunId || loadingPastRuns}
            data-testid="pos-count-view-run"
          >
            Xem lượt
          </Button>
        </div>

        {activeListed?.errorMessage && (
          <p className={styles.err} data-testid="pos-count-listed-error">
            {activeListed.errorMessage}
          </p>
        )}

        <div className={styles.toolbarRow}>
          <label>
            Đơn vị cơ sở
            <select
              value={companyCode}
              onChange={(e) => {
                setCompanyCode(e.target.value);
                if (e.target.value) setActiveCompanyCode(e.target.value);
              }}
              data-testid="pos-count-company"
            >
              <option value="">Tất cả đơn vị cơ sở</option>
              {companies.map((c) => (
                <option key={c.id} value={c.id}>
                  {c.id} — {c.name}
                </option>
              ))}
            </select>
          </label>
          <label>
            Từ ngày
            <input
              type="date"
              value={fromDate}
              onChange={(e) => setFromDate(e.target.value)}
              data-testid="pos-count-from"
            />
          </label>
          <label>
            Đến ngày
            <input
              type="date"
              value={toDate}
              onChange={(e) => setToDate(e.target.value)}
              data-testid="pos-count-to"
            />
          </label>
        </div>

        <div className={styles.checkRow}>
          {CONNECTORS.map((c) => (
            <label key={c.key} className={styles.checkboxLabel}>
              <input
                type="checkbox"
                checked={selectedKeys.includes(c.key)}
                onChange={() => toggleKey(c.key)}
              />
              {c.label}
            </label>
          ))}
          {mode === 'detail' && (
            <label className={styles.checkboxLabel} data-testid="pos-count-split-by-day">
              <input
                type="checkbox"
                checked={splitByDay}
                onChange={(e) => setSplitByDay(e.target.checked)}
              />
              Tách theo ngày (song song từng ngày)
            </label>
          )}
        </div>

        <Button
          type="button"
          onClick={mode === 'count' ? runCountCheck : startDetailJob}
          disabled={loading}
          data-testid="pos-count-run"
        >
          {loading
            ? 'Đang chạy…'
            : mode === 'count'
              ? 'Chạy đối soát Count'
              : 'Tạo job Detail'}
        </Button>
      </div>

      {mode === 'count' && result && (
        <div className={styles.panel} data-testid="pos-count-result">
          <div className={styles.summary}>
            <span>
              {result.allCompanies || result.companyCode === '*'
                ? 'Tất cả ĐVCS'
                : `${result.companyCode}${
                    result.posBranchId != null ? ` (POS branchId=${result.posBranchId})` : ''
                  }`}{' '}
              · {result.fromDate} → {result.toDate} · TZ {result.timezone}
            </span>
            <span className={result.allMatch ? styles.ok : styles.warn}>
              POS Σ {result.posTotalSum.toLocaleString('vi-VN')} · ERP CT Σ{' '}
              {result.erpTotalSum.toLocaleString('vi-VN')} · ERP dòng Σ{' '}
              {(result.erpLineTotalSum ?? 0).toLocaleString('vi-VN')} · Δ{' '}
              {result.deltaSum.toLocaleString('vi-VN')}
            </span>
          </div>

          {result.rows.map((row: PosVoucherCountCheckRow) => (
            <div key={row.connectorKey} className={styles.connectorBlock}>
              <div className={styles.connectorTitle}>
                {row.label}{' '}
                <code className={styles.mutedInline}>{row.connectorKey}</code>
                <span className={`${styles.badge} ${statusClass(row.status)}`}>
                  {statusLabel(row.status)}
                </span>
              </div>
              <table className={styles.table}>
                <thead>
                  <tr>
                    <th>Kỳ</th>
                    <th>POS CT</th>
                    <th>ERP CT</th>
                    <th>Δ CT</th>
                    <th>ERP dòng</th>
                    <th>Trạng thái</th>
                    <th>Ghi chú</th>
                  </tr>
                </thead>
                <tbody>
                  <tr className={styles.totalsRow}>
                    <td>
                      <strong>{periodLabel(row.totals)}</strong>
                    </td>
                    <PeriodCells period={row.totals} />
                  </tr>
                  {(row.months ?? []).map((m) => (
                    <tr key={m.periodKey}>
                      <td>{periodLabel(m)}</td>
                      <PeriodCells period={m} />
                    </tr>
                  ))}
                </tbody>
              </table>
              <p className={styles.hint}>{row.erpMatchHint}</p>
            </div>
          ))}
        </div>
      )}

      {mode === 'detail' && detailRun && (
        <div className={styles.panel} data-testid="pos-detail-reconcile-result">
          <div className={styles.summary}>
            <span>
              Run đối soát <code>{detailRun.id}</code>
              {' · '}
              {detailRun.companyScope} · {detailRun.fromDate} → {detailRun.toDate}
              {detailRun.splitByDay ? ' · theo ngày' : ' · theo tháng'} ·{' '}
              <span className={statusClass(detailRun.status)}>{statusLabel(detailRun.status)}</span>
              {totalMasters > 0
                ? ` · ${doneMasters}/${totalMasters} kỳ`
                : detailRun.progressMessage
                  ? ` · ${detailRun.progressMessage}`
                  : ''}
              {mismatchMasters > 0
                ? ` · lệch ${mismatchMasters.toLocaleString('vi-VN')}`
                : ''}
            </span>
            {canStopDetail && (
              <Button
                type="button"
                onClick={stopDetailRun}
                disabled={busyActions}
                data-testid="pos-detail-stop-run"
              >
                {stopping ? 'Đang dừng…' : 'Dừng run'}
              </Button>
            )}
            {canActOnMasters && (
              <>
                <Button
                  type="button"
                  onClick={() => confirmSoftDeleteExtra()}
                  disabled={busyActions}
                  data-testid="pos-detail-soft-delete-extra"
                >
                  {softDeleting ? 'Đang soft-delete…' : 'Soft-delete thừa (đã chọn / tất cả lệch)'}
                </Button>
                {canHardDeletePosDeleted && (
                  <Button
                    type="button"
                    onClick={() => confirmHardDeletePosDeleted()}
                    disabled={busyActions}
                    data-testid="pos-detail-hard-delete-pos-deleted"
                  >
                    {hardDeleting
                      ? 'Đang hard-delete…'
                      : 'Hard-delete POS xóa (đã chọn / tất cả lệch)'}
                  </Button>
                )}
                <Button type="button" onClick={() => confirmResync()} disabled={busyActions}>
                  {resyncing ? 'Đang enqueue…' : 'Resync thiếu (đã chọn / tất cả lệch)'}
                </Button>
                {canUpdateAllChanged && (
                  <Button
                    type="button"
                    onClick={updateAllChangedToLatest}
                    disabled={busyActions}
                    data-testid="pos-detail-update-all-changed"
                  >
                    {resyncing
                      ? 'Đang enqueue…'
                      : `Update all to latest (${changedDocTotal.toLocaleString('vi-VN')} đổi)`}
                  </Button>
                )}
              </>
            )}
            {canRecheckMasters && (
              <Button
                type="button"
                onClick={() => confirmRecheck()}
                disabled={busyActions}
                data-testid="pos-detail-recheck"
              >
                {rechecking ? 'Đang re-check…' : 'Re-check (đã chọn / tất cả lệch)'}
              </Button>
            )}
          </div>
          {detailRun.errorMessage && <p className={styles.err}>{detailRun.errorMessage}</p>}
          <p className={styles.hint} data-testid="pos-detail-status-hint">
            SSOT trạng thái đối soát là dòng trên (Queued/Running/Xong). Checkbox header = chọn mọi
            dòng lệch trên trang hiện tại; bật «Chỉ dòng lệch» để lọc.
          </p>
          {discoverJobId && (
            <p className={styles.hint} data-testid="pos-detail-discover-job-hint">
              DataSync shell (period events / leader pool) —{' '}
              {reconcileStillRunning ? (
                <>
                  đối soát còn <strong>Đang chạy</strong>; External runs có thể hiện «Hoàn tất» nếu
                  shell cũ (trước fix) — không dùng làm trạng thái đối soát.{' '}
                </>
              ) : null}
              <InAppLink to={`/admin/jobs/external-runs?runId=${discoverJobId}`}>
                External runs · {discoverJobId.slice(0, 8)}…
              </InAppLink>
            </p>
          )}
          {resyncJobIds.length > 0 && (
            <p className={styles.hint} data-testid="pos-detail-resync-job-links">
              Job <strong>resync import</strong> (sau Confirm thiếu / Update all to latest):{' '}
              {resyncJobIds.map((id, i) => (
                <React.Fragment key={id}>
                  {i > 0 ? ' · ' : null}
                  <InAppLink to={`/admin/jobs/external-runs?runId=${id}`}>
                    Xem job {id.slice(0, 8)}…
                  </InAppLink>
                </React.Fragment>
              ))}
            </p>
          )}

          <div
            className={styles.masterFilterHost}
            data-lin-list-layout="erp-filter-bar"
            data-testid="pos-detail-master-filter-host"
          >
            <LinErpListFilterBar
              testIdPrefix={MASTER_GRID_PREFIX}
              dateLabel="Thời gian"
              expandDateRangeAriaLabel="Mở rộng khoảng ngày"
              searchAriaLabel="Lọc kỳ"
              fromDate={masterFilterFrom}
              toDate={masterFilterTo}
              onDateChange={handleMasterFilterDateChange}
              onSearch={applyMasterFilter}
              leading={(
                <>
                  <div data-testid={`${MASTER_GRID_PREFIX}-field-connector`}>
                    <Select
                      label="Loại chứng từ"
                      id={`${MASTER_GRID_PREFIX}-connector`}
                      value={filterConnectorKey}
                      onChange={(e) => setFilterConnectorKey(e.target.value)}
                      options={CONNECTOR_FILTER_OPTIONS}
                    />
                  </div>
                  <div data-testid={`${MASTER_GRID_PREFIX}-field-onlyMismatch`}>
                    <label className={styles.checkboxLabel}>
                      <input
                        type="checkbox"
                        checked={onlyMismatch}
                        onChange={(e) => {
                          setOnlyMismatch(e.target.checked);
                          masterSelection.clearSelection();
                        }}
                        data-testid="pos-detail-only-mismatch"
                      />
                      Chỉ hiện dòng lệch (thiếu/thừa/đổi/POS xóa) ·{' '}
                      {scopedMismatchCount.toLocaleString('vi-VN')} /{' '}
                      {scopedMasters.length.toLocaleString('vi-VN')}
                    </label>
                  </div>
                </>
              )}
              dateLeading={(
                <LinReportPeriodSelectorFields
                  testIdPrefix={MASTER_GRID_PREFIX}
                  labels={PERIOD_FILTER_LABELS}
                  viewMode={filterViewMode}
                  month={filterMonth}
                  year={filterYear}
                  quarter={filterQuarter}
                  yearOptions={FILTER_YEAR_OPTIONS}
                  onViewModeChange={handleMasterFilterViewModeChange}
                  onMonthChange={setFilterMonth}
                  onYearChange={setFilterYear}
                  onQuarterChange={setFilterQuarter}
                />
              )}
            />
            <div className={styles.masterFilterActions}>
              <Button
                type="button"
                onClick={() => {
                  if (selectableFiltered.length === 0) {
                    toast.warning('Không có dòng lệch có thể chọn.');
                    return;
                  }
                  masterSelection.selectAllInDatabase();
                  toast.success(
                    `Đã chọn ${selectableFiltered.length.toLocaleString('vi-VN')} dòng lệch (mọi trang).`,
                  );
                }}
                disabled={selectableFiltered.length === 0 || busyActions}
                data-testid="pos-detail-select-all-mismatch"
              >
                Chọn tất cả lệch
              </Button>
              <label>
                Số dòng/trang
                <select
                  value={masterPageSize}
                  onChange={(e) =>
                    setMasterPageSize(Number(e.target.value) || MASTER_PAGE_SIZE_DEFAULT)
                  }
                  data-testid="pos-detail-master-page-size"
                >
                  <option value={25}>25</option>
                  <option value={50}>50</option>
                  <option value={100}>100</option>
                </select>
              </label>
            </div>
          </div>

          <div className={styles.gridWrap}>
            <ErpDataListGrid
              testIdPrefix={MASTER_GRID_PREFIX}
              rows={pagedMasters}
              page={masterPage}
              pageSize={masterPageSize}
              selection={masterSelection}
              isRowSelectable={isMasterSelectable}
              getRowSelectDisabledReason={masterSelectDisabledReason}
              getRowId={getMasterId}
              headerCells={
                <>
                  <th>{detailRun.splitByDay ? 'Ngày' : 'Tháng'}</th>
                  <th>Loại</th>
                  <th>POS</th>
                  <th>ERP</th>
                  <th>Thiếu</th>
                  <th>Đổi</th>
                  <th>Thừa</th>
                  <th>POS xóa</th>
                  <th>Status</th>
                  <th>Resync</th>
                  <th>Thao tác</th>
                </>
              }
              renderRow={(m) => (
                <>
                  <td>{m.periodKey}</td>
                  <td>
                    {m.label}
                    <code className={styles.muted}>{m.connectorKey}</code>
                  </td>
                  <td>{m.posCount.toLocaleString('vi-VN')}</td>
                  <td>{m.erpCount.toLocaleString('vi-VN')}</td>
                  <td className={m.missingCount > 0 ? styles.warn : styles.ok}>
                    {m.missingCount.toLocaleString('vi-VN')}
                  </td>
                  <td className={(m.changedCount ?? 0) > 0 ? styles.warn : styles.ok}>
                    {(m.changedCount ?? 0).toLocaleString('vi-VN')}
                  </td>
                  <td className={m.extraCount > 0 ? styles.warn : ''}>
                    {m.extraCount.toLocaleString('vi-VN')}
                  </td>
                  <td className={posDeletedOf(m) > 0 ? styles.warn : styles.ok}>
                    {posDeletedOf(m).toLocaleString('vi-VN')}
                  </td>
                  <td className={statusClass(m.status)}>{statusLabel(m.status)}</td>
                  <td>
                    {m.resyncStatus}
                    {m.resyncDataSyncRunId ? (
                      <>
                        {' '}
                        <InAppLink
                          to={`/admin/jobs/external-runs?runId=${m.resyncDataSyncRunId}`}
                          className={styles.linkBtn}
                        >
                          Job resync
                        </InAppLink>
                      </>
                    ) : null}
                  </td>
                  <td className={styles.rowActions}>
                    {m.missingCount > 0 && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        onClick={() => openDetails(m, 'missing')}
                      >
                        Xem thiếu
                      </button>
                    )}{' '}
                    {(m.changedCount ?? 0) > 0 && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        onClick={() => openDetails(m, 'changed')}
                      >
                        Xem đổi
                      </button>
                    )}{' '}
                    {m.extraCount > 0 && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        onClick={() => openDetails(m, 'extra')}
                      >
                        Xem thừa
                      </button>
                    )}{' '}
                    {posDeletedOf(m) > 0 && (
                      <button
                        type="button"
                        className={styles.linkBtn}
                        onClick={() => openDetails(m, 'posDeleted')}
                      >
                        Xem POS xóa
                      </button>
                    )}
                    {m.status === 'Done' && m.missingCount > 0 && (
                      <>
                        {' '}
                        <button
                          type="button"
                          className={styles.linkBtn}
                          disabled={busyActions}
                          onClick={() => confirmResync(undefined, m.id, 'missing')}
                        >
                          Resync thiếu
                        </button>
                      </>
                    )}
                    {m.status === 'Done' && (m.changedCount ?? 0) > 0 && (
                      <>
                        {' '}
                        <button
                          type="button"
                          className={styles.linkBtn}
                          disabled={busyActions}
                          onClick={() => confirmResync(undefined, m.id, 'changed')}
                        >
                          Resync đổi
                        </button>
                      </>
                    )}
                    {m.status === 'Done' && m.extraCount > 0 && (
                      <>
                        {' '}
                        <button
                          type="button"
                          className={styles.linkBtn}
                          disabled={busyActions}
                          onClick={() => confirmSoftDeleteExtra(undefined, m.id)}
                        >
                          Soft-delete
                        </button>
                      </>
                    )}
                    {m.status === 'Done' && posDeletedOf(m) > 0 && (
                      <>
                        {' '}
                        <button
                          type="button"
                          className={styles.linkBtn}
                          disabled={busyActions}
                          onClick={() => confirmHardDeletePosDeleted(undefined, m.id)}
                        >
                          Hard-delete
                        </button>
                      </>
                    )}
                    {(m.status === 'Done' || m.status === 'Failed') && (
                      <>
                        {' '}
                        <button
                          type="button"
                          className={styles.linkBtn}
                          disabled={busyActions}
                          onClick={() => confirmRecheck(m.id)}
                        >
                          Re-check
                        </button>
                      </>
                    )}
                  </td>
                </>
              )}
            />
          </div>
          {masterTotal > 0 && (
            <div className={styles.gridFooter} data-testid="pos-detail-master-pagination">
              <Pagination
                currentPage={masterPage}
                totalPages={masterTotalPages}
                totalCount={masterTotal}
                pageSize={masterPageSize}
                itemLabel="kỳ"
                onPageChange={(p) => {
                  setMasterPage(p);
                  masterSelection.clearSelection();
                }}
              />
            </div>
          )}

          {canBulkByConnector && (
            <div className={styles.checkRow}>
              {CONNECTORS.filter((c) =>
                detailRun.masters.some((m) => m.connectorKey === c.key && m.missingCount > 0),
              ).map((c) => (
                <Button
                  key={`resync-${c.key}`}
                  type="button"
                  onClick={() => confirmResync(c.key, undefined, 'missing')}
                  disabled={busyActions}
                >
                  Resync thiếu · {c.label}
                </Button>
              ))}
              {CONNECTORS.filter((c) =>
                detailRun.masters.some(
                  (m) => m.connectorKey === c.key && (m.changedCount ?? 0) > 0,
                ),
              ).map((c) => (
                <Button
                  key={`resync-changed-${c.key}`}
                  type="button"
                  onClick={() => confirmResync(c.key, undefined, 'changed')}
                  disabled={busyActions}
                >
                  Resync đổi · {c.label}
                </Button>
              ))}
              {CONNECTORS.filter((c) =>
                detailRun.masters.some((m) => m.connectorKey === c.key && m.extraCount > 0),
              ).map((c) => (
                <Button
                  key={`softdel-${c.key}`}
                  type="button"
                  onClick={() => confirmSoftDeleteExtra(c.key)}
                  disabled={busyActions}
                >
                  Soft-delete thừa · {c.label}
                </Button>
              ))}
              {CONNECTORS.filter((c) =>
                detailRun.masters.some(
                  (m) => m.connectorKey === c.key && posDeletedOf(m) > 0,
                ),
              ).map((c) => (
                <Button
                  key={`harddel-${c.key}`}
                  type="button"
                  onClick={() => confirmHardDeletePosDeleted(c.key)}
                  disabled={busyActions}
                >
                  Hard-delete POS xóa · {c.label}
                </Button>
              ))}
            </div>
          )}
        </div>
      )}

      {detailPanel && (
        <div className={styles.panel}>
          <div className={styles.connectorTitle}>
            {detailPanel.master.periodKey} · {detailPanel.master.label} · {detailPanel.kind} (
            {detailPanel.total.toLocaleString('vi-VN')})
            <button type="button" className={styles.linkBtn} onClick={() => setDetailPanel(null)}>
              Đóng
            </button>
          </div>
          <div className={styles.gridWrap}>
            <ErpDataListGrid
              testIdPrefix={DETAIL_GRID_PREFIX}
              rows={detailItems}
              page={detailPage}
              pageSize={detailPageSize}
              selection={detailSelection}
              isRowSelectable={() => false}
              getRowId={getDetailId}
              headerCells={
                <>
                  <th>Document key</th>
                  <th>ERP mã</th>
                  <th>ERP ĐVCS</th>
                  <th>Resync</th>
                  <th>Ghi chú</th>
                </>
              }
              renderRow={(d) => (
                <>
                  <td>
                    <code>{d.documentKey}</code>
                  </td>
                  <td>{d.erpVoucherCode ?? '—'}</td>
                  <td>{d.erpCompanyCode ?? '—'}</td>
                  <td>{d.resyncStatus}</td>
                  <td className={d.note ? styles.warn : undefined}>{d.note ?? '—'}</td>
                </>
              )}
            />
          </div>
          {detailTotal > 0 && (
            <div className={styles.gridFooter} data-testid="pos-detail-keys-pagination">
              <Pagination
                currentPage={detailPage}
                totalPages={detailTotalPages}
                totalCount={detailTotal}
                pageSize={detailPageSize}
                itemLabel="CT"
                onPageChange={(p) => openDetails(detailPanel.master, detailPanel.kind, p)}
              />
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default PosVoucherCountCheckPage;
