import React, { useMemo } from 'react';
import { InAppLink } from '../../router/InAppLink';
import { useNavTitle } from '@linm-soft-org/linm-web-common-components';
import { ADMIN_HOME_NAV } from '../../config/adminPages';
import { useAdminPermissions } from '../../hooks/useAdminPermissions';
import { filterAdminNavByPermission } from '../../components/auth/AdminPermNavLinks';
import styles from './AdminHomePage.module.css';

const AdminHomePage: React.FC = () => {
  useNavTitle('Admin');
  const { hasPermission, loading } = useAdminPermissions();

  const links = useMemo(
    () => filterAdminNavByPermission(ADMIN_HOME_NAV, hasPermission),
    [hasPermission],
  );

  return (
    <div className={styles.page} data-testid="admin-home-page">
      <h1 className={styles.greeting}>Quản trị hệ thống</h1>
      <p className={styles.sub}>Chọn module — theo quyền gói (permission), không theo menu path</p>
      {loading ? (
        <p className={styles.sub} data-testid="admin-home-loading">
          <i className="fas fa-spinner fa-spin" style={{ marginRight: 8 }} />
          Đang tải quyền truy cập…
        </p>
      ) : links.length === 0 ? (
        <p className={styles.sub} data-testid="admin-home-empty">
          Không có module nào trong gói quyền của bạn.
        </p>
      ) : (
        <ul className={styles.links}>
          {links.map((item) => (
            <li key={item.path}>
              <InAppLink to={item.path}>{item.label}</InAppLink>
              {item.description ? (
                <span className={styles.linkDesc}> — {item.description}</span>
              ) : null}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default AdminHomePage;
