import React from 'react';
import { Button } from '../../../ui';
import { jobsService, type PosSalesInvoiceVatRefillPreview } from '../../../services/jobs';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';

type Props = {
  onRunStarted: (runId: string) => void;
};

const ExternalSyncVatRefillPanel: React.FC<Props> = ({ onRunStarted }) => {
  const toast = useAppToast();
  const [fromDate, setFromDate] = React.useState('');
  const [toDate, setToDate] = React.useState('');
  const [preview, setPreview] = React.useState<PosSalesInvoiceVatRefillPreview | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [running, setRunning] = React.useState(false);
  const [searched, setSearched] = React.useState(false);

  const loadPreview = React.useCallback(() => {
    setLoadingPreview(true);
    setSearched(true);
    jobsService
      .getPosSalesInvoiceVatRefillPreview(fromDate || null, toDate || null)
      .then(setPreview)
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setLoadingPreview(false));
  }, [fromDate, toDate, toast]);

  const handleDateChange = React.useCallback((field: 'from' | 'to', value: string) => {
    if (field === 'from') setFromDate(value);
    else setToDate(value);
    setPreview(null);
    setSearched(false);
  }, []);

  const handleRun = React.useCallback(() => {
    if (!searched || !preview?.eligibleCount) {
      toast.warning('Bấm Tìm trước — không có HĐ POS trong khoảng đã chọn.');
      return;
    }
    const range =
      fromDate || toDate ? `\nKhoảng ngày HĐ: ${fromDate || '…'} → ${toDate || '…'}` : '';
    const ok = window.confirm(
      `Re-import VAT cho tối đa 200 HĐ POS (gọi FM ChiTietHoaDon · áp lại tách thuế)?` +
        range +
        `\n\nĐủ điều kiện: ${preview.eligibleCount.toLocaleString('vi-VN')}`,
    );
    if (!ok) return;

    setRunning(true);
    jobsService
      .triggerPosSalesInvoiceVatRefill({ fromDate: fromDate || null, toDate: toDate || null })
      .then((result) => {
        if (result.runId) {
          toast.info(`Đã tạo job re-fill VAT — theo dõi run bên dưới.`);
          onRunStarted(result.runId);
          return;
        }
        toast.success(
          `VAT refill: cập nhật ${result.refilledCount.toLocaleString('vi-VN')} HĐ` +
            (result.failedCount ? ` · lỗi ${result.failedCount.toLocaleString('vi-VN')}` : ''),
        );
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRunning(false));
  }, [searched, preview, fromDate, toDate, toast, onRunStarted]);

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '12px 16px',
        border: '1px solid #e2e8f0',
        borderRadius: 8,
        background: '#f8fafc',
      }}
      data-testid="pos-vat-refill-panel"
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: 12, alignItems: 'flex-start', justifyContent: 'space-between' }}>
        <div style={{ flex: '1 1 280px' }}>
          <strong>Re-fill VAT HĐ POS (FM ChiTietHoaDon)</strong>
          <p style={{ margin: '4px 0 0', color: '#64748b', fontSize: 13 }}>
            Re-import tối đa 200 HĐ/lần — áp lại tách thuế từ FM. HĐ EIssued bỏ qua.
          </p>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, marginTop: 8, alignItems: 'center' }}>
            <label style={{ fontSize: 13 }}>
              Từ ngày{' '}
              <input type="date" value={fromDate} onChange={(e) => handleDateChange('from', e.target.value)} data-testid="vat-refill-from-date" />
            </label>
            <label style={{ fontSize: 13 }}>
              Đến ngày{' '}
              <input type="date" value={toDate} onChange={(e) => handleDateChange('to', e.target.value)} data-testid="vat-refill-to-date" />
            </label>
          </div>
          {loadingPreview ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>Đang đếm…</p>
          ) : preview && searched ? (
            <p style={{ margin: '6px 0 0', fontSize: 13 }}>
              Đủ điều kiện: <strong>{preview.eligibleCount.toLocaleString('vi-VN')}</strong>
              {' '}(Draft {preview.draftCount.toLocaleString('vi-VN')} · Posted {preview.postedCount.toLocaleString('vi-VN')})
            </p>
          ) : (
            <p style={{ margin: '6px 0 0', fontSize: 13, color: '#64748b' }}>Chọn khoảng ngày HĐ và bấm Tìm.</p>
          )}
        </div>
        <div style={{ display: 'flex', gap: 8, alignItems: 'center' }}>
          <Button type="button" variant="secondary" onClick={loadPreview} disabled={loadingPreview || running} data-testid="vat-refill-refresh">
            Tìm
          </Button>
          <Button
            type="button"
            onClick={handleRun}
            disabled={running || loadingPreview || !searched || !preview?.eligibleCount}
            data-testid="vat-refill-trigger"
          >
            {running ? 'Đang tạo job…' : 'Re-fill VAT'}
          </Button>
        </div>
      </div>
    </div>
  );
};

export default ExternalSyncVatRefillPanel;
