import React, { Suspense } from 'react';
import { MemoryRouter, Routes, Route, Navigate, Outlet } from 'react-router-dom';
import { Provider } from 'react-redux';
import { store } from './store/store';
import {
  AlertProvider,
  ReduxToastContainer,
  ToastProvider,
  SimpleNotFoundPage,
} from '@linm-soft-org/linm-web-common-components';
import { AppLayout } from './components/layout/AppLayout';
import { ProtectedRoute } from './components/auth/ProtectedRoute';
import { MemoryRouterSync } from './router/MemoryRouterSync';
import { showDevNav, isStandalone } from './dev/isStandalone';
import { StandaloneShell } from './standalone/StandaloneShell';
import { StandaloneMockNav } from './standalone/StandaloneMockNav';
import { StandaloneMockTopbar } from './standalone/StandaloneMockTopbar';
import AdminHomePage from './pages/AdminHomePage';
import AccountsManagementPage from './pages/AccountsManagementPage';
import LoginActivityPage from './pages/LoginActivityPage';
import PermissionsManagementPage from './pages/PermissionsManagementPage';
import ApiKeysManagementPage from './pages/ApiKeysManagementPage';
import CompaniesManagementPage from './pages/CompaniesManagementPage';
import DepartmentsManagementPage from './pages/DepartmentsManagementPage';
import EmployeesManagementPage from './pages/EmployeesManagementPage';
import DataCleanupPage from './pages/DataCleanupPage/DataCleanupPage';
import GoLiveCleanupPage from './pages/GoLiveCleanupPage/GoLiveCleanupPage';
import ReportSeedPage from './pages/ReportSeedPage/ReportSeedPage';
import JobsMonitoringHubPage from './pages/JobsMonitoring/JobsMonitoringHubPage';
import JobDashboardPage from './pages/JobsMonitoring/JobDashboardPage';
import JobScheduleConfigPage from './pages/JobsMonitoring/JobScheduleConfigPage';
import JobInternalPage from './pages/JobsMonitoring/JobInternalPage';
import DataSyncSetConfigPage from './pages/JobsMonitoring/DataSyncSetConfigPage';
import ExternalSyncRunsPage from './pages/JobsMonitoring/ExternalSyncRunsPage';
import MissingLedgerRunsPage from './pages/JobsMonitoring/MissingLedgerRunsPage';
import LegacyCashRunsPage from './pages/JobsMonitoring/LegacyCashRunsPage';
import LegacyInvoiceRunsPage from './pages/JobsMonitoring/LegacyInvoiceRunsPage';
import VatRefillRunsPage from './pages/JobsMonitoring/VatRefillRunsPage';
import PosInboundRunsPage from './pages/JobsMonitoring/PosInboundRunsPage';
import ExternalSyncVoucherRenumberPage from './pages/JobsMonitoring/ExternalSyncVoucherRenumberPage';
import PosBillOpsPage from './pages/JobsMonitoring/PosBillOpsPage';
import PosVoucherCountCheckPage from './pages/JobsMonitoring/PosVoucherCountCheckPage';
import JobEventsPage from './pages/JobsMonitoring/JobEventsPage';
import JobServerConfigPage from './pages/JobsMonitoring/JobServerConfigPage';
import ExternalSyncMonthSplitChainHost from './pages/JobsMonitoring/ExternalSyncMonthSplitChainHost';

const DevPage = React.lazy(() => import('./dev/DevPage'));

const initialPath =
  typeof window !== 'undefined'
    ? window.location.pathname + window.location.search || '/'
    : '/';

/** Standalone AppShell — Shell overflow only; Nav + Topbar + AppLayout siblings (SETUP-P2-17). */
const AppShell: React.FC = () => (
  <StandaloneShell>
    <StandaloneMockNav />
    <StandaloneMockTopbar />
    <AppLayout />
  </StandaloneShell>
);

const adminNestedRoutes = (
  <>
    <Route index element={<AdminHomePage />} />
    <Route path="accounts" element={<AccountsManagementPage />} />
    <Route path="login-activity" element={<LoginActivityPage />} />
    <Route path="companies" element={<CompaniesManagementPage />} />
    <Route path="departments" element={<DepartmentsManagementPage />} />
    <Route path="employees" element={<EmployeesManagementPage />} />
    <Route path="packages" element={<Navigate to="/admin/permissions?tab=packages" replace />} />
    <Route path="permissions" element={<PermissionsManagementPage />} />
    <Route path="api-keys" element={<ApiKeysManagementPage />} />
    <Route path="data-cleanup" element={<DataCleanupPage />} />
    <Route path="go-live-cleanup" element={<GoLiveCleanupPage />} />
    <Route path="report-seed" element={<ReportSeedPage />} />
    <Route path="jobs" element={<JobsMonitoringHubPage />} />
    <Route path="jobs/server-config" element={<JobServerConfigPage />} />
    <Route path="jobs/schedule" element={<JobScheduleConfigPage />} />
    <Route path="jobs/dashboard" element={<JobDashboardPage />} />
    <Route path="jobs/inbound" element={<JobDashboardPage />} />
    <Route path="jobs/pos-inbound-runs" element={<PosInboundRunsPage />} />
    <Route path="jobs/external-sync" element={<DataSyncSetConfigPage />} />
    <Route path="jobs/external-runs" element={<ExternalSyncRunsPage />} />
    <Route path="jobs/missing-ledger-runs" element={<MissingLedgerRunsPage />} />
    <Route path="jobs/legacy-cash-runs" element={<LegacyCashRunsPage />} />
    <Route path="jobs/legacy-invoice-runs" element={<LegacyInvoiceRunsPage />} />
    <Route path="jobs/vat-refill-runs" element={<VatRefillRunsPage />} />
    <Route path="jobs/voucher-renumber" element={<ExternalSyncVoucherRenumberPage />} />
    <Route path="jobs/pos-bill-ops" element={<PosBillOpsPage />} />
    <Route path="jobs/pos-voucher-count" element={<PosVoucherCountCheckPage />} />
    <Route path="jobs/outbound" element={<JobDashboardPage />} />
    <Route path="jobs/internal" element={<JobInternalPage />} />
    <Route path="jobs/events" element={<JobEventsPage />} />
    <Route path="*" element={<SimpleNotFoundPage showDevNav={showDevNav} homePath="/admin" />} />
  </>
);

const Root: React.FC = () => (
  <Provider store={store}>
    <AlertProvider>
      <ToastProvider>
        {isStandalone && <ReduxToastContainer />}
        <MemoryRouter initialEntries={[initialPath]} initialIndex={0}>
          <MemoryRouterSync />
          <Routes>
            {isStandalone ? (
              <Route element={<AppShell />}>
                {showDevNav && (
                  <Route path="/dev" element={<Suspense fallback={null}><DevPage /></Suspense>} />
                )}
                <Route path="/" element={<Navigate to="/dev" replace />} />
                <Route
                  path="/admin"
                  element={
                    <ProtectedRoute>
                      <>
                        <ExternalSyncMonthSplitChainHost />
                        <Outlet />
                      </>
                    </ProtectedRoute>
                  }
                >
                  {adminNestedRoutes}
                </Route>
              </Route>
            ) : (
              <>
                {showDevNav && (
                  <Route path="/dev" element={<Suspense fallback={null}><DevPage /></Suspense>} />
                )}
                <Route
                  path="/admin/*"
                  element={
                    <ProtectedRoute>
                      <>
                        <ExternalSyncMonthSplitChainHost />
                        <AppLayout />
                      </>
                    </ProtectedRoute>
                  }
                >
                  {adminNestedRoutes}
                </Route>
              </>
            )}
          </Routes>
        </MemoryRouter>
      </ToastProvider>
    </AlertProvider>
  </Provider>
);

export default Root;
