import { connectorLabel } from './externalSyncRunDisplay';

/** ERP form view path for REVA external sync converted vouchers. */
const CONNECTOR_VIEW_PATH: Record<string, (id: string) => string> = {
  'reva-fm-phieu-thu': (id) => `/kt/pt/${id}`,
  'reva-fm-phieu-chi': (id) => `/kt/pc/${id}`,
  'reva-fm-hoa-don': (id) => `/bh/hoa-don/${id}`,
  'reva-fm-bao-co': (id) => `/kt/bao-co/${id}`,
  'reva-fm-bao-no': (id) => `/kt/bao-no/${id}`,
};

/** Prefix mã CT ERP → shell route (SSOT: cash=PT/PC, bank=BC/BN). */
const CODE_PREFIX_VIEW_PATH: Array<{ prefix: string; build: (id: string) => string }> = [
  { prefix: 'PT-', build: (id) => `/kt/pt/${id}` },
  { prefix: 'PC-', build: (id) => `/kt/pc/${id}` },
  { prefix: 'INV-', build: (id) => `/bh/hoa-don/${id}` },
  { prefix: 'BC-', build: (id) => `/kt/bao-co/${id}` },
  { prefix: 'BN-', build: (id) => `/kt/bao-no/${id}` },
  { prefix: 'UNC-', build: (id) => `/kt/uy-nhiem-chi/${id}` },
];

/** Nhãn loại CT theo prefix mã ERP — ưu tiên hơn connector (phieu-thu có thể ra BC). */
const CODE_PREFIX_LABELS: Array<{ prefix: string; label: string }> = [
  { prefix: 'PT-', label: 'Phiếu thu tiền mặt' },
  { prefix: 'PC-', label: 'Phiếu chi tiền mặt' },
  { prefix: 'BC-', label: 'Giấy báo có (ngân hàng)' },
  { prefix: 'BN-', label: 'Giấy báo nợ (ngân hàng)' },
  { prefix: 'UNC-', label: 'Ủy nhiệm chi' },
  { prefix: 'INV-', label: 'Hóa đơn bán' },
  { prefix: 'FM-HD-', label: 'Hóa đơn bán (placeholder)' },
  { prefix: 'FM-PT-', label: 'Phiếu thu (placeholder)' },
  { prefix: 'FM-PC-', label: 'Phiếu chi (placeholder)' },
];

function buildPathForSet(setName: string, voucherId: string): string | null {
  const key = setName.trim().toLowerCase();
  const byConnector = CONNECTOR_VIEW_PATH[key];
  if (byConnector) return byConnector(voucherId);
  return null;
}

function buildPathForCode(voucherCode: string, voucherId: string): string | null {
  const upper = voucherCode.trim().toUpperCase();
  for (const { prefix, build } of CODE_PREFIX_VIEW_PATH) {
    if (upper.startsWith(prefix)) return build(voucherId);
  }
  return null;
}

/** Whether Mã CT ERP can open an ERP form (by connector or code prefix). */
export function isExternalSyncVoucherLinkable(
  setName: string,
  voucherCode?: string | null,
): boolean {
  if (voucherCode?.trim()) {
    const upper = voucherCode.trim().toUpperCase();
    if (CODE_PREFIX_VIEW_PATH.some(({ prefix }) => upper.startsWith(prefix))) return true;
  }
  const key = setName.trim().toLowerCase();
  return key in CONNECTOR_VIEW_PATH;
}

/**
 * Shell route to open ERP voucher form (Finance / Sales MFE).
 * Prefer mã CT prefix (BC-/BN-/PT-/PC-) over connector — bank channel → báo có/nợ.
 */
export function resolveExternalSyncVoucherViewPath(
  setName: string,
  voucherId?: string | null,
  voucherCode?: string | null,
): string | null {
  if (!voucherId) return null;
  const id = voucherId.trim();
  if (!id) return null;

  if (voucherCode?.trim()) {
    const byCode = buildPathForCode(voucherCode, id);
    if (byCode) return byCode;
  }

  return buildPathForSet(setName, id);
}

/** Nhãn cột Loại — ưu tiên prefix mã ERP, fallback connector. */
export function labelExternalSyncVoucherType(
  setName: string,
  voucherCode?: string | null,
): string {
  const code = voucherCode?.trim();
  if (code) {
    const upper = code.toUpperCase();
    for (const { prefix, label } of CODE_PREFIX_LABELS) {
      if (upper.startsWith(prefix)) return label;
    }
  }
  return connectorLabel(setName);
}
