import React from 'react';
import type { ExternalSyncOrchestration } from '../../../services/jobs/dataSyncModels';
import { JobDetailCollapsibleSection, JobDetailMetaGrid, formatJobDate } from './JobDetailMetaGrid';
import { formatDurationMs } from '../externalSyncRunDisplay';
import styles from '../JobInternalPage.module.css';

export type ExternalSyncRunOrchestrationSectionProps = {
  orchestration: ExternalSyncOrchestration;
  defaultOpen?: boolean;
};

const resolveBatchSize = (orchestration: ExternalSyncOrchestration): number =>
  Math.max(1, orchestration.detailBatchSize ?? orchestration.detailParallelJobs);

const resolveConcurrentBatches = (orchestration: ExternalSyncOrchestration): number =>
  Math.max(1, orchestration.concurrentDetailBatches ?? 2);

const resolveImportConcurrency = (orchestration: ExternalSyncOrchestration): number =>
  Math.max(1, orchestration.detailImportConcurrency ?? 16);

const resolveDocsCapTotal = (orchestration: ExternalSyncOrchestration): number => {
  if (orchestration.maxInFlightDocsTotal != null && orchestration.maxInFlightDocsTotal > 0) {
    return orchestration.maxInFlightDocsTotal;
  }
  if (orchestration.totalDetailParallelJobs != null && orchestration.totalDetailParallelJobs > 0) {
    return orchestration.totalDetailParallelJobs;
  }
  const perLane =
    orchestration.maxInFlightDocsPerLane ??
    resolveBatchSize(orchestration) * resolveConcurrentBatches(orchestration);
  return Math.max(1, orchestration.searchLaneCount) * Math.max(1, perLane);
};

export const ExternalSyncRunOrchestrationSection: React.FC<ExternalSyncRunOrchestrationSectionProps> = ({
  orchestration,
  defaultOpen = true,
}) => {
  const isRepost = orchestration.isLedgerRepost === true;
  const phaseRows = orchestration.phaseTimings.filter(
    (p) => p.completedCount > 0 || p.activeCount > 0 || p.failedCount > 0,
  );
  const batchSize = resolveBatchSize(orchestration);
  const concurrentBatches = resolveConcurrentBatches(orchestration);
  const importConcurrency = resolveImportConcurrency(orchestration);
  const docsCapTotal = resolveDocsCapTotal(orchestration);
  const perLaneCap =
    orchestration.maxInFlightDocsPerLane ?? batchSize * concurrentBatches;
  const laneStats = orchestration.laneStats ?? [];
  const liveTotal = orchestration.liveTotalDetailParallelJobs;
  const liveLanes = orchestration.liveSearchLaneCount;
  const liveDetail = orchestration.liveDetailParallelJobs;
  const configAligned = orchestration.repostConfigAligned;
  const checkpointsProcessing =
    orchestration.checkpointsProcessing ??
    laneStats.reduce((sum, l) => sum + l.processing, 0);
  const batchEventsInFlight = orchestration.detailBatchEventsInFlight ?? 0;
  const batchEventsDone = orchestration.detailBatchEventsCompleted ?? 0;
  const maxBatchEvents = Math.max(1, orchestration.searchLaneCount) * concurrentBatches;

  const repostMetaItems = isRepost
    ? [
        {
          label: 'Config run vs DB',
          value:
            configAligned === true
              ? 'Khớp — post song song đúng config'
              : configAligned === false
                ? `Lệch — run ${orchestration.detailParallelJobs}, DB ${orchestration.liveParallelBatchJobs ?? '?'}`
                : '—',
          fullWidth: true,
        },
        {
          label: 'Post song song (leader cap)',
          value: `${orchestration.detailSlotsInUse} / ${docsCapTotal}`,
        },
        {
          label: 'Post import đang chạy (queue)',
          value:
            orchestration.postEventsInFlight != null
              ? orchestration.postEventsInFlight.toLocaleString('vi-VN')
              : '—',
        },
        {
          label: 'Checkpoint Processing',
          value:
            orchestration.checkpointsProcessingCap != null
              ? `${(orchestration.batchSlotsInUse ?? orchestration.detailSlotsInUse).toLocaleString('vi-VN')} / ${orchestration.checkpointsProcessingCap.toLocaleString('vi-VN')}`
              : '—',
        },
      ]
    : [];

  const syncMetaItems = !isRepost
    ? [
        {
          label: 'Chế độ',
          value:
            orchestration.syncMode === 'refill'
              ? 'Re-fill'
              : orchestration.syncMode === 'resync'
                ? 'Re-sync'
                : orchestration.syncMode ?? '—',
        },
        {
          label: 'Đã xóa (wipe / thừa)',
          value: `${(orchestration.purgeRemovedCount ?? 0).toLocaleString('vi-VN')} wipe · ${(orchestration.extraSoftDeletedCount ?? 0).toLocaleString('vi-VN')} thừa`,
        },
        {
          label: 'Search leader (run)',
          value: orchestration.searchLaneCount,
        },
        {
          label: 'CT / batch event (detailBatchSize)',
          value: `${batchSize} · 1 POS ChiTiet*Batch / event`,
        },
        {
          label: 'Batch event song song / lane',
          value: concurrentBatches,
        },
        {
          label: 'CPU import / batch (detailImportConcurrency)',
          value: importConcurrency,
        },
        {
          label: 'Cap docs in-flight (run)',
          value: `${docsCapTotal.toLocaleString('vi-VN')} (${orchestration.searchLaneCount} lane × ${batchSize} CT × ${concurrentBatches} batch)`,
        },
        {
          label: 'Docs đang giữ slot',
          value: `${orchestration.detailSlotsInUse.toLocaleString('vi-VN')} / ${docsCapTotal.toLocaleString('vi-VN')}`,
        },
        {
          label: 'Batch job đang chạy',
          value: `${batchEventsInFlight.toLocaleString('vi-VN')} / ${maxBatchEvents} · xong ${batchEventsDone.toLocaleString('vi-VN')}`,
        },
        {
          label: 'Checkpoint Processing (raw)',
          value:
            checkpointsProcessing > docsCapTotal
              ? `${checkpointsProcessing.toLocaleString('vi-VN')} ⚠ > cap (kẹt/heal)`
              : checkpointsProcessing.toLocaleString('vi-VN'),
        },
        {
          label: 'Pool chờ dispatch',
          value: orchestration.detailPoolPending.toLocaleString('vi-VN'),
        },
        {
          label: 'Thời gian run',
          value: formatDurationMs(orchestration.runDurationMs),
        },
      ]
    : [];

  return (
    <JobDetailCollapsibleSection
      title={isRepost ? 'Leader re-post (PostImport 1:1)' : 'Leader pool · detail batch'}
      defaultOpen={defaultOpen}
    >
      <JobDetailMetaGrid
        items={[
          {
            label: 'Leader (worker dispatch)',
            value: orchestration.leaderWorkerId ?? '—',
            mono: Boolean(orchestration.leaderWorkerId),
            fullWidth: true,
          },
          {
            label: 'Lần dispatch gần nhất',
            value: orchestration.lastLeaderDispatchAtUtc
              ? formatJobDate(orchestration.lastLeaderDispatchAtUtc)
              : '—',
          },
          {
            label: 'Chế độ',
            value: [
              orchestration.dispatchMode === 'leaderPool' ? 'Leader pool' : orchestration.dispatchMode,
              isRepost
                ? 'PostImport trực tiếp (1 CT / slot)'
                : orchestration.searchMode === 'sequential'
                  ? 'Search tuần tự'
                  : orchestration.searchMode === 'parallelLanes'
                    ? `Search ${orchestration.searchLaneCount} lane song song (run này)`
                    : orchestration.searchMode,
              orchestration.phase ? `Phase: ${orchestration.phase}` : null,
            ]
              .filter(Boolean)
              .join(' · ') || '—',
          },
          ...repostMetaItems,
          ...(isRepost
            ? [
                {
                  label: 'Cap post song song (run)',
                  value: docsCapTotal,
                },
                {
                  label: 'Detail parallel (run)',
                  value: orchestration.detailParallelJobs,
                },
                {
                  label: 'Slot post trống',
                  value: orchestration.detailSlotsAvailable,
                },
                {
                  label: 'Post đang giữ slot',
                  value: `${orchestration.detailSlotsInUse} / ${docsCapTotal}`,
                },
                {
                  label: 'Pool chờ dispatch',
                  value: orchestration.detailPoolPending.toLocaleString('vi-VN'),
                },
                {
                  label: 'Thời gian run',
                  value: formatDurationMs(orchestration.runDurationMs),
                },
              ]
            : syncMetaItems),
        ]}
      />

      {isRepost && configAligned === false ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Config DB hiện tại: <strong>{orchestration.liveParallelBatchJobs} post song song</strong>.
          Run này giữ snapshot lúc start: <strong>{orchestration.detailParallelJobs}</strong>.
          {' '}
          Muốn áp dụng config mới → dừng run và chạy lại Re-Post.
        </p>
      ) : null}

      {!isRepost && liveTotal != null && liveLanes != null && liveDetail != null ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Config DB hiện tại (sync mới):{' '}
          <strong>
            {liveLanes} leader · {liveDetail} CT/batch = cap {liveTotal} docs
          </strong>
          . Run này giữ <strong>{orchestration.searchLaneCount} leader</strong> đã enqueue lúc start
          {orchestration.snapshotDetailParallelJobs != null
            ? ` · CT/batch lúc start ${orchestration.snapshotDetailParallelJobs}`
            : ''}
          .
          {' '}
          <strong>
            Muốn config mới → Dừng run + Resync
          </strong>{' '}
          (snapshot không đổi giữa run).
        </p>
      ) : null}

      {!isRepost ? (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: liveTotal != null ? 8 : 12 }}>
          <strong>detailBatchSize = {batchSize}</strong> CT / 1 job{' '}
          <code>ExternalDetailBatchRequested</code> (1 POST ChiTiet*Batch khi bật) —{' '}
          <strong>không</strong> = {batchSize} job song song.
          CPU trong batch = <code>detailImportConcurrency</code> ({importConcurrency}).
          Cap docs = {orchestration.searchLaneCount}×{batchSize}×{concurrentBatches}.
          Hard cap event ={' '}
          <strong>
            {orchestration.activePlatformEvents ?? '—'} /{' '}
            {orchestration.maxActivePlatformEvents ?? 20}
          </strong>{' '}
          (planned peak {orchestration.plannedPeakPlatformEvents ?? '—'}).
          Lưu config DB không đổi run đang chạy — <strong>Dừng + Resync</strong>.
        </p>
      ) : (
        <p className={styles.detailSummaryHeroHint} style={{ marginTop: 12 }}>
          Leader cap <strong>{docsCapTotal}</strong> · batch prepare{' '}
          <strong>{orchestration.itemsPerBatch ?? docsCapTotal}</strong> CT/event (
          <code>LedgerRepost.BatchRequested</code>, Task.WhenAll) · GL: 1{' '}
          <code>PostImport</code>/CT. Throughput GL phụ thuộc{' '}
          <strong>LowWorkerInstanceCount</strong> — nên ≥ cap post.
        </p>
      )}

      {!isRepost &&
      (orchestration.renumberBatchSize != null ||
        orchestration.renumberParallelism != null ||
        orchestration.renumberGroupByDay != null) ? (
        <>
          <JobDetailMetaGrid
            items={[
              {
                label: 'Đánh số — batch (CT/group)',
                value: orchestration.renumberBatchSize ?? '—',
              },
              {
                label: 'Đánh số — song song (ngày×loại)',
                value: orchestration.renumberParallelism ?? '—',
              },
              {
                label: 'Đánh số — gom theo',
                value:
                  orchestration.renumberGroupByDay === true
                    ? 'Ngày CT'
                    : orchestration.renumberGroupByDay === false
                      ? 'Tháng CT'
                      : '—',
              },
              {
                label: 'Đánh số — interval batch (s)',
                value: orchestration.renumberIntervalSeconds ?? '—',
              },
              {
                label: 'Bucket ngày×loại (run)',
                value:
                  orchestration.renumberDayBucketCount != null
                    ? orchestration.renumberDayBucketCount.toLocaleString('vi-VN')
                    : '—',
              },
              {
                label: 'Capacity groups (run)',
                value:
                  orchestration.renumberGroupCount != null
                    ? orchestration.renumberGroupCount.toLocaleString('vi-VN')
                    : '—',
              },
            ]}
          />
          <p className={styles.detailSummaryHeroHint} style={{ marginTop: 8 }}>
            Phase <strong>Đánh số + ghi sổ</strong>: song song theo ngày×loại (không race IdCode cùng ngày).
            Post song song theo <code>renumberParallelism</code>. Config connector tab pipeline / REVA.
          </p>
        </>
      ) : null}

      {!isRepost && laneStats.length > 0 ? (
        <div className={styles.detailTableWrap} style={{ marginTop: 12 }}>
          <table className={styles.detailTable} data-testid="external-sync-lane-stats">
            <thead>
              <tr>
                <th align="left">Lane</th>
                <th align="right">Pending</th>
                <th align="right">Processing (raw)</th>
                <th align="right">In-flight ước lượng</th>
                <th align="right">Cap docs</th>
                <th align="right">Slot trống</th>
              </tr>
            </thead>
            <tbody>
              {laneStats.map((lane) => {
                const effective =
                  lane.effectiveInFlight ?? Math.min(lane.processing, lane.detailCap);
                const overCap = lane.processing > lane.detailCap;
                return (
                  <tr key={lane.laneIndex}>
                    <td>L{lane.laneIndex}</td>
                    <td align="right">{lane.pending.toLocaleString('vi-VN')}</td>
                    <td
                      align="right"
                      style={overCap ? { color: '#b91c1c', fontWeight: 600 } : undefined}
                      title={
                        overCap
                          ? 'Checkpoint Processing > cap — thường do heal/batch cũ kẹt; slot thật = min(Processing, Cap)'
                          : undefined
                      }
                    >
                      {lane.processing.toLocaleString('vi-VN')}
                      {overCap ? ' ⚠' : ''}
                    </td>
                    <td align="right">{effective.toLocaleString('vi-VN')}</td>
                    <td align="right" title={`Cap / lane (batchSize×concurrent) ≈ ${perLaneCap}`}>
                      {lane.detailCap.toLocaleString('vi-VN')}
                    </td>
                    <td align="right">{lane.slotsAvailable.toLocaleString('vi-VN')}</td>
                  </tr>
                );
              })}
            </tbody>
          </table>
          <p className={styles.detailSummaryHeroHint} style={{ marginTop: 8 }}>
            <strong>Processing (raw)</strong> = mọi checkpoint status Processing.
            <strong> In-flight ước lượng</strong> = min(raw, Cap) — dùng cho slot.
            Cap / lane = detailBatchSize × concurrentDetailBatches.
          </p>
        </div>
      ) : null}

      <div className={styles.detailTableWrap} style={{ marginTop: 12 }}>
        <table className={styles.detailTable}>
          <thead>
            <tr>
              <th align="left">Phase</th>
              <th align="right">Hoàn tất</th>
              <th align="right">Đang chạy</th>
              <th align="right">Lỗi</th>
              <th align="right">Thời gian phase</th>
              <th align="right">TB / job</th>
              <th align="right">Max / job</th>
            </tr>
          </thead>
          <tbody>
            {(phaseRows.length > 0 ? phaseRows : orchestration.phaseTimings).map((p) => (
              <tr key={p.phaseKey}>
                <td>
                  <div style={{ fontWeight: 600 }}>{p.phaseLabel}</div>
                  <div className={styles.gridSub}>{p.eventType}</div>
                </td>
                <td align="right">{p.completedCount.toLocaleString('vi-VN')}</td>
                <td align="right">{p.activeCount > 0 ? p.activeCount.toLocaleString('vi-VN') : '—'}</td>
                <td align="right" style={{ color: p.failedCount > 0 ? '#b91c1c' : undefined }}>
                  {p.failedCount > 0 ? p.failedCount.toLocaleString('vi-VN') : '—'}
                </td>
                <td align="right">{formatDurationMs(p.totalDurationMs)}</td>
                <td align="right">{formatDurationMs(p.avgDurationMs)}</td>
                <td align="right">{formatDurationMs(p.maxDurationMs)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </JobDetailCollapsibleSection>
  );
};

export default ExternalSyncRunOrchestrationSection;
