import React, { useEffect, useState } from 'react';
import { useFormOptions, useNavTitle } from '@linm-soft-org/linm-web-common-components';
import { Button, SearchTextInput, TableCard } from '../../ui';
import { formatUTCToLocalDisplay } from '../../utils/dateTime';
import catalog from '../orgCatalog/orgCatalog.module.css';
import { listLoginHistory, listPlatformDevices, type PlatformLoginDevice, type UserLoginEvent } from './loginActivity';
import { LOGIN_ACTIVITY_LOOKUP, labelOf } from './lookupStatic';

const L = LOGIN_ACTIVITY_LOOKUP;

function accountCell(name: string, account: string): string {
  return name && account && name !== account ? `${name} · ${account}` : name || account || '—';
}

const LoginActivityPage: React.FC = () => {
  useNavTitle(labelOf(L, 'title', 'Đăng nhập nền tảng'));
  useFormOptions('admin-login-activity');
  const [search, setSearch] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [devices, setDevices] = useState<PlatformLoginDevice[]>([]);
  const [history, setHistory] = useState<UserLoginEvent[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const timer = window.setTimeout(() => {
      setLoading(true);
      void Promise.all([listPlatformDevices(appliedSearch), listLoginHistory(appliedSearch)])
        .then(([deviceRows, historyRows]) => {
          setDevices(deviceRows);
          setHistory(historyRows);
          setError('');
        })
        .catch(() => setError(labelOf(L, 'loadFail', 'Không tải được dữ liệu đăng nhập.')))
        .finally(() => setLoading(false));
    }, 0);
    return () => window.clearTimeout(timer);
  }, [appliedSearch]);

  const applySearch = () => setAppliedSearch(search.trim());

  return (
    <div className={catalog.page} data-testid="admin-login-activity">
      <div className={catalog.header}>
        <div>
          <h1 className={catalog.title}>{labelOf(L, 'title', 'Đăng nhập nền tảng')}</h1>
          <p className={catalog.hint}>{labelOf(L, 'hint', 'Thiết bị đang đăng nhập và lịch sử đăng nhập thành công. Tìm theo tài khoản, họ tên, mã nhân viên hoặc trình duyệt.')}</p>
        </div>
        <div className={catalog.headerActions}>
          <SearchTextInput
            value={search}
            onChange={setSearch}
            onSearch={applySearch}
            placeholder={labelOf(L, 'search', 'Tìm tài khoản, họ tên, mã nhân viên, trình duyệt')}
            testId="admin-login-search"
          />
          <Button variant="secondary" onClick={applySearch} disabled={loading}>
            {labelOf(L, 'refresh', 'Làm mới')}
          </Button>
        </div>
      </div>
      {error ? <p className={catalog.hint}>{error}</p> : null}

      <h2 className={catalog.title}>{labelOf(L, 'devices', 'Thiết bị đang đăng nhập')}</h2>
      {loading ? (
        <TableCard>
          <div className={catalog.emptyState}>{labelOf(L, 'loading', 'Đang tải…')}</div>
        </TableCard>
      ) : devices.length === 0 ? (
        <TableCard>
          <div className={catalog.emptyState}>{labelOf(L, 'devicesEmpty', 'Chưa có thiết bị đang đăng nhập.')}</div>
        </TableCard>
      ) : (
        <TableCard>
          <div className={catalog.tableWrapper}>
            <table className={catalog.table}>
              <thead>
                <tr>
                  <th>{labelOf(L, 'account', 'Tài khoản')}</th>
                  <th>{labelOf(L, 'employee', 'Mã nhân viên')}</th>
                  <th>{labelOf(L, 'device', 'Thiết bị')}</th>
                  <th>{labelOf(L, 'signedIn', 'Đăng nhập')}</th>
                  <th>{labelOf(L, 'lastSeen', 'Dùng gần nhất')}</th>
                  <th>{labelOf(L, 'ip', 'IP')}</th>
                </tr>
              </thead>
              <tbody>
                {devices.map((row) => (
                  <tr key={`${row.userId}-${row.deviceId}`}>
                    <td>{accountCell(row.fullName, row.accountName)}</td>
                    <td>{row.employeeId || '—'}</td>
                    <td>{row.label || labelOf(L, 'unknownDevice', 'Trình duyệt')}</td>
                    <td>{formatUTCToLocalDisplay(row.signedInAt)}</td>
                    <td>{formatUTCToLocalDisplay(row.lastSeenAt)}</td>
                    <td>{row.ipAddress || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </TableCard>
      )}

      <h2 className={catalog.title}>{labelOf(L, 'history', 'Lịch sử đăng nhập')}</h2>
      {loading ? (
        <TableCard>
          <div className={catalog.emptyState}>{labelOf(L, 'loading', 'Đang tải…')}</div>
        </TableCard>
      ) : history.length === 0 ? (
        <TableCard>
          <div className={catalog.emptyState}>{labelOf(L, 'historyEmpty', 'Chưa có lần đăng nhập.')}</div>
        </TableCard>
      ) : (
        <TableCard>
          <div className={catalog.tableWrapper}>
            <table className={catalog.table}>
              <thead>
                <tr>
                  <th>{labelOf(L, 'account', 'Tài khoản')}</th>
                  <th>{labelOf(L, 'employee', 'Mã nhân viên')}</th>
                  <th>{labelOf(L, 'device', 'Thiết bị')}</th>
                  <th>{labelOf(L, 'signedIn', 'Đăng nhập')}</th>
                  <th>{labelOf(L, 'ip', 'IP')}</th>
                </tr>
              </thead>
              <tbody>
                {history.map((row) => (
                  <tr key={row.id}>
                    <td>{accountCell(row.fullName, row.accountName)}</td>
                    <td>{row.employeeId || '—'}</td>
                    <td>{row.deviceLabel || labelOf(L, 'unknownDevice', 'Trình duyệt')}</td>
                    <td>{formatUTCToLocalDisplay(row.loggedInAt)}</td>
                    <td>{row.ipAddress || '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </TableCard>
      )}
    </div>
  );
};

export default LoginActivityPage;
