/**
 * Phòng ban — Medical WebService Departments (Kind B+D, modal).
 */
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useNavTitle, useAppToast } from '@linm-soft-org/linm-web-common-components';
import { Button, Input, Select, TableCard, Modal, Pagination } from '../../ui';
import { useActiveStatusOptions } from '../../hooks/useAdminFormOptions';
import { useOrgCatalogWritePermission } from '../../hooks/useOrgCatalogWritePermission';
import { departmentsService, type MedicalDepartment } from '../../services/medicalOrg';
import { isRmmsOrgCatalog } from '../../services/medicalOrg/rmmsOrgCatalog';
import type { OrgCatalogPageProps } from '../orgCatalog/orgCatalogPage.types';
import styles from '../orgCatalog/orgCatalog.module.css';

const PAGE_SIZE = 50;

type FormMode = 'create' | 'edit' | 'view';

interface DeptForm {
  code: string;
  name: string;
  description: string;
  sortOrder: string;
  isActive: boolean;
}

const emptyForm: DeptForm = { code: '', name: '', description: '', sortOrder: '0', isActive: true };

const DepartmentsManagementPage: React.FC<OrgCatalogPageProps> = ({
  navTitle = 'Phòng ban',
  pageTestId = 'admin-departments-page',
  createTestId = 'admin-departments-create',
  hint = isRmmsOrgCatalog()
    ? 'Danh mục đơn vị — RMMS OrgUnits'
    : 'Danh mục khoa/phòng — Medical WebService',
  writePermissionCode,
  writePermissionFallbacks,
  adminWritePermissionCode = 'admin:departments:write',
  devWriteBypass,
}) => {
  useNavTitle(navTitle);
  const toast = useAppToast();
  const canWrite = useOrgCatalogWritePermission({
    writePermissionCode,
    writePermissionFallbacks,
    adminWritePermissionCode,
    devWriteBypass,
  });
  const { getActiveLabel, options: statusOptions } = useActiveStatusOptions();

  const [items, setItems] = useState<MedicalDepartment[]>([]);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [search, setSearch] = useState('');
  const [appliedSearch, setAppliedSearch] = useState('');
  const [includeInactive, setIncludeInactive] = useState(true);
  const [loading, setLoading] = useState(true);

  const [formOpen, setFormOpen] = useState(false);
  const [formMode, setFormMode] = useState<FormMode>('create');
  const [editing, setEditing] = useState<MedicalDepartment | null>(null);
  const [form, setForm] = useState<DeptForm>(emptyForm);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [saving, setSaving] = useState(false);
  const cancelRef = useRef(false);

  const locked = formMode === 'view';

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const result = await departmentsService.list({
        includeInactive,
        search: appliedSearch,
        page,
        pageSize: PAGE_SIZE,
      });
      if (cancelRef.current) return;
      setItems(result.items ?? []);
      setTotal(Number(result.totalCount ?? 0));
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể tải danh sách phòng ban');
    } finally {
      if (!cancelRef.current) setLoading(false);
    }
  }, [appliedSearch, includeInactive, page, toast]);

  useEffect(() => {
    cancelRef.current = false;
    const t = setTimeout(() => { load(); }, 0);
    return () => {
      clearTimeout(t);
      cancelRef.current = true;
    };
  }, [load]);

  const openCreate = () => {
    setEditing(null);
    setForm(emptyForm);
    setFieldErrors({});
    setFormMode('create');
    setFormOpen(true);
  };

  const openEdit = (row: MedicalDepartment, mode: FormMode) => {
    setEditing(row);
    setForm({
      code: row.code ?? '',
      name: row.name,
      description: row.description ?? '',
      sortOrder: String(row.sortOrder ?? 0),
      isActive: row.isActive,
    });
    setFieldErrors({});
    setFormMode(mode);
    setFormOpen(true);
  };

  const closeForm = () => {
    if (saving) return;
    setFormOpen(false);
  };

  const validate = (): boolean => {
    const next: Record<string, string> = {};
    if (!form.name.trim()) next.name = 'Tên phòng ban là bắt buộc';
    const order = Number(form.sortOrder);
    if (!Number.isFinite(order) || order < 0) next.sortOrder = 'Thứ tự phải ≥ 0';
    setFieldErrors(next);
    return Object.keys(next).length === 0;
  };

  const handleSave = async () => {
    if (locked || !canWrite) return;
    if (!validate()) return;
    setSaving(true);
    try {
      const payload = {
        name: form.name.trim(),
        code: form.code.trim() ? form.code.trim().toUpperCase() : null,
        description: form.description.trim() || null,
        isActive: form.isActive,
        sortOrder: Number(form.sortOrder),
      };
      if (editing) await departmentsService.update(editing.id, { ...payload, kind: editing.kind });
      else await departmentsService.create(payload);
      toast.success(editing ? 'Đã cập nhật phòng ban' : 'Đã tạo phòng ban');
      setFormOpen(false);
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể lưu phòng ban');
    } finally {
      setSaving(false);
    }
  };

  const handleDeactivate = async (row: MedicalDepartment) => {
    if (!canWrite) return;
    try {
      await departmentsService.deactivate(row.id);
      toast.success('Đã ngừng hoạt động phòng ban');
      await load();
    } catch (err: unknown) {
      toast.fromError(err, 'Không thể ngừng hoạt động');
    }
  };

  const modalTitle =
    formMode === 'create' ? 'Thêm phòng ban' : formMode === 'edit' ? 'Chỉnh sửa phòng ban' : 'Xem phòng ban';

  return (
    <div className={styles.page} data-testid={pageTestId}>
      <div className={styles.header}>
        <div>
          <h1 className={styles.title}>
            <i className="fas fa-building" /> {navTitle}
          </h1>
          <p className={styles.hint}>{hint}</p>
        </div>
        <div className={styles.headerActions}>
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder="Tìm mã hoặc tên"
            onKeyDown={(e) => {
              if (e.key === 'Enter') {
                setPage(1);
                setAppliedSearch(search.trim());
              }
            }}
          />
          <Button
            variant="secondary"
            onClick={() => {
              setPage(1);
              setAppliedSearch(search.trim());
            }}
          >
            Tìm
          </Button>
          <Button variant={includeInactive ? 'secondary' : 'primary'} onClick={() => { setIncludeInactive((v) => !v); setPage(1); }}>
            {includeInactive ? 'Tất cả' : 'Đang hoạt động'}
          </Button>
          <Button variant="secondary" onClick={load}>
            <i className="fas fa-rotate" /> Làm mới
          </Button>
          {canWrite && (
            <Button variant="primary" onClick={openCreate} data-testid={createTestId}>
              <i className="fas fa-plus" /> Thêm
            </Button>
          )}
        </div>
      </div>

      <TableCard>
        {loading && <div className={styles.emptyState}>Đang tải dữ liệu...</div>}
        {!loading && items.length === 0 && (
          <div className={styles.emptyState}>
            <i className="fas fa-building" />
            <p>Chưa có phòng ban</p>
          </div>
        )}
        {!loading && items.length > 0 && (
          <div className={styles.tableWrapper}>
            <table className={styles.table}>
              <thead>
                <tr>
                  <th>STT</th>
                  <th>Mã</th>
                  <th>Tên</th>
                  <th>Mô tả</th>
                  <th>Thứ tự</th>
                  <th>Trạng thái</th>
                  <th className={styles.actionsCell}>Hành động</th>
                </tr>
              </thead>
              <tbody>
                {items.map((row, idx) => (
                  <tr key={row.id} className={styles.clickableRow} onClick={() => openEdit(row, 'view')}>
                    <td>{(page - 1) * PAGE_SIZE + idx + 1}</td>
                    <td>{row.code ? <span className={styles.codeBadge}>{row.code}</span> : <span className={styles.na}>—</span>}</td>
                    <td>{row.name}</td>
                    <td>{row.description || <span className={styles.na}>—</span>}</td>
                    <td>{row.sortOrder}</td>
                    <td>
                      <span className={`${styles.statusBadge} ${row.isActive ? styles.active : styles.inactive}`}>
                        {getActiveLabel(row.isActive)}
                      </span>
                    </td>
                    <td className={styles.actionsCell} onClick={(e) => e.stopPropagation()}>
                      <button className={styles.viewBtn} title="Xem" onClick={() => openEdit(row, 'view')}>
                        <i className="fas fa-eye" />
                      </button>
                      {canWrite && (
                        <button className={styles.editBtn} title="Sửa" onClick={() => openEdit(row, 'edit')}>
                          <i className="fas fa-pen" />
                        </button>
                      )}
                      {canWrite && row.isActive && (
                        <button className={styles.deleteBtn} title="Ngừng hoạt động" onClick={() => handleDeactivate(row)}>
                          <i className="fas fa-ban" />
                        </button>
                      )}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </TableCard>

      {total > PAGE_SIZE && (
        <div className={styles.pager}>
          <Pagination
            currentPage={page}
            totalPages={Math.max(1, Math.ceil(total / PAGE_SIZE))}
            totalCount={total}
            pageSize={PAGE_SIZE}
            onPageChange={setPage}
          />
        </div>
      )}

      <Modal isOpen={formOpen} onClose={closeForm} title={modalTitle} size="md" closeOnOverlayClick={!saving}>
        <div className={styles.formWrapper}>
          <div className={styles.formRow}>
            <Input
              label="Mã"
              value={form.code}
              onChange={(e) => setForm((f) => ({ ...f, code: e.target.value.toUpperCase() }))}
              error={fieldErrors.code}
              readOnly={locked}
              fullWidth
            />
            <Input
              label="Tên phòng ban"
              value={form.name}
              onChange={(e) => setForm((f) => ({ ...f, name: e.target.value }))}
              error={fieldErrors.name}
              required
              readOnly={locked}
              fullWidth
            />
          </div>
          <Input
            label="Mô tả"
            value={form.description}
            onChange={(e) => setForm((f) => ({ ...f, description: e.target.value }))}
            readOnly={locked}
            fullWidth
          />
          <div className={styles.formRow}>
            <Input
              label="Thứ tự"
              value={form.sortOrder}
              onChange={(e) => setForm((f) => ({ ...f, sortOrder: e.target.value }))}
              error={fieldErrors.sortOrder}
              readOnly={locked}
              fullWidth
            />
            <Select
              label="Trạng thái"
              value={form.isActive ? 'active' : 'inactive'}
              onChange={(e) => setForm((f) => ({ ...f, isActive: e.target.value === 'active' }))}
              options={
                statusOptions.length >= 2
                  ? statusOptions
                  : [
                      { value: 'active', label: 'Hoạt động' },
                      { value: 'inactive', label: 'Ngừng hoạt động' },
                    ]
              }
              disabled={locked}
              fullWidth
            />
          </div>
          {fieldErrors._general && <div className={styles.formError}>{fieldErrors._general}</div>}
        </div>
        <div className={styles.modalFooter}>
          <button className={styles.cancelBtn} onClick={closeForm} disabled={saving}>
            {locked ? 'Đóng' : 'Hủy'}
          </button>
          {!locked && canWrite && (
            <button className={styles.saveBtn} onClick={handleSave} disabled={saving}>
              {saving ? 'Đang lưu...' : 'Lưu'}
            </button>
          )}
        </div>
      </Modal>
    </div>
  );
};

export default DepartmentsManagementPage;
