import React from 'react';
import { createRoot } from 'react-dom/client';
import singleSpaReact from 'single-spa-react';
import { OrgCatalogParcelShell } from '../components/OrgCatalogParcelShell';
import DepartmentsManagementPage from '../pages/DepartmentsManagementPage';
import type { OrgCatalogPageProps } from '../pages/orgCatalog/orgCatalogPage.types';

const DepartmentsManagementWithShell: React.FC<OrgCatalogPageProps> = (props) => (
  <OrgCatalogParcelShell>
    <DepartmentsManagementPage {...props} />
  </OrgCatalogParcelShell>
);

export type DepartmentsManagementParcelProps = OrgCatalogPageProps;

export const DepartmentsManagementParcel = singleSpaReact({
  React,
  ReactDOMClient: { createRoot },
  rootComponent: DepartmentsManagementWithShell,
  renderType: 'createRoot',
  errorBoundary(error) {
    throw error;
  },
});
