import React, { useCallback, useEffect, useRef, useState } from 'react';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import { Pagination } from '../../../ui';
import { jobsService, type DataSyncRunDetail, type ExternalSyncVoucherSample } from '../../../services/jobs';
import { JobDetailCollapsibleSection } from './JobDetailMetaGrid';
import { displayExternalVoucherImportOutcome, displayVoucherSampleStatus } from '../jobStatusDisplay';
import {
  isExternalSyncVoucherLinkable,
  labelExternalSyncVoucherType,
} from '../externalSyncVoucherViewPath';
import { openConvertedExternalSyncVoucher } from '../externalSyncVoucherNavigate';
import styles from '../JobInternalPage.module.css';

const PAGE_SIZE = 20;
const SEARCH_DEBOUNCE_MS = 400;

/** Map voucher sample status → pipeline badge color. */
function sampleStatusBadgeColor(status: string): string {
  switch (status) {
    case 'Created':
    case 'PendingRenumber': return '#d97706';
    case 'Renumbered': return '#2563eb';
    case 'Posted': return '#16a34a';
    case 'Failed': return '#dc2626';
    default: return '#6b7280';
  }
}

/** Map voucher sample status → pipeline badge bg. */
function sampleStatusBadgeBg(status: string): string {
  switch (status) {
    case 'Created':
    case 'PendingRenumber': return '#fffbeb';
    case 'Renumbered': return '#eff6ff';
    case 'Posted': return '#f0fdf4';
    case 'Failed': return '#fef2f2';
    default: return '#f8fafc';
  }
}

/** Pipeline-style status pill. */
function PipelineStatusPill({ status }: { status: string }) {
  const label = displayVoucherSampleStatus(status);
  const color = sampleStatusBadgeColor(status);
  const bg = sampleStatusBadgeBg(status);
  const borderColor = `${color}33`;
  return (
    <span
      style={{
        display: 'inline-block',
        padding: '1px 6px',
        borderRadius: 4,
        fontSize: 11,
        fontWeight: 600,
        color,
        background: bg,
        border: `1px solid ${borderColor}`,
        whiteSpace: 'nowrap',
      }}
    >
      {label}
    </span>
  );
}

/** Aggregated status summary string, e.g. "Đã ghi sổ: 2/3". */
function childStatusSummary(children: ExternalSyncVoucherSample[]): {
  label: string;
  done: number;
  total: number;
} {
  const total = children.length;
  const done = children.filter((c) => c.status === 'Posted').length;
  const failed = children.filter((c) => c.status === 'Failed').length;
  if (done === total) return { label: `Đã ghi sổ: ${done}/${total}`, done, total };
  if (failed > 0) return { label: `Lỗi: ${failed}/${total}`, done: done + failed, total };
  if (done > 0) return { label: `Đã ghi sổ: ${done}/${total}`, done, total };
  return { label: `Chờ xử lý: ${total}`, done: 0, total };
}

export type ExternalSyncVoucherSamplesSectionProps = {
  runDetail: DataSyncRunDetail;
};

export const ExternalSyncVoucherSamplesSection: React.FC<ExternalSyncVoucherSamplesSectionProps> = ({
  runDetail,
}) => {
  const toast = useAppToast();
  const totalHint =
    (runDetail.checkpointSummary?.total ?? 0) > 0
      ? runDetail.checkpointSummary.done
      : (runDetail.voucherSampleCount ??
        runDetail.conversionSummary?.documentsConverted ??
        runDetail.voucherSamples?.length ??
        0);

  const [page, setPage] = useState(1);
  const [items, setItems] = useState<ExternalSyncVoucherSample[]>([]);
  const [total, setTotal] = useState(0);
  const [filterLoading, setFilterLoading] = useState(false);
  const [pageLoading, setPageLoading] = useState(false);
  const [search, setSearch] = useState('');
  const [expandedRow, setExpandedRow] = useState<string | null>(null);
  const [openingVoucherKey, setOpeningVoucherKey] = useState<string | null>(null);
  const [refreshingStatus, setRefreshingStatus] = useState(false);
  const searchTimer = useRef<ReturnType<typeof setTimeout>>();

  const loadPage = useCallback(
    async (targetPage: number, searchTerm: string, mode: 'filter' | 'page') => {
      if (mode === 'filter') setFilterLoading(true);
      else setPageLoading(true);
      try {
        const result = await jobsService.getExternalVoucherSamples(
          runDetail.id,
          targetPage,
          PAGE_SIZE,
          searchTerm || undefined,
        );
        setItems(result.items);
        setTotal(result.total);
        setPage(targetPage);
        setExpandedRow(null);
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Không tải được danh sách chứng từ.';
        toast.error(message);
      } finally {
        if (mode === 'filter') setFilterLoading(false);
        else setPageLoading(false);
      }
    },
    [runDetail.id, toast],
  );

  useEffect(() => {
    if (totalHint <= 0) {
      setItems([]);
      setTotal(0);
      return;
    }
    void loadPage(1, '', 'filter');
  }, [runDetail.id, totalHint, loadPage]);

  const handleSearchChange = useCallback(
    (value: string) => {
      setSearch(value);
      if (searchTimer.current) clearTimeout(searchTimer.current);
      if (totalHint <= 0) return;
      searchTimer.current = setTimeout(() => {
        void loadPage(1, value.trim(), 'filter');
      }, SEARCH_DEBOUNCE_MS);
    },
    [totalHint, loadPage],
  );

  const handlePageChange = useCallback(
    (nextPage: number) => {
      void loadPage(nextPage, search.trim(), 'page');
    },
    [search, loadPage],
  );

  const openConvertedVoucher = useCallback(
    async (sample: ExternalSyncVoucherSample) => {
      const code = sample.voucherCode?.trim();
      if (!code || !isExternalSyncVoucherLinkable(sample.setName, code)) return;

      const rowKey = `${sample.setName}-${sample.externalId}-${code}`;
      setOpeningVoucherKey(rowKey);
      try {
        await openConvertedExternalSyncVoucher(runDetail, sample);
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Không mở được chứng từ ERP.';
        toast.error(message);
      } finally {
        setOpeningVoucherKey(null);
      }
    },
    [runDetail, toast],
  );

  const toggleExpand = useCallback((rowKey: string) => {
    setExpandedRow((prev) => (prev === rowKey ? null : rowKey));
  }, []);

  const handleRefreshStatus = useCallback(async () => {
    setRefreshingStatus(true);
    try {
      const updated = await jobsService.refreshVoucherSampleStatus(runDetail.id);
      toast.success(`Đã cập nhật trạng thái cho ${updated} chứng từ từ ERP.`);
      // Reload current page after refresh
      await loadPage(page, search.trim(), 'filter');
    } catch (err) {
      const message = err instanceof Error ? err.message : 'Kiểm tra từ ERP thất bại.';
      toast.error(message);
    } finally {
      setRefreshingStatus(false);
    }
  }, [runDetail.id, page, search, toast, loadPage]);

  if (totalHint <= 0 && total <= 0 && !filterLoading) return null;

  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
  const sttBase = (page - 1) * PAGE_SIZE;
  const showTableLoading = filterLoading;

  return (
    <JobDetailCollapsibleSection title={`Mã chứng từ đã convert (${total.toLocaleString('vi-VN')})`}>
      {totalHint > 0 ? (
        <div style={{ marginBottom: 8, display: 'flex', gap: 8, alignItems: 'center' }}>
          <input
            type="text"
            placeholder="Tìm mã POS, mã CT ERP, trạng thái…"
            value={search}
            onChange={(e) => handleSearchChange(e.target.value)}
            style={{
              flex: 1,
              maxWidth: 360,
              padding: '6px 10px',
              fontSize: 13,
              border: '1px solid #d1d5db',
              borderRadius: 4,
              outline: 'none',
            }}
            onFocus={(e) => { e.target.style.borderColor = '#3b82f6'; }}
            onBlur={(e) => { e.target.style.borderColor = '#d1d5db'; }}
          />
          {filterLoading ? <span style={{ fontSize: 12, color: '#64748b' }}>Đang tìm…</span> : null}
          <button
            type="button"
            disabled={refreshingStatus}
            onClick={() => void handleRefreshStatus()}
            style={{
              padding: '6px 12px',
              fontSize: 13,
              border: '1px solid #3b82f6',
              borderRadius: 4,
              background: refreshingStatus ? '#eff6ff' : '#3b82f6',
              color: refreshingStatus ? '#3b82f6' : '#fff',
              cursor: refreshingStatus ? 'wait' : 'pointer',
              whiteSpace: 'nowrap',
              fontWeight: 500,
              marginLeft: 'auto',
            }}
          >
            {refreshingStatus ? 'Đang kiểm tra…' : 'Kiểm tra từ ERP'}
          </button>
        </div>
      ) : null}

      <div className={pageLoading ? styles.gridBusy : undefined} aria-busy={pageLoading || undefined}>
        <div className={styles.detailTableWrap}>
          {showTableLoading ? (
            <p className={styles.gridLoading}>Đang tải…</p>
          ) : items.length === 0 ? (
            <p className={styles.gridEmpty}>Chưa có mẫu chứng từ đã lưu cho run này.</p>
          ) : (
            <table className={styles.detailTable}>
              <thead>
                <tr>
                  <th align="right">STT</th>
                  <th>Loại</th>
                  <th>Mã POS</th>
                  <th>Mã CT ERP</th>
                  <th>Trạng thái pipeline</th>
                  <th>Kết quả</th>
                  <th>Lỗi</th>
                  <th>Chứng từ liên quan</th>
                  <th></th>
                </tr>
              </thead>
              <tbody>
                {items.map((v, idx) => {
                  const code = v.voucherCode?.trim() ?? '';
                  const linkable = code.length > 0 && isExternalSyncVoucherLinkable(v.setName, code);
                  const rowKey = `${v.setName}-${v.externalId}-${code || idx}`;
                  const opening = openingVoucherKey === rowKey;
                  const expanded = expandedRow === rowKey;

                  const children = v.childSamples ?? [];
                  const summary = children.length > 0 ? childStatusSummary(children) : null;

                  return (
                    <React.Fragment key={rowKey}>
                      {/* ── Parent row ─────────────────────────────── */}
                      <tr>
                        <td align="right">{sttBase + idx + 1}</td>
                        <td>{labelExternalSyncVoucherType(v.setName, code)}</td>
                        <td className={styles.gridMono}>{v.externalId}</td>
                        <td className={styles.gridMono}>
                          {linkable ? (
                            <button
                              type="button"
                              className={styles.linkButton}
                              title="Mở chứng từ ERP (tab mới)"
                              disabled={opening}
                              onClick={() => void openConvertedVoucher(v)}
                            >
                              {opening ? 'Đang mở…' : code}
                            </button>
                          ) : (
                            v.voucherCode ?? '—'
                          )}
                        </td>
                        <td>
                          <PipelineStatusPill status={v.status} />
                        </td>
                        <td>
                          {v.isNewInsert === false ? (
                            <span style={{ color: '#d97706', fontWeight: 600, fontSize: 12 }}>
                              {displayExternalVoucherImportOutcome(v.isNewInsert)}
                              {linkable ? (
                                <>
                                  {' · '}
                                  <button
                                    type="button"
                                    className={styles.linkButton}
                                    title="Mở phiếu ERP đã tồn tại (skip trùng)"
                                    disabled={opening}
                                    onClick={() => void openConvertedVoucher(v)}
                                  >
                                    {opening ? 'Đang mở…' : 'Xem phiếu trùng'}
                                  </button>
                                </>
                              ) : null}
                            </span>
                          ) : (
                            displayExternalVoucherImportOutcome(v.isNewInsert)
                          )}
                        </td>
                        <td>
                          {v.status === 'Failed' && v.errorMessage ? (
                            <span title={v.errorMessage} style={{ cursor: 'help', color: '#dc2626', fontSize: 12 }}>
                              {v.errorMessage.length > 60
                                ? `${v.errorMessage.slice(0, 60)}…`
                                : v.errorMessage}
                            </span>
                          ) : (
                            <span style={{ color: '#94a3b8', fontSize: 12 }}>—</span>
                          )}
                        </td>
                        <td>
                          {children.length > 0 ? (
                            <>
                              <button
                                type="button"
                                onClick={() => toggleExpand(rowKey)}
                                style={{
                                  background: 'none',
                                  border: '1px solid #d1d5db',
                                  borderRadius: 4,
                                  padding: '2px 8px',
                                  fontSize: 11,
                                  cursor: 'pointer',
                                  color: '#2563eb',
                                  whiteSpace: 'nowrap',
                                }}
                              >
                                {expanded ? '▲ Thu gọn' : `▼ ${children.length} phiếu`}
                              </button>
                              {summary && (
                                <span style={{
                                  marginLeft: 6,
                                  fontSize: 11,
                                  color: summary.done === summary.total ? '#16a34a' : '#d97706',
                                }}>
                                  {summary.label}
                                </span>
                              )}
                            </>
                          ) : (
                            <span style={{ fontSize: 11, color: '#94a3b8' }}>—</span>
                          )}
                        </td>
                        <td>
                          {/* Empty cell for alignment with expand toggle column */}
                        </td>
                      </tr>

                      {/* ── Expanded children rows ────────────────── */}
                      {expanded && children.length > 0 && (
                        <tr>
                          <td colSpan={9} style={{ padding: 0 }}>
                            <div style={{
                              background: '#f1f5f9',
                              padding: '8px 12px 8px 48px',
                              fontSize: 12,
                              borderBottom: '1px solid #e2e8f0',
                            }}>
                              <div style={{ fontWeight: 600, marginBottom: 4, color: '#334155' }}>
                                Phiếu liên quan ({children.length}):
                              </div>
                              <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                                <thead>
                                  <tr style={{ color: '#64748b' }}>
                                    <th align="left" style={{ padding: '2px 8px' }}>Loại</th>
                                    <th align="left" style={{ padding: '2px 8px' }}>Mã POS</th>
                                    <th align="left" style={{ padding: '2px 8px' }}>Mã CT ERP</th>
                                    <th align="left" style={{ padding: '2px 8px' }}>Trạng thái</th>
                                    <th align="left" style={{ padding: '2px 8px' }}>Lỗi</th>
                                    <th align="left" style={{ padding: '2px 8px' }}></th>
                                  </tr>
                                </thead>
                                <tbody>
                                  {children.map((child, ci) => {
                                    const childCode = child.voucherCode?.trim() ?? '';
                                    const childLinkable = childCode.length > 0 && isExternalSyncVoucherLinkable(child.setName, childCode);
                                    const childKey = `${child.setName}-${child.externalId}-${childCode || ci}`;
                                    const childOpening = openingVoucherKey === childKey;

                                    return (
                                      <tr key={ci} style={{ borderTop: '1px solid #e2e8f0' }}>
                                        <td style={{ padding: '2px 8px' }}>
                                          {labelExternalSyncVoucherType(child.setName, childCode)}
                                        </td>
                                        <td style={{ padding: '2px 8px', fontFamily: 'monospace' }}>
                                          {child.externalId}
                                        </td>
                                        <td style={{ padding: '2px 8px', fontFamily: 'monospace' }}>
                                          {childLinkable ? (
                                            <button
                                              type="button"
                                              onClick={() => {
                                                if (!childOpening) void openConvertedVoucher(child);
                                              }}
                                              style={{
                                                background: 'none',
                                                border: 'none',
                                                padding: 0,
                                                color: '#2563eb',
                                                cursor: 'pointer',
                                                fontSize: 12,
                                                fontFamily: 'monospace',
                                                textDecoration: 'underline',
                                              }}
                                              disabled={childOpening}
                                            >
                                              {childOpening ? 'Đang mở…' : childCode}
                                            </button>
                                          ) : (
                                            child.voucherCode ?? '—'
                                          )}
                                        </td>
                                        <td style={{ padding: '2px 8px' }}>
                                          <PipelineStatusPill status={child.status} />
                                        </td>
                                        <td style={{ padding: '2px 8px' }}>
                                          {child.status === 'Failed' && child.errorMessage ? (
                                            <span
                                              title={child.errorMessage}
                                              style={{ cursor: 'help', color: '#dc2626', fontSize: 11 }}
                                            >
                                              {child.errorMessage.length > 50
                                                ? `${child.errorMessage.slice(0, 50)}…`
                                                : child.errorMessage}
                                            </span>
                                          ) : (
                                            <span style={{ color: '#94a3b8' }}>—</span>
                                          )}
                                        </td>
                                        <td style={{ padding: '2px 8px' }}>
                                          {childLinkable ? (
                                            <button
                                              type="button"
                                              onClick={() => {
                                                if (!childOpening) void openConvertedVoucher(child);
                                              }}
                                              style={{
                                                background: 'none',
                                                border: '1px solid #d1d5db',
                                                borderRadius: 4,
                                                padding: '1px 6px',
                                                fontSize: 10,
                                                cursor: 'pointer',
                                                color: '#2563eb',
                                              }}
                                              disabled={childOpening}
                                            >
                                              {childOpening ? '…' : 'Mở'}
                                            </button>
                                          ) : null}
                                        </td>
                                      </tr>
                                    );
                                  })}
                                </tbody>
                              </table>
                            </div>
                          </td>
                        </tr>
                      )}
                    </React.Fragment>
                  );
                })}
              </tbody>
            </table>
          )}
        </div>
      </div>
      {!showTableLoading && total > 0 ? (
        <div style={{ marginTop: 12 }}>
          <Pagination
            currentPage={page}
            totalPages={totalPages}
            totalCount={total}
            pageSize={PAGE_SIZE}
            itemLabel="chứng từ"
            onPageChange={handlePageChange}
          />
        </div>
      ) : null}
    </JobDetailCollapsibleSection>
  );
};
