import React from 'react';
import { InAppLink } from '../../router/InAppLink';
import {
  evaluateParallelismQueueWarning,
  type ParallelismQueueWarningInput,
} from './jobParallelismQueueWarning';

export type JobParallelismQueueWarningBannerProps = Omit<
  ParallelismQueueWarningInput,
  'lowWorkerPickCapacity'
> & {
  lowWorkerPickCapacity: number | null | undefined;
  loadingWorkers?: boolean;
  testId?: string;
};

const boxStyle = (level: 'warn' | 'danger'): React.CSSProperties => ({
  marginTop: 8,
  padding: '10px 12px',
  borderRadius: 8,
  fontSize: 13,
  lineHeight: 1.45,
  border: `1px solid ${level === 'danger' ? '#fca5a5' : '#fcd34d'}`,
  background: level === 'danger' ? '#fef2f2' : '#fffbeb',
  color: level === 'danger' ? '#991b1b' : '#92400e',
});

export const JobParallelismQueueWarningBanner: React.FC<JobParallelismQueueWarningBannerProps> = ({
  configuredCap,
  detailBatchSize,
  lowWorkerPickCapacity,
  loadingWorkers,
  concurrentRuns,
  context,
  testId = 'job-parallelism-queue-warning',
}) => {
  if (loadingWorkers) {
    return (
      <p style={{ margin: '8px 0 0', fontSize: 12, color: '#64748b' }} data-testid={testId}>
        Đang đọc cấu hình worker Low…
      </p>
    );
  }

  if (lowWorkerPickCapacity == null) {
    return (
      <p style={{ margin: '8px 0 0', fontSize: 12, color: '#b45309' }} data-testid={testId}>
        Không đọc được <strong>LowWorkerInstanceCount</strong> — kiểm tra thủ công trên{' '}
        <InAppLink to="/admin/jobs/server-config">Cấu hình worker</InAppLink> trước khi tăng leader /
        batch event song song.
      </p>
    );
  }

  const warning = evaluateParallelismQueueWarning({
    configuredCap,
    detailBatchSize,
    lowWorkerPickCapacity,
    concurrentRuns,
    context,
  });

  if (!warning || warning.level === 'ok') {
    return null;
  }

  return (
    <div style={boxStyle(warning.level)} data-testid={testId} role="alert">
      <strong>{warning.title}</strong>
      <div style={{ marginTop: 4 }}>{warning.detail}</div>
    </div>
  );
};

export default JobParallelismQueueWarningBanner;
