import React from 'react';
import { useAppToast } from '@linm-soft-org/linm-web-common-components';
import { Button } from '../../../ui';
import { jobsService } from '../../../services/jobs';

const QUEUE_BATCH = 5_000;
const FAILED_BATCH = 10_000;

export type JobRequeueFailedScope = {
  eventType?: string;
  direction?: string;
  fromUtc?: string;
  toUtc?: string;
};

export type JobRequeueFailedButtonProps = JobRequeueFailedScope & {
  failedCount: number;
  disabled?: boolean;
  onDone: () => void;
};

export const JobRequeueFailedButton: React.FC<JobRequeueFailedButtonProps> = ({
  eventType,
  direction,
  fromUtc,
  toUtc,
  failedCount,
  disabled,
  onDone,
}) => {
  const toast = useAppToast();
  const [requeuing, setRequeuing] = React.useState(false);
  const scopeLabel = eventType || (direction ? `hướng ${direction}` : 'mọi loại');

  const handleRequeueFailed = () => {
    if (failedCount <= 0) {
      toast.error('Không có event Lỗi để requeue.');
      return;
    }
    if (
      !window.confirm(
        `Đưa tối đa ${Math.min(failedCount, FAILED_BATCH).toLocaleString('vi-VN')} event Lỗi (Failed/DeadLetter) vào hàng đợi lại — ${scopeLabel}? Attempt reset về 0.`,
      )
    ) {
      return;
    }
    setRequeuing(true);
    jobsService
      .requeueFailedEvents({
        eventType: eventType || undefined,
        direction: direction || undefined,
        fromUtc,
        toUtc,
        resetAttempts: true,
        maxCount: FAILED_BATCH,
      })
      .then((r) => {
        toast.success(`Đã requeue ${r.requeuedCount.toLocaleString('vi-VN')} event Lỗi`);
        onDone();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setRequeuing(false));
  };

  return (
    <Button
      type="button"
      variant="primary"
      disabled={disabled || requeuing || failedCount <= 0}
      onClick={handleRequeueFailed}
      data-testid="requeue-failed-btn"
    >
      {requeuing
        ? 'Đang requeue…'
        : `Requeue tất cả lỗi${failedCount > 0 ? ` (${failedCount.toLocaleString('vi-VN')})` : ''}`}
    </Button>
  );
};

export type JobEventQueueActionsProps = JobRequeueFailedScope & {
  queuedTotal?: number;
  /** Số Lỗi từ list (jobStatus=Failed) — hiện nút ngay, không chờ preview API. */
  failedHint?: number;
  onDone: () => void;
};

export const JobEventQueueActions: React.FC<JobEventQueueActionsProps> = ({
  eventType,
  direction,
  fromUtc,
  toUtc,
  queuedTotal = 0,
  failedHint = 0,
  onDone,
}) => {
  const toast = useAppToast();
  const [previewCount, setPreviewCount] = React.useState<number | null>(null);
  const [failedCount, setFailedCount] = React.useState<number | null>(null);
  const [loadingPreview, setLoadingPreview] = React.useState(false);
  const [cancelling, setCancelling] = React.useState(false);
  const [reprioritizing, setReprioritizing] = React.useState(false);

  const busy = cancelling || reprioritizing;
  const scopeLabel = eventType || (direction ? `hướng ${direction}` : 'mọi loại');
  const failedTotal = failedCount ?? failedHint;

  React.useEffect(() => {
    let cancelled = false;
    setLoadingPreview(true);
    Promise.allSettled([
      queuedTotal > 0
        ? jobsService.getCancelQueuedPreview(eventType || undefined)
        : Promise.resolve({ eligibleCount: 0 }),
      jobsService.getRequeueFailedPreview({
        eventType: eventType || undefined,
        direction: direction || undefined,
        fromUtc,
        toUtc,
      }),
    ])
      .then(([queued, failed]) => {
        if (cancelled) return;
        setPreviewCount(
          queued.status === 'fulfilled' ? queued.value.eligibleCount : queuedTotal,
        );
        setFailedCount(failed.status === 'fulfilled' ? failed.value.eligibleCount : null);
      })
      .finally(() => {
        if (!cancelled) setLoadingPreview(false);
      });
    return () => {
      cancelled = true;
    };
  }, [eventType, direction, fromUtc, toUtc, queuedTotal]);

  const handleCancelQueued = () => {
    const count = previewCount ?? queuedTotal;
    if (!window.confirm(`Hủy tối đa ${QUEUE_BATCH.toLocaleString('vi-VN')} event Queued (${scopeLabel})? Hiện có ~${count.toLocaleString('vi-VN')} event.`)) {
      return;
    }
    setCancelling(true);
    jobsService
      .cancelQueuedEvents({ eventType: eventType || undefined, maxCount: QUEUE_BATCH })
      .then((r) => {
        toast.success(`Đã hủy ${r.cancelledCount.toLocaleString('vi-VN')} event Queued`);
        onDone();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setCancelling(false));
  };

  const handleReprioritize = () => {
    if (!window.confirm(`Đẩy ưu tiên (priority -10) tối đa ${QUEUE_BATCH.toLocaleString('vi-VN')} event Queued — ${scopeLabel}?`)) {
      return;
    }
    setReprioritizing(true);
    jobsService
      .reprioritizeQueuedEvents({ eventType: eventType || undefined, priority: -10, maxCount: QUEUE_BATCH })
      .then((r) => {
        toast.success(`Đã cập nhật ưu tiên ${r.updatedCount.toLocaleString('vi-VN')} event`);
        onDone();
      })
      .catch((e: Error) => toast.error(e.message))
      .finally(() => setReprioritizing(false));
  };

  return (
    <div
      style={{
        marginBottom: 16,
        padding: '10px 14px',
        background: '#fff7ed',
        border: '1px solid #fed7aa',
        borderRadius: 8,
        fontSize: 13,
        display: 'flex',
        flexWrap: 'wrap',
        gap: 10,
        alignItems: 'center',
      }}
      data-testid="job-event-queue-actions"
    >
      <span style={{ color: '#9a3412' }}>
        Vận hành hàng đợi
        {eventType ? (
          <>
            {' '}
            — <code>{eventType}</code>
          </>
        ) : direction ? (
          <>
            {' '}
            — {direction}
          </>
        ) : null}
        {loadingPreview
          ? '…'
          : ` (${(previewCount ?? queuedTotal).toLocaleString('vi-VN')} Queued · ${failedTotal.toLocaleString('vi-VN')} Lỗi)`}
      </span>
      <Button
        type="button"
        variant="secondary"
        disabled={busy || queuedTotal <= 0}
        onClick={handleReprioritize}
        data-testid="reprioritize-queued-btn"
      >
        {reprioritizing ? 'Đang đẩy…' : 'Đẩy ưu tiên'}
      </Button>
      <Button
        type="button"
        variant="secondary"
        disabled={busy || queuedTotal <= 0}
        onClick={handleCancelQueued}
        data-testid="cancel-queued-btn"
      >
        {cancelling ? 'Đang hủy…' : 'Hủy Queued'}
      </Button>
      <JobRequeueFailedButton
        eventType={eventType}
        direction={direction}
        fromUtc={fromUtc}
        toUtc={toUtc}
        failedCount={failedTotal}
        disabled={busy}
        onDone={onDone}
      />
    </div>
  );
};
