import { BffResponse, unwrap } from '@linm-soft-org/linm-web-common-components';
import { apiClient } from '../api';
import type { GoLiveCleanupExecuteResultDto, GoLiveCleanupPreviewDto } from './responseModel';

export interface GoLiveCleanupPeriod {
  dateFrom?: string;
  dateTo?: string;
}

export const goLiveCleanupEndpoint = {
  preview: async (period?: GoLiveCleanupPeriod): Promise<GoLiveCleanupPreviewDto> => {
    const params = new URLSearchParams();
    if (period?.dateFrom) params.set('dateFrom', period.dateFrom);
    if (period?.dateTo) params.set('dateTo', period.dateTo);
    const qs = params.toString();
    const res = await apiClient.get<BffResponse<GoLiveCleanupPreviewDto>>(
      `/integration/go-live-cleanup/preview${qs ? `?${qs}` : ''}`,
    );
    return unwrap(res);
  },

  execute: async (body: {
    confirmPhrase: string;
    cardKey: string;
    itemKeys: string[];
    dateFrom?: string;
    dateTo?: string;
  }): Promise<GoLiveCleanupExecuteResultDto> => {
    const res = await apiClient.post<BffResponse<GoLiveCleanupExecuteResultDto>>(
      '/integration/go-live-cleanup/execute',
      body,
    );
    return unwrap(res);
  },
};
