import React, { useMemo } from 'react';
import { InAppLink } from '../../router/InAppLink';
import { useAdminPermissions } from '../../hooks/useAdminPermissions';
import type { AdminNavItem } from '../../config/adminPages';
import {
  AdminPerm,
  hasAdminPagePermission,
  hasAnyJobsPagePermission,
} from '../../config/adminPermissions';

export function filterAdminNavByPermission<T extends Pick<AdminNavItem, 'permissionCode'>>(
  items: readonly T[],
  hasPermission: (code: string) => boolean,
): T[] {
  return items.filter((item) => {
    if (item.permissionCode === AdminPerm.jobsHub) {
      return hasAnyJobsPagePermission(hasPermission);
    }
    return hasAdminPagePermission(hasPermission, item.permissionCode);
  });
}

/** @deprecated use filterAdminNavByPermission */
export function filterAdminNavByAccess<T extends Pick<AdminNavItem, 'permissionCode'>>(
  items: readonly T[],
  _hasMenuAccess: (path: string) => boolean,
  hasPermission?: (code: string) => boolean,
): T[] {
  if (!hasPermission) return [...items];
  return filterAdminNavByPermission(items, hasPermission);
}

export interface AdminPermNavLinkItem {
  to: string;
  label: string;
  /** Page permission code (read) — required for accurate display */
  permissionCode: string;
}

interface AdminPermNavLinksProps {
  items: readonly AdminPermNavLinkItem[];
  className?: string;
  style?: React.CSSProperties;
  separator?: string;
  'data-testid'?: string;
}

/**
 * Cross-page job/admin links — only render items the user may open
 * (Auth permissionCodes, not menu paths).
 */
export const AdminPermNavLinks: React.FC<AdminPermNavLinksProps> = ({
  items,
  className,
  style,
  separator = ' · ',
  'data-testid': testId,
}) => {
  const { hasPermission, loading } = useAdminPermissions();

  const visible = useMemo(
    () =>
      items.filter((item) => {
        if (item.permissionCode === AdminPerm.jobsHub) {
          return hasAnyJobsPagePermission(hasPermission);
        }
        return hasAdminPagePermission(hasPermission, item.permissionCode);
      }),
    [items, hasPermission],
  );

  if (loading || visible.length === 0) return null;

  return (
    <p className={className} style={style} data-testid={testId}>
      {visible.map((item, i) => (
        <React.Fragment key={`${item.to}-${item.label}`}>
          {i > 0 ? separator : null}
          <InAppLink to={item.to}>{item.label}</InAppLink>
        </React.Fragment>
      ))}
    </p>
  );
};
