/** Kết quả POST hard-delete POS-deleted — type local (tránh import() namespace bị fork-ts-checker cắt). */
export type ConfirmHardDeletePosDeletedResult = {
  reconcileRunId: string;
  mastersProcessed: number;
  detailsHardDeleted: number;
  detailsNotFound: number;
  detailsFailed: number;
  invoicesRemoved: number;
  cashVouchersRemoved: number;
  connectorKeys: string[];
};

export async function confirmPosVoucherDetailHardDeletePosDeleted(
  runId: string,
  body?: {
    masterIds?: string[] | null;
    connectorKey?: string | null;
    documentKeys?: string[] | null;
  },
): Promise<ConfirmHardDeletePosDeletedResult> {
  const res = await apiClient.post<BffResponse<ConfirmHardDeletePosDeletedResult>>(
    `/pos/sync/voucher-detail-reconcile/${encodeURIComponent(runId)}/hard-delete-pos-deleted`,
    body ?? {},
  );
  return unwrap(res);
}

function normalizeTenantCompanyCode<T extends { companyCode?: string | null }>(raw: T): T {
  const companyCode = String(raw.companyCode ?? '').trim() || undefined;
  return { ...raw, companyCode };
}

const qs = (params: Record<string, string | number | undefined>) => {
  const sp = new URLSearchParams();
  Object.entries(params).forEach(([k, v]) => {
    if (v !== undefined && v !== '') sp.set(k, String(v));
  });
  const s = sp.toString();
  return s ? `?${s}` : '';
};

