import { apiClient, unwrap, type BffResponse } from '@linm-soft-org/linm-web-common-components';
import type { VoucherRegistryDto } from './voucherRegistryModels';

const BASE = '/system';

export const voucherRegistryEndpoint = {
  getList: async (): Promise<VoucherRegistryDto[]> => {
    const res = await apiClient.get<BffResponse<VoucherRegistryDto[]>>(`${BASE}/voucher-registry`);
    return unwrap(res) ?? [];
  },
};
