import React from 'react';
import { useNavigate } from 'react-router-dom';
import { navigateInAppPath } from './navigateInAppPath';
import styles from './InAppLink.module.css';

export type InAppLinkProps = {
  to: string;
  children: React.ReactNode;
  className?: string;
  style?: React.CSSProperties;
  replace?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  title?: string;
  'data-testid'?: string;
};

/** Shell-safe in-app link — updates URL bar via `navigateInAppPath`. */
export const InAppLink: React.FC<InAppLinkProps> = ({
  to,
  children,
  className,
  style,
  replace,
  onClick,
  title,
  'data-testid': dataTestId,
}) => {
  const navigate = useNavigate();
  const composedClassName = className ? `${styles.root} ${className}` : styles.root;

  return (
    <button
      type="button"
      role="link"
      className={composedClassName}
      style={style}
      title={title}
      data-testid={dataTestId}
      onClick={(e) => {
        onClick?.(e);
        if (e.defaultPrevented) return;
        navigateInAppPath(to, navigate, { replace });
      }}
    >
      {children}
    </button>
  );
};

export default InAppLink;
