import { resolveRuntimeApiUrl } from '../../config/runtimeApiUrl';

interface DeptShape {
  id: string;
  name: string;
  code?: string | null;
  description?: string | null;
  isActive: boolean;
  sortOrder: number;
  createdAt?: string;
  updatedAt?: string;
  kind?: string;
  parentCode?: string | null;
}

interface StaffShape {
  id: string;
  username: string;
  email: string;
  fullName: string;
  firstName: string;
  lastName: string;
  role: string;
  departmentId?: string | null;
  departmentName: string;
  staffId?: string | null;
  phone?: string | null;
  isActive: boolean;
}

/** RMMS domain catalog — not Medical `/departments` + `/users`. */
const RMMS_DEPTS = '/integration/org-units';
const RMMS_USERS = '/integration/users';
const ORG_UNIT_PAGE_SIZES = [50, 100, 200, 500];

export function isRmmsOrgCatalog(): boolean {
  const flag = (import.meta.env.VITE_ORG_CATALOG_BACKEND as string | undefined)?.trim().toLowerCase();
  if (flag === 'rmms') return true;
  if (flag === 'medical') return false;
  const runtime = resolveRuntimeApiUrl(import.meta.env.VITE_API_URL as string | undefined);
  if (/rmms/i.test(runtime) || /localhost:5201/i.test(runtime)) return true;
  if (typeof window !== 'undefined' && /rmms/i.test(window.location.hostname)) return true;
  return false;
}

export function rewriteRmmsOrgPath(path: string): string {
  const qIndex = path.indexOf('?');
  const pathname = qIndex >= 0 ? path.slice(0, qIndex) : path;
  const search = qIndex >= 0 ? path.slice(qIndex + 1) : '';

  if (pathname === '/departments/stats') {
    return `${RMMS_DEPTS}?page=1&pageSize=200`;
  }

  let nextPath = pathname;
  if (nextPath === '/departments' || nextPath.startsWith('/departments/')) {
    nextPath = RMMS_DEPTS + nextPath.slice('/departments'.length);
  } else if (nextPath === '/users' || nextPath.startsWith('/users/')) {
    nextPath = RMMS_USERS + nextPath.slice('/users'.length);
  }

  const params = new URLSearchParams(search);
  if (nextPath === RMMS_DEPTS || nextPath.startsWith(`${RMMS_DEPTS}?`)) {
    const rawSize = Number(params.get('pageSize') || '50');
    if (!ORG_UNIT_PAGE_SIZES.includes(rawSize)) params.set('pageSize', '50');
    params.delete('includeInactive');
  }
  if (nextPath === RMMS_USERS || nextPath.startsWith(`${RMMS_USERS}?`)) {
    params.delete('includeInactive');
    params.delete('departmentId');
  }

  const qs = params.toString();
  return qs ? `${nextPath}?${qs}` : nextPath;
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' ? (value as Record<string, unknown>) : {};
}

function str(value: unknown): string {
  return value == null ? '' : String(value);
}

export function mapOrgUnitToDepartment(raw: unknown): DeptShape {
  const row = asRecord(raw);
  const kind = str(row.kind);
  return {
    id: str(row.id),
    name: str(row.name),
    code: str(row.code) || null,
    description: str(row.legacyAlias) || kind || null,
    isActive: row.isActive !== false,
    sortOrder: Number(row.sortOrder ?? 0),
    createdAt: str(row.createdAt) || undefined,
    updatedAt: str(row.updatedAt) || undefined,
    kind,
    parentCode: str(row.parentCode) || null,
  };
}

export function mapAppUserToStaff(raw: unknown): StaffShape {
  const row = asRecord(raw);
  const fullName = str(row.fullName);
  const parts = fullName.trim().split(/\s+/);
  const lastName = parts.pop() ?? '';
  const firstName = parts.join(' ');
  return {
    id: str(row.id),
    username: str(row.username),
    email: str(row.email),
    fullName,
    firstName,
    lastName,
    role: str(row.roleCode || row.role),
    departmentId: str(row.orgCode) || null,
    departmentName: str(row.orgCode),
    staffId: str(row.code || row.staffId) || null,
    phone: str(row.phone) || null,
    isActive: row.isActive !== false,
  };
}

export function mapRmmsOrgPayload<T>(path: string, data: T): T {
  if (!isRmmsOrgCatalog() || data == null || typeof data !== 'object') return data;
  const row = data as Record<string, unknown>;
  const items = row.items;
  if (Array.isArray(items) && path.includes(RMMS_DEPTS)) {
    return { ...row, items: items.map(mapOrgUnitToDepartment) } as T;
  }
  if (Array.isArray(items) && path.includes(RMMS_USERS)) {
    return { ...row, items: items.map(mapAppUserToStaff) } as T;
  }
  if (path.includes(`${RMMS_DEPTS}/`) && !Array.isArray(items) && row.id && row.name) {
    return mapOrgUnitToDepartment(data) as T;
  }
  if (path.includes(`${RMMS_USERS}/`) && !Array.isArray(items) && row.id && row.fullName) {
    return mapAppUserToStaff(data) as T;
  }
  return data;
}

function slugCode(name: string): string {
  const ascii = name
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^A-Za-z0-9]+/g, '')
    .slice(0, 12)
    .toUpperCase();
  return ascii || `OU${Date.now().toString(36).toUpperCase()}`;
}

export function toRmmsOrgUnitWrite(
  req: { name?: string; code?: string | null; isActive?: boolean },
  existingKind?: string,
) {
  const name = (req.name ?? '').trim();
  return {
    code: (req.code ?? '').trim() || slugCode(name),
    name,
    kind: (existingKind || 'ROOM').trim().toUpperCase(),
    parentCode: null as string | null,
    isActive: req.isActive !== false,
  };
}

export function toRmmsAppUserWrite(
  req: {
    fullName?: string;
    email?: string | null;
    staffId?: string | null;
    phone?: string | null;
    role?: string;
    isActive?: boolean;
    username?: string | null;
  },
  orgCode: string,
) {
  const fullName = (req.fullName ?? '').trim();
  const staffId = (req.staffId ?? '').trim();
  const email = (req.email ?? '').trim();
  const username =
    (req.username ?? '').trim() ||
    (email.includes('@') ? email.split('@')[0] : '') ||
    staffId ||
    slugCode(fullName).toLowerCase();
  return {
    username,
    fullName,
    email: email || `${username}@rmms.local`,
    phone: (req.phone ?? '').trim() || null,
    orgCode,
    roleCode: mapRoleToRmms(req.role),
    isActive: req.isActive,
  };
}

function mapRoleToRmms(role?: string | null): string {
  const raw = (role ?? '').trim();
  if (!raw) return 'Ban.TK';
  const lower = raw.toLowerCase();
  if (lower === 'staff') return 'Ban.TK';
  if (lower === 'manager') return 'Ban.QL';
  if (lower === 'admin') return 'Admin';
  return raw;
}
